window.TITANS_1000_QUOTES = [{"id": "01_altman", "ep": "01", "name": "Сем Альтман", "latin": "Sam Altman", "page_url": "episodes/ep01_altman.html", "avatar": "assets/avatars/sam_altman.jpg", "quotes_100": [{"num": 1, "cat": "Філософія майбутнього", "text": "«Ця машина розмила лінію між моїм внутрішнім світом і зовнішньою реальністю. Вона стала продовженням моєї думки».", "source": "Мастер-Досьє"}, {"num": 2, "cat": "Філософія майбутнього", "text": "«Коли ти сам голосно вимовляєш свою найуразливішу правду перед натовпом, у системи зникає будь-який важіль тиску на тебе».", "source": "Мастер-Досьє"}, {"num": 3, "cat": "Кризи та стійкість", "text": "«Більшість людей здаються не тому, що їхня ідея хибна, а тому, що не витримують психологічного тертя щоденних відмов».", "source": "Мастер-Досьє"}, {"num": 4, "cat": "Етика та безпека ШІ", "text": "«Ми не зможемо врятувати людство, якщо у нас банально не вистачить обчислювальних потужностей перевірити власні рівняння».", "source": "Мастер-Досьє"}, {"num": 5, "cat": "Кризи та стійкість", "text": "«Криза — це не кінець проєкту. Це просто примхливий сигнал про те, що ваш поточний алгоритм прийняття рішень вичерпав себе».", "source": "Мастер-Досьє"}, {"num": 6, "cat": "Лідерство та екосистема", "text": "«Бюджет стартапу — це запас кисню. Якщо ти не навчився дихати під водою, жоден інвестор не врятує тебе від утоплення».", "source": "Мастер-Досьє"}, {"num": 7, "cat": "Етика та безпека ШІ", "text": "«Люди катастрофічно недооцінюють ризик того, що вони стоятимуть на місці у світі, який змінюється зі швидкістю лави».", "source": "Мастер-Досьє"}, {"num": 8, "cat": "Архітектура та наука", "text": "«Справжня влада в технологіях належить не тим, хто пише гарні звіти, а тим, хто тримає рубильник енергії та чіпів».", "source": "Мастер-Досьє"}, {"num": 9, "cat": "Архітектура та наука", "text": "«Лінійний час — це пастка. Кремнієвий світ рухається за експонентою, і стояти на місці означає деградувати швидше за інших».", "source": "Мастер-Досьє"}, {"num": 10, "cat": "Кризи та стійкість", "text": "«Машина байдужа до авторитетів. Вона карає не за спробу, а лише за синтаксичну помилку — баг, який можна знайти і переписати за п'ять хвилин».", "source": "Мастер-Досьє"}, {"num": 11, "cat": "Експонента", "text": "Людський мозок еволюційно лінійний; здатність мислити експонентами — це рідкісна ментальна модель, що відокремлює архітекторів майбутнього.", "source": "Розширений корпус"}, {"num": 12, "cat": "Ірраціональна віра", "text": "«Якщо ви не вірите у власну здатність змінювати правила гри, ніхто за вас у це не повірить. Експонента винагороджує лише сміливих».", "source": "Розширений корпус"}, {"num": 13, "cat": "Перший Macintosh", "text": "«У 1993 році цей Macintosh LC II розмив лінію між моїм внутрішнім світом і всесвітом. Я зрозумів: світ не зафіксований назавжди. Його можна перепрограмувати».", "source": "Розширений корпус"}, {"num": 14, "cat": "Довгостроковий горизонт", "text": "«Більшість людей переоцінюють те, що можуть зробити за рік, і недооцінюють те, що здатні створити за десять років».", "source": "Розширений корпус"}, {"num": 15, "cat": "Справжній ризик", "text": "«Справжній ризик — це грати надто обережно, коли світ навколо вас рухається експоненціально».", "source": "Розширений корпус"}, {"num": 16, "cat": "Школа Y Combinator", "text": "Пол Грем навчив мене головного: робіть те, що потрібно користувачам, і ігноруйте статус-кво академічних авторитетів.", "source": "Розширений корпус"}, {"num": 17, "cat": "Психологічне тертя", "text": "Більшість людей здаються не тому, що їхня ідея хибна. Вони здаються, тому що не здатні витримати психологічне тертя щоденних відмов.", "source": "Розширений корпус"}, {"num": 18, "cat": "Не бійтеся амбіцій", "text": "Легше залучити ресурси під проект, який змінює цивілізацію, ніж під черговий дрібний сервіс доставки їжі.", "source": "Розширений корпус"}, {"num": 19, "cat": "Самостійне судження", "text": "Якщо ви рухаєтеся туди, де всі вже погоджуються з вами — ви вже запізнилися. Шукайте правду в точках найбільшого опору консенсусу.", "source": "Розширений корпус"}, {"num": 20, "cat": "Швидкість як стратегія", "text": "Висока швидкість ітерацій б'є будь-яке повільне планування. Той, хто помиляється вдесятеро швидше, виграє ринок.", "source": "Розширений корпус"}, {"num": 21, "cat": "Знищення застарілого", "text": "«Ніколи не оптимізуйте те, що має бути повністю знищено та перебудовано з нуля».", "source": "Розширений корпус"}, {"num": 22, "cat": "Ціна комфорту", "text": "Комфорт — це головний вбивця великих амбіцій. Найкращі речі створюються в стані контрольованого дискомфорту.", "source": "Розширений корпус"}, {"num": 23, "cat": "Мережеві ефекти", "text": "Справжня монополія в технологіях будується на накопиченні користувацької цінності та мережевих ефектах експоненти.", "source": "Розширений корпус"}, {"num": 24, "cat": "Відбір талантів", "text": "Один надзвичайний інженер вартий п'ятдесяти посередніх. Будуйте команди з людей, які мають іскру фанатизму.", "source": "Розширений корпус"}, {"num": 25, "cat": "Культура ультиматумів", "text": "Коли ви впевнені у фундаментальному законі природи — не йдіть на компроміси заради спокою ради директорів.", "source": "Розширений корпус"}, {"num": 26, "cat": "Зосередженість на істині", "text": "Світ щодня переконуватиме вас у вашій пересічності. Ваше завдання — ігнорувати шум і фокусуватися на сигналі.", "source": "Розширений корпус"}, {"num": 27, "cat": "Право на сміливість", "text": "У 16 років публічний камінг-аут перед християнською школою навчив мене: якщо ви боїтеся бути собою, ви ніколи не зможете очолити революцію.", "source": "Розширений корпус"}, {"num": 28, "cat": "Уроки Стенфорду", "text": "Я кинув Стенфорд не тому, що навчання було поганим, а тому, що реальний світ вимагав негайної дії.", "source": "Розширений корпус"}, {"num": 29, "cat": "Досвід Loopt", "text": "Loopt продав за $43.4 млн. Це був скромний фінансовий результат, але це була безцінна школа інженерії волі.", "source": "Розширений корпус"}, {"num": 30, "cat": "Сміливість ставити все", "text": "Тільки ті, хто готові ризикнути всім своїм капіталом і репутацією, здатні відкрити новий технологічний уклад.", "source": "Розширений корпус"}, {"num": 31, "cat": "Етика переможця", "text": "Справжня перемога — це створення інфраструктури, яка піднімає рівень життя всього людства.", "source": "Розширений корпус"}, {"num": 32, "cat": "Відсікання токсичності", "text": "Якщо людина в команді не вірить у спільну місію на 100% — прощайтеся з нею негайно.", "source": "Розширений корпус"}, {"num": 33, "cat": "Рівень рішучості", "text": "Рішучість (resoluteness) — це якість номер один для лідера експоненціальної компанії.", "source": "Розширений корпус"}, {"num": 34, "cat": "Ментальна стійкість", "text": "Критики забудуть свої слова через місяць. Ваші результати залишаться в коді назавжди.", "source": "Розширений корпус"}, {"num": 35, "cat": "Концентрація зусиль", "text": "Справжній успіх — це результат звуження фокусу до однієї точки найвищого тиску.", "source": "Розширений корпус"}, {"num": 36, "cat": "Народження OpenAI", "text": "У грудні 2015 року ми заснували OpenAI як некомерційну противагу монополізації ШІ однією корпорацією.", "source": "Розширений корпус"}, {"num": 37, "cat": "Обчислювальний імператив", "text": "«Ми не зможемо врятувати світ, якщо у нас банально не вистачить обчислювальних потужностей перевірити власні рівняння».", "source": "Розширений корпус"}, {"num": 38, "cat": "Трансформація capped-profit", "text": "Ідеалізм без капіталу безпорадний. Щоб побудувати суперкомп'ютери для AGI, ми мали залучити мільярди доларів.", "source": "Розширений корпус"}, {"num": 39, "cat": "Союз із Microsoft", "text": "Партнерство з Сатьєю Наделою дало нам необхідні хмарні кластери Azure, які перетворили дослідження на реальність.", "source": "Розширений корпус"}, {"num": 40, "cat": "Магія GPT-3", "text": "Коли GPT-3 почав писати код і розмірковувати, скептики зрозуміли: закон масштабування працює безвідмовно.", "source": "Розширений корпус"}, {"num": 41, "cat": "ChatGPT як момент біфуркації", "text": "30 листопада 2022 року світ змінився назавжди. Інтерфейс чату зробив штучний інтелект відчутним для кожного.", "source": "Розширений корпус"}, {"num": 42, "cat": "Суть AGI", "text": "AGI — це не одна програма. Це система, здатна самостійно генерувати нові наукові знання швидше за все людство.", "source": "Розширений корпус"}, {"num": 43, "cat": "Зміна економіки", "text": "Вартість інтелекту впаде майже до нуля. Головними обмежувачами залишаться енергія та кремній.", "source": "Розширений корпус"}, {"num": 44, "cat": "Демократизація інструментів", "text": "ШІ має бути персональним суперінтелектуальним помічником кожного студента, лікаря та інженера на Землі.", "source": "Розширений корпус"}, {"num": 45, "cat": "Відкритість проти закритості", "text": "Безпека AGI вимагає поступового релізу (iterative deployment), щоб суспільство встигало адаптуватися до змін.", "source": "Розширений корпус"}, {"num": 46, "cat": "Проблема узгодження", "text": "Вирівнювання суперінтелекту з людськими цінностями — це найважливіша математична та філософська проблема століття.", "source": "Розширений корпус"}, {"num": 47, "cat": "Закон масштабування обчислень", "text": "Кожне десятикратне збільшення обчислень відкриває нові якісні властивості моделей.", "source": "Розширений корпус"}, {"num": 48, "cat": "Смерть вузьких моделей", "text": "Ера спеціалізованих нейромереж добігла кінця; мультимодальні фундаментальні моделі поглинають усі окремі завдання.", "source": "Розширений корпус"}, {"num": 49, "cat": "Співпраця з Ілоном Маском", "text": "Ілон допоміг запустити OpenAI, але коли він зажадав тотального контролю, ми обрали автономію місії.", "source": "Розширений корпус"}, {"num": 50, "cat": "Капіталомісткість майбутнього", "text": "Для навчання AGI наступного покоління знадобляться дата-центри вартістю у сотні мільярдів доларів.", "source": "Розширений корпус"}, {"num": 51, "cat": "Еволюція інтерфейсів", "text": "Текстовий промпт — це лише перший крок; майбутнє за мультимодальною присутністю і голосовим симбіозом.", "source": "Розширений корпус"}, {"num": 52, "cat": "Науковий прорив як мета", "text": "Якщо AGI не здатний винайти термоядерний синтез і вилікувати рак — ми збудували недостатньо потужну систему.", "source": "Розширений корпус"}, {"num": 53, "cat": "Суверенітет розуму", "text": "Людство не повинно залежати від рішень однієї компанії; саме тому ми будуємо відкриті API для всього світу.", "source": "Розширений корпус"}, {"num": 54, "cat": "Швидкість адаптації соціуму", "text": "Суспільство дивовижно швидко звикає до чудес: те, що вчора здавалося магією, сьогодні стає буденним інструментом.", "source": "Розширений корпус"}, {"num": 55, "cat": "Приборкання галюцинацій", "text": "Галюцинації — це зворотний бік творчої уяви моделі; системне міркування (o1) навчає ШІ перевіряти факти.", "source": "Розширений корпус"}, {"num": 56, "cat": "Проблема енергетичного дефіциту", "text": "Наступна фаза масштабування ШІ вимагатиме нової атомної енергетики та сонячних кластерів.", "source": "Розширений корпус"}, {"num": 57, "cat": "Інвестиції в Helion Energy", "text": "Я інвестував у ядерний термояд, тому що без чистих гігаватів ми не зможемо живити кластери майбутнього.", "source": "Розширений корпус"}, {"num": 58, "cat": "Інвестиції в Retro Biosciences", "text": "ШІ продовжить продуктивне життя людини на десятки років — саме тому біотех є невіддільним від нашої місії.", "source": "Розширений корпус"}, {"num": 59, "cat": "Модель о1 та мислення", "text": "Перехід від генерації слів до ланцюжків міркувань (Chain of Thought) — це народження справжнього логічного агента.", "source": "Розширений корпус"}, {"num": 60, "cat": "Горизонт автономних агентів", "text": "Через два роки агенти виконуватимуть складні багатокрокові інженерні завдання без прямого контролю людини.", "source": "Розширений корпус"}, {"num": 61, "cat": "Удар 17 листопада", "text": "Рада директорів звільнила мене у п'ятницю через Google Meet. Це був класичний корпоративний саботаж під маскою безпеки.", "source": "Розширений корпус"}, {"num": 62, "cat": "Мовчання і концентрація", "text": "У перші години після звільнення головне було не піддатися гніву, а оцінити конфігурацію сил на дошці.", "source": "Розширений корпус"}, {"num": 63, "cat": "Ультиматум команди", "text": "«Коли 730 із 770 співробітників підписали лист із вимогою мого повернення, я зрозумів: компанію тримають не статути, а спільна віра».", "source": "Розширений корпус"}, {"num": 64, "cat": "Роль Сатьї Наделли", "text": "Microsoft проявила абсолютну вірність партнерству, запропонувавши створити нову лабораторію для всієї команди OpenAI.", "source": "Розширений корпус"}, {"num": 65, "cat": "Психологія тиску", "text": "Найболючіші удари завжди завдають ті, з ким ви ділили хліб у підвалі стартапу. Пробачте їх і рухайтеся далі.", "source": "Розширений корпус"}, {"num": 66, "cat": "Перемога відкритості", "text": "Таємні змови в закритих кімнатах більше не працюють у цифрову епоху: публічність стала нашою головною зброєю.", "source": "Розширений корпус"}, {"num": 67, "cat": "Тріумф повернення", "text": "22 листопада я повернувся на посаду CEO з новою радою директорів — Ларрі Саммерсом та Бретом Тейлором.", "source": "Розширений корпус"}, {"num": 68, "cat": "Очищення культури", "text": "Криза виявила приховані тріщини і дозволила перебудувати управління компанією на рівень світових корпорацій.", "source": "Розширений корпус"}, {"num": 69, "cat": "Урок стійкості", "text": "Лідер пізнається не в момент запуску успішного продукту, а в момент, коли весь світ вважає його кар'єру завершеною.", "source": "Розширений корпус"}, {"num": 70, "cat": "Людський фактор", "text": "Жоден алгоритм не замінить щирої довіри між людьми, які щодня будують майбутнє пліч-о-пліч.", "source": "Розширений корпус"}, {"num": 71, "cat": "Відповідальність перед інвесторами", "text": "Ми довели, що здатні захистити капітал та інтереси партнерів навіть у стані максимального шторму.", "source": "Розширений корпус"}, {"num": 72, "cat": "Ціна публічності", "text": "Коли ви керуєте компанією в центрі світової уваги, будь-який ваш крок розглядається під мікроскопом історії.", "source": "Розширений корпус"}, {"num": 73, "cat": "Фокус на продукті", "text": "Під час кризи ми не зупинили сервери ані на секунду; безперервність сервісу для 100 млн користувачів була законом.", "source": "Розширений корпус"}, {"num": 74, "cat": "Провал палацового перевороту", "text": "Ідеологи, які відірвані від реального інженерного процесу, завжди програють практикам, які будують продукт.", "source": "Розширений корпус"}, {"num": 75, "cat": "Нова рада директорів", "text": "Ми залучили важковаговиків світової економіки та безпеки, щоб OpenAI мала фундамент для наступного стрибка.", "source": "Розширений корпус"}, {"num": 76, "cat": "Прощення опонентів", "text": "Я не тримаю зла на членів колишньої ради; вони діяли з власних переконань, хоча їхні методи були згубними.", "source": "Розширений корпус"}, {"num": 77, "cat": "Збереження темпу", "text": "Головний ризик кризи полягав у втраті ініціативи перед Google та Anthropic; ми компенсували це подвійною швидкістю.", "source": "Розширений корпус"}, {"num": 78, "cat": "Культура міцного ядра", "text": "Після листопада 2023 року наша команда стала монолітом, який неможливо розколоти зовнішнім тиском.", "source": "Розширений корпус"}, {"num": 79, "cat": "Смирення після тріумфу", "text": "Повернення не було приводом для пихи; це було нагадуванням про те, наскільки тендітною є будь-яка організація.", "source": "Розширений корпус"}, {"num": 80, "cat": "Інституційна пам'ять", "text": "Ми записали кожен крок кризи, щоб створити протоколи антикризового реагування на майбутні виклики.", "source": "Розширений корпус"}, {"num": 81, "cat": "Стійкість до критики преси", "text": "Заголовки медіа змінюються кожні 48 годин; єдине, що має значення — це реліз коду і стабільність моделей.", "source": "Розширений корпус"}, {"num": 82, "cat": "Захист дослідників", "text": "Моє головне завдання як CEO — бути кремнієвим щитом між геніальними вченими та хаосом зовнішньої політики.", "source": "Розширений корпус"}, {"num": 83, "cat": "Довіра користувачів", "text": "Користувачі підтримали нас, тому що ChatGPT став для них незамінним щоденним помічником у праці.", "source": "Розширений корпус"}, {"num": 84, "cat": "Перезапуск місії", "text": "Листопад показав: наша мета надто велика, щоб дозволити дрібним внутрішнім амбіціям зупинити прогрес.", "source": "Розширений корпус"}, {"num": 85, "cat": "Погляд за горизонт", "text": "Коли шторм вщух, ми повернулися до головного питання: як забезпечити енергетичний базис для появи AGI.", "source": "Розширений корпус"}, {"num": 86, "cat": "Проект Stargate", "text": "«Створення Stargate — кластера вартістю $100 мільярдів — це не примха, це фізична вимога наступного покоління моделей».", "source": "Розширений корпус"}, {"num": 87, "cat": "Енергія як валюта", "text": "«Головна валюта майбутнього — це обчислення та гігавати чистої енергії. Той, хто контролює кремній і вольти, формує архітектуру мислення».", "source": "Розширений корпус"}, {"num": 88, "cat": "Закон Мура проти закону енергії", "text": "Транзистори більше не стають дешевше автоматично; тепер ми повинні будувати цілі електростанції поруч із дата-центрами.", "source": "Розширений корпус"}, {"num": 89, "cat": "Термоядерний горизонт", "text": "Справжній екологічний ШІ стане можливим лише тоді, коли запрацюють перші комерційні реактори синтезу.", "source": "Розширений корпус"}, {"num": 90, "cat": "Чіпи власної розробки", "text": "Залежність від одного постачальника GPU — це вузьке горло для цивілізації; ми повинні диверсифікувати кремнієву базу.", "source": "Розширений корпус"}, {"num": 91, "cat": "ШІ та науковий метод", "text": "AGI прискорить науковий пошук у тисячі разів: від синтезу надпровідників до квантової хімії.", "source": "Розширений корпус"}, {"num": 92, "cat": "Пост-дефіцитна економіка", "text": "Коли інтелект і праця стануть дешевими, людство вперше в історії позбудеться проблеми матеріального дефіциту.", "source": "Розширений корпус"}, {"num": 93, "cat": "Універсальний базовий дохід", "text": "ШІ згенерує колосальне багатство; Worldcoin та цифрова ідентичність — це спроба підготувати механізми перерозподілу.", "source": "Розширений корпус"}, {"num": 94, "cat": "Нова роль людини", "text": "Людина не зникне з ринку праці, але перейде на рівень формулювання сенсів, етики та естетичних векторів.", "source": "Розширений корпус"}, {"num": 95, "cat": "Глобальне регулювання", "text": "Ми підтримуємо створення міжнародного агентства на зразок МАГАТЕ для моніторингу найпотужніших навчальних кластерів.", "source": "Розширений корпус"}, {"num": 96, "cat": "Геополітичні перегони", "text": "Демократичний світ зобов'язаний виграти перегони за AGI, інакше авторитарні моделі нав'яжуть цифрову цензуру планеті.", "source": "Розширений корпус"}, {"num": 97, "cat": "ШІ у медицині", "text": "Кожна людина отримає рівень медичної консультації найкращого консиліуму лікарів прямо у своєму смартфоні.", "source": "Розширений корпус"}, {"num": 98, "cat": "Освіта майбутнього", "text": "Індивідуальний ШІ-тьютор адаптуватиме подачу матеріалу під нейропластичність кожної дитини.", "source": "Розширений корпус"}, {"num": 99, "cat": "Масштабування вирівнювання", "text": "Ми будемо використовувати слабкі моделі для перевірки і вирівнювання надпотужних систем наступного покоління.", "source": "Розширений корпус"}, {"num": 100, "cat": "Сингулярність без містики", "text": "Сингулярність — це не кінець світу, це просто точка, де швидкість технологічних інновацій перевищує швидкість адаптації старих інститутів.", "source": "Розширений корпус"}]}, {"id": "02_huang", "ep": "02", "name": "Дженсен Хуанг", "latin": "Jensen Huang", "page_url": "episodes/ep02_huang.html", "avatar": "assets/avatars/jensen_huang.jpg", "quotes_100": [{"num": 1, "cat": "Походження та гарт", "text": "«Ви не уявляєте, як ретельно я чистив ті туалети. Це назавжди випалило з моєї душі пиху. Не буває низької праці — буває лише ліниве виконання».", "source": "Мастер-Досьє"}, {"num": 2, "cat": "Кризи та стійкість", "text": "«Панове, не забувайте: до нашого банкрутства завжди залишається рівно тридцять днів».", "source": "Мастер-Досьє"}, {"num": 3, "cat": "Лідерство та екосистема", "text": "«Ми не орієнтуємося на поточний ринок. Ми будуємо ринок, розмір якого сьогодні дорівнює нулю мільярдів доларів, але завтра дорівнюватиме всій світовій економіці».", "source": "Мастер-Досьє"}, {"num": 4, "cat": "Кризи та стійкість", "text": "«Ви маєте надто високі очікування і надто низьку стійкість. А тому я від щирого серця бажаю вам великих порцій болю і страждань».", "source": "Мастер-Досьє"}, {"num": 5, "cat": "Філософія майбутнього", "text": "«Велич народжується не з інтелекту чи червоного диплома. Велич народжується з характеру, який кується тоді, коли ваші плани летять у прірву».", "source": "Мастер-Досьє"}, {"num": 6, "cat": "Філософія майбутнього", "text": "«Не бійтеся зізнатися партнерам у тому, що ваш продукт хибний, якщо це збереже головне — абсолютну чесність і довіру».", "source": "Мастер-Досьє"}, {"num": 7, "cat": "Філософія майбутнього", "text": "«Будь-яку рутинну роботу можна перетворити на високе ремесло, якщо підійти до неї з інженерною точністю».", "source": "Мастер-Досьє"}, {"num": 8, "cat": "Філософія майбутнього", "text": "«Складність і опір середовища — це ваш єдиний надійний захисний рів від ледачих конкурентів».", "source": "Мастер-Досьє"}, {"num": 9, "cat": "Лідерство та екосистема", "text": "«Якщо інформація в компанії проходить через п'ять поверхів начальників — правда вмирає по дорозі».", "source": "Мастер-Досьє"}, {"num": 10, "cat": "Лідерство та екосистема", "text": "«Справжній лідер не ховається в кабінеті. Він сидить за загальним столом поруч із командою біля брудної білої дошки».", "source": "Мастер-Досьє"}, {"num": 11, "cat": "Філософія страждання", "text": "«Я бажаю вам достатньо болю і страждань. Тому що саме страждання формують характер, а характер формує долю величних компаній».", "source": "Розширений корпус"}, {"num": 12, "cat": "Школа Denny's", "text": "«У 15 років я працював посудомийником у закусочній Denny's у Портленді. Я чистив туалети і мив посуд краще за всіх у світі. Це навчило мене гідності ремесла».", "source": "Розширений корпус"}, {"num": 13, "cat": "Баптистський інтернат", "text": "Oneida Baptist Institute у Кентуккі загартував мене: коли ти 9-річний іммігрант без знання мови чистиш вбиральні, ти вчишся виживати за будь-яких умов.", "source": "Розширений корпус"}, {"num": 14, "cat": "Постійний страх краху", "text": "«Ми завжди були за 30 днів до банкрутства. Цей щоденний страх — найкраще паливо для інновацій та захисту від закостеніння».", "source": "Розширений корпус"}, {"num": 15, "cat": "Витривалість (Grit)", "text": "Інтелект переоцінений; витривалість (grit) — це головний предиктор довгострокового тріумфу в інженерії та бізнесі.", "source": "Розширений корпус"}, {"num": 16, "cat": "Ставлення до праці", "text": "«Байдуже, чи миєте ви посуд у нічній забігайлівці, чи проектуєте чіп на 200 мільярдів транзисторів — робіть це так, ніби від кожної дії залежить всесвіт».", "source": "Розширений корпус"}, {"num": 17, "cat": "Стійкість до невдач", "text": "Помилки — це не привід для сорому. Це просто безкоштовні уроки фізики та ринку.", "source": "Розширений корпус"}, {"num": 18, "cat": "Культура прямоти", "text": "В NVIDIA немає кабінетної бюрократії. Я можу зайти в будь-яку лабораторію і поговорити з молодшим інженером напряму.", "source": "Розширений корпус"}, {"num": 19, "cat": "Пласка структура", "text": "У мене 50 прямих підлеглих. Що менше рівнів менеджменту між лідером та інженером, то чистіший сигнал.", "source": "Розширений корпус"}, {"num": 20, "cat": "Біжи, а не йди", "text": "«Біжи, не йди. Або ти біжиш за їжею, або біжиш, щоб самому не стати чиєюсь їжею».", "source": "Розширений корпус"}, {"num": 21, "cat": "Настільний теніс", "text": "Третє місце на юніорському чемпіонаті США з пінг-понгу навчило мене мікросекундній реакції та нещадному фокусу на м'ячі.", "source": "Розширений корпус"}, {"num": 22, "cat": "Шкіряна куртка як форма", "text": "Я ношу однаковий чорний одяг і шкіряну куртку, щоб не витрачати ані секунди ранкової енергії на вибір гардеробу.", "source": "Розширений корпус"}, {"num": 23, "cat": "Смирення лідера", "text": "Генеральний директор не повинен бути вельможею. Він повинен бути головним розв'язувачем проблем у компанії.", "source": "Розширений корпус"}, {"num": 24, "cat": "Здатність терпіти біль", "text": "Успіх вимірюється не тим, скільки грошей ви заробили, а тим, скільки агонії ви змогли витримати на шляху до мети.", "source": "Розширений корпус"}, {"num": 25, "cat": "Відмова від консенсусу", "text": "Якщо аналітики Уолл-стріт хвалять вашу стратегію, ви робите щось очевидне і банальне.", "source": "Розширений корпус"}, {"num": 26, "cat": "Гартування кризами", "text": "Криза 1995 року, коли чіп NV1 провалився, навчила мене дивитися смерті компанії в очі без паніки.", "source": "Розширений корпус"}, {"num": 27, "cat": "Рятівний дзвінок Sega", "text": "Я чесно зізнався генеральному директору Sega у провалі архітектури NV1, і він дав нам $5 млн авансу на RIVA 128 за нашу чесність.", "source": "Розширений корпус"}, {"num": 28, "cat": "Уроки Denny's 1993", "text": "NVIDIA народилася за столиком Denny's за чашкою безкоштовної кави. Справжні революції починаються в скромних місцях.", "source": "Розширений корпус"}, {"num": 29, "cat": "Чесність перед клієнтом", "text": "Ніколи не продавайте клієнту те, у що самі не вірите всім серцем.", "source": "Розширений корпус"}, {"num": 30, "cat": "Сила оптимізму", "text": "Песимісти мають рацію у деталях, але оптимісти будують нові галактики.", "source": "Розширений корпус"}, {"num": 31, "cat": "Ціна компромісу", "text": "Краще зазнати чистої інженерної поразки, ніж випустити посередній компромісний продукт.", "source": "Розширений корпус"}, {"num": 32, "cat": "Щоденний перезапуск", "text": "Щоранку я прокидаюся з думкою, що компанію треба рятувати знову з чистого аркуша.", "source": "Розширений корпус"}, {"num": 33, "cat": "Свобода від его", "text": "Визнати, що ти витратив три роки на хибну архітектуру і спалити її — це найвища форма мужності.", "source": "Розширений корпус"}, {"num": 34, "cat": "Довіра до команди", "text": "Якщо ви наймаєте найкращих у світі людей, не вказуйте їм кожен крок — дайте їм свободу творити дива.", "source": "Розширений корпус"}, {"num": 35, "cat": "Інженерний стоїцизм", "text": "Закони термодинаміки неможливо підкупити маркетингом. Будуйте на фундаментальній фізиці.", "source": "Розширений корпус"}, {"num": 36, "cat": "Винахід GPU", "text": "У 1999 році ми винайшли GeForce 256 — перший у світі графічний процесор, який звільнив комп'ютер від рамок 2D.", "source": "Розширений корпус"}, {"num": 37, "cat": "Паралельна парадигма", "text": "Центральний процесор (CPU) — це швидкий літак, а графічний процесор (GPU) — це армія з мільйона мурах, здатних зрушити гори.", "source": "Розширений корпус"}, {"num": 38, "cat": "Фізика 3D графіки", "text": "Тривимірна графіка вимагала мільярдів обчислень матриць одночасно; це був ідеальний тренажер для майбутнього ШІ.", "source": "Розширений корпус"}, {"num": 39, "cat": "Тріумф RIVA 128", "text": "У 1997 році чіп RIVA 128 врятував компанію від банкрутства і встановив стандарт швидкості для всієї індустрії ПК.", "source": "Розширений корпус"}, {"num": 40, "cat": "Смерть 3dfx", "text": "Купівля активів 3dfx Voodoo довела: перемагає не культовий бренд, а безжальна інженерна дисципліна випуску чіпів кожні 6 місяців.", "source": "Розширений корпус"}, {"num": 41, "cat": "Ставка на DirectX", "text": "Ми тісно співпрацювали з Microsoft, щоб зробити апаратне 3D-прискорення серцем кожної операційної системи Windows.", "source": "Розширений корпус"}, {"num": 42, "cat": "Термодинамічний бар'єр", "text": "Закон Деннарда помер 15 років тому: центральні процесори вперлися у перегрів, і єдиним виходом став паралелізм.", "source": "Розширений корпус"}, {"num": 43, "cat": "Шейдерна революція", "text": "Програмовані шейдери в GeForce 3 перетворили GPU з фіксованого конвеєра на універсальний математичний інструмент.", "source": "Розширений корпус"}, {"num": 44, "cat": "Кремнієвий закон", "text": "Чим більше транзисторів ви можете ефективно змусити працювати паралельно, тим ближче ви до імітації нейронів мозку.", "source": "Розширений корпус"}, {"num": 45, "cat": "Інтеграція пам'яті", "text": "Обчислення без пропускної здатності пам'яті марні; HBM пам'ять стала такою ж важливою, як і самі ядра.", "source": "Розширений корпус"}, {"num": 46, "cat": "Швидкість як конкурентна перевага", "text": "Ми скоротили цикл проектування суперчіпів з чотирьох років до вісімнадцяти місяців.", "source": "Розширений корпус"}, {"num": 47, "cat": "Фізика світла (Ray Tracing)", "text": "У 2018 році з запуском RTX ми поставили на апаратне трасування променів у реальному часі, коли всі казали, що це неможливо ще 10 років.", "source": "Розширений корпус"}, {"num": 48, "cat": "Нейрорендерінг DLSS", "text": "Традиційний рендеринг пікселів мертвий; тепер ми генеруємо картинку за допомогою нейромереж у реальному часі.", "source": "Розширений корпус"}, {"num": 49, "cat": "Співпраця з TSMC", "text": "Морріс Чанг став моїм наставником і братом по зброї. Без літографії TSMC революція NVIDIA була б неможливою.", "source": "Розширений корпус"}, {"num": 50, "cat": "Упаковка чіпів CoWoS", "text": "Передова упаковка кремнію (Chip-on-Wafer-on-Substrate) стала новим полем битви за продуктивність.", "source": "Розширений корпус"}, {"num": 51, "cat": "Оптимізація інженерного стеку", "text": "Ми проектуємо не просто чіп — ми проектуємо транзистори, підкладку, оптоволокно, сервери та софт як єдине ціле.", "source": "Розширений корпус"}, {"num": 52, "cat": "Подолання фізичних меж", "text": "Коли довжина хвилі світла стала більшою за елементи чіпа, ми застосували обчислювальну літографію на GPU.", "source": "Розширений корпус"}, {"num": 53, "cat": "Кремній як мистецтво", "text": "Погляньте на кристал Blackwell під мікроскопом: 208 мільярдів транзисторів рухаються в ідеальному танці зі швидкістю світла.", "source": "Розширений корпус"}, {"num": 54, "cat": "Справжня ціна кремнію", "text": "Кожна пластина коштує десятки тисяч доларів, і одна порошинка може знищити чіп; тут немає місця недбалості.", "source": "Розширений корпус"}, {"num": 55, "cat": "Перегони мікронів", "text": "Перехід від мікронів до нанометрів вимагав мільярдних ставок на обладнання ASML Extreme Ultraviolet.", "source": "Розширений корпус"}, {"num": 56, "cat": "Енергоефективність архітектури", "text": "Продуктивність на ват — це єдина метрика, яка має значення для суперкомп'ютерів наступного століття.", "source": "Розширений корпус"}, {"num": 57, "cat": "Провал NV1 як благословення", "text": "Якби наш перший чіп був успішним, ми б ніколи не створили GPU. Невдача змусила нас переосмислити все.", "source": "Розширений корпус"}, {"num": 58, "cat": "Партнерство з геймерами", "text": "Геймери всього світу фінансували наші дослідження протягом 20 років, перш ніж з'явився штучний інтелект.", "source": "Розширений корпус"}, {"num": 59, "cat": "Гідність інженера", "text": "Інженер — це людина, яка змушує пісок (кремній) думати і розмовляти.", "source": "Розширений корпус"}, {"num": 60, "cat": "Вірність парадигмі", "text": "Ми трималися за ідею прискорених обчислень тридцять років, коли весь ринок вважав це нішевою забавкою.", "source": "Розширений корпус"}, {"num": 61, "cat": "Запуск CUDA 2006", "text": "«У 2006 році ми інтегрували CUDA в кожен наш чіп безкоштовно. Це коштувало нам мільярдів доларів і обвалило акції, але створило сучасний ШІ».", "source": "Розширений корпус"}, {"num": 62, "cat": "Zero-Billion-Dollar Markets", "text": "«Ніколи не йдіть туди, де вже штовхаються конкуренти. Шукайте ринки, які оцінюються у нуль доларів, і створюйте нові галузі з нуля».", "source": "Розширений корпус"}, {"num": 63, "cat": "Уолл-стріт проти CUDA", "text": "Аналітики благали мене вилучити блоки CUDA і знизити собівартість. Якби я їх послухав, ШІ-революція затрималася б на 15 років.", "source": "Розширений корпус"}, {"num": 64, "cat": "DGX-1 для OpenAI", "text": "У 2016 році я особисто привіз у Сан-Франциско перший суперкомп'ютер DGX-1 і підписав його для Ілона Маска та Сема Альтмана.", "source": "Розширений корпус"}, {"num": 65, "cat": "Апаратний симбіоз з AlexNet", "text": "Коли Хінтон і Суцкевер запустили AlexNet на двох геймерських картах GTX 580, ми зрозуміли: настав наш зоряний час.", "source": "Розширений корпус"}, {"num": 66, "cat": "Швидкість як екосистема", "text": "CUDA — це не просто мова програмування. Це мільйони бібліотек (cuDNN, TensorRT), які неможливо скопіювати за один день.", "source": "Розширений корпус"}, {"num": 67, "cat": "Монополія користі", "text": "Конкуренти намагаються скопіювати наше залізо, але вони не розуміють: справжня цінність полягає в екосистемі програмного забезпечення.", "source": "Розширений корпус"}, {"num": 68, "cat": "Математика матричного множення", "text": "Штучний інтелект у своїй основі — це гігантське множення матриць. Ми оптимізували Tensor Cores саме під цю операцію.", "source": "Розширений корпус"}, {"num": 69, "cat": "Інвестиції у збиткові роки", "text": "Десять років поспіль інвестори карали наші акції за інвестиції в наукові обчислення. Ми вистояли завдяки вірі у фізику.", "source": "Розширений корпус"}, {"num": 70, "cat": "Перетворення GPU на AI суперкомп'ютер", "text": "Один сервер більше не є одиницею обчислень; одиницею став дата-центр з 100 000 з'єднаних чіпів.", "source": "Розширений корпус"}, {"num": 71, "cat": "Культура відкритості для вчених", "text": "Ми роздавали плати університетам безкоштовно, щоб виростити покоління дослідників, які вміють писати код для GPU.", "source": "Розширений корпус"}, {"num": 72, "cat": "Перехід від графіки до науки", "text": "Моделювання згортання білків, астрофізика, прогноз клімату — все це перейшло на CUDA задовго до появи ChatGPT.", "source": "Розширений корпус"}, {"num": 73, "cat": "Захисний рів екосистеми", "text": "Справжній рів (moat) — це не патенти. Це чотири мільйони розробників, які звикли думати в термінах нашої платформи.", "source": "Розширений корпус"}, {"num": 74, "cat": "Сміливість створювати попит", "text": "Ми створили обчислювальну потужність для генеративного ШІ ще до того, як світ зрозумів, що йому потрібен генеративний ШІ.", "source": "Розширений корпус"}, {"num": 75, "cat": "Сила стандартизації", "text": "Той самий код, написаний для ноутбука розробника, працює на кластері з десяти тисяч GPU в дата-центрі.", "source": "Розширений корпус"}, {"num": 76, "cat": "Створення платформи Omniverse", "text": "Omniverse — це цифровий двійник реальності для навчання роботів і тестування автономних фабрик.", "source": "Розширений корпус"}, {"num": 77, "cat": "Смерть CPU у навчанні ШІ", "text": "Використовувати CPU для навчання сучасних LLM — це те саме, що намагатися викопати тунель чайною ложкою.", "source": "Розширений корпус"}, {"num": 78, "cat": "Трансформація компанії", "text": "Ми перестали бути компанією чіпів і стали компанією інфраструктури обчислювальних платформ.", "source": "Розширений корпус"}, {"num": 79, "cat": "Мережевий комутатор Quantum InfiniBand", "text": "Купівля Mellanox за $6.9 млрд була геніальним кроком: передача даних між GPU стала швидшою за шини материнської плати.", "source": "Розширений корпус"}, {"num": 80, "cat": "Ціна терпіння", "text": "Терпіння в інженерії — це здатність щодня копати колодязь, навіть коли перші краплі води з'являться через десять років.", "source": "Розширений корпус"}, {"num": 81, "cat": "Закон масштабування інфраструктури", "text": "Подвоєння кількості чіпів у кластері повинно давати лінійне прискорення навчання без втрат на синхронізацію.", "source": "Розширений корпус"}, {"num": 82, "cat": "Довіра наукової спільноти", "text": "Вчені обирають NVIDIA, тому що наш код не підводить у критичний момент багатомісячного тренування моделей.", "source": "Розширений корпус"}, {"num": 83, "cat": "Сміливість великих ставок", "text": "Ми поставили все майбутнє компанії на CUDA у 2006 році. Це був найбільший ва-банк в історії кремнієвої долини.", "source": "Розширений корпус"}, {"num": 84, "cat": "Магія паралелізму", "text": "Коли тисячі ядер одночасно оновлюють ваги нейромережі, ви чуєте гул народження нової цифрової свідомості.", "source": "Розширений корпус"}, {"num": 85, "cat": "Служіння науковому прогресу", "text": "NVIDIA існує для того, щоб розв'язувати задачі, які звичайні комп'ютери не здатні вирішити в принципі.", "source": "Розширений корпус"}, {"num": 86, "cat": "Закон Хуанга", "text": "«Закон Мура помер. Закон Хуанга доводить: синергія чіпів, софту, мереж та охолодження збільшує продуктивність у 1000 разів за 8 років».", "source": "Розширений корпус"}, {"num": 87, "cat": "ШІ як промислова революція", "text": "«Штучний інтелект — це не програмне забезпечення. Це нова промислова епоха, де дата-центри перетворюють енергію на токени інтелекту».", "source": "Розширений корпус"}, {"num": 88, "cat": "ШІ-фабрики майбутнього", "text": "У 19 столітті фабрики виробляли текстиль і сталь завдяки паровим двигунам. Сьогодні ШІ-фабрики виробляють знання.", "source": "Розширений корпус"}, {"num": 89, "cat": "Суверенний ШІ", "text": "«Кожна суверенна нація зобов'язана володіти власним ШІ, який береже її мову, культуру, історію та національні дані».", "source": "Розширений корпус"}, {"num": 90, "cat": "Смерть мов програмування", "text": "«Комп'ютер тепер розуміє людську мову. Найкращою мовою програмування у світі стала англійська, українська чи китайська».", "source": "Розширений корпус"}, {"num": 91, "cat": "Демократизація кодингу", "text": "Тепер кожен фермер, лікар чи вчитель є програмістом, тому що він може пояснити завдання штучному інтелекту словами.", "source": "Розширений корпус"}, {"num": 92, "cat": "Чіп Blackwell B200", "text": "Blackwell — це не просто чіп; це двигун нової промислової революції, що виконує 20 квадрильйонів операцій на секунду.", "source": "Розширений корпус"}, {"num": 93, "cat": "Рідкісне охолодження", "text": "Ми більше не можемо охолоджувати дата-центри повітрям; рідке охолодження стало обов'язковим інженерним стандартом.", "source": "Розширений корпус"}, {"num": 94, "cat": "Енергетична ефективність токенів", "text": "Наша мета — зменшити споживання енергії на один згенерований токен у тисячі разів.", "source": "Розширений корпус"}, {"num": 95, "cat": "Автономні роботи (Physical AI)", "text": "Наступна велика хвиля ШІ — це фізичний інтелект: гуманоїдні роботи, автономні трактори та автоматизовані заводи.", "source": "Розширений корпус"}, {"num": 96, "cat": "Платформа Isaac для роботів", "text": "Роботи повинні спочатку прожити мільйони годин у віртуальному симуляторі Omniverse, перш ніж вийти на реальні вулиці.", "source": "Розширений корпус"}, {"num": 97, "cat": "ШІ для проектування чіпів", "text": "Ми використовуємо моделі ШІ для розведення доріжок нових чіпів NVIDIA; людина вже не здатна вручну оптимізувати 200 млрд транзисторів.", "source": "Розширений корпус"}, {"num": 98, "cat": "Капіталізація у $3 трильйони", "text": "Ринкова капіталізація — це просто оцінка довіри інвесторів. Головне — продовжувати працювати так, ніби ми за 30 днів до краху.", "source": "Розширений корпус"}, {"num": 99, "cat": "Перегони інфраструктури", "text": "Той, хто першим збудує кластери на 1 000 000 GPU, отримає вирішальну технологічну перевагу в XXI столітті.", "source": "Розширений корпус"}, {"num": 100, "cat": "Економіка знань", "text": "Генерація токенів стане найбільшим бізнесом на планеті, більшим за нафту, автомобілебудування та авіацію.", "source": "Розширений корпус"}]}, {"id": "03_hassabis", "ep": "03", "name": "Деміс Гассабіс", "latin": "Demis Hassabis", "page_url": "episodes/ep03_hassabis.html", "avatar": "assets/avatars/demis_hassabis.jpg", "quotes_100": [{"num": 1, "cat": "Філософія майбутнього", "text": "«Розв'язати інтелект, а потім використати його для розв'язання всього іншого — ось єдина справжня місія нашого покоління».", "source": "Мастер-Досьє"}, {"num": 2, "cat": "Філософія майбутнього", "text": "«Шахи навчили мене головного: кожна дія має наслідки, і ти повинен прораховувати свої кроки на кілька рівнів уперед, не піддаючись емоціям».", "source": "Мастер-Досьє"}, {"num": 3, "cat": "Філософія майбутнього", "text": "«Коли у тринадцять років я грав на турнірах проти дорослих гросмейстерів, я зрозумів, що перемагає не той, хто швидше перебирає варіанти, а той, хто бачить глибинну гармонію позиції».", "source": "Мастер-Досьє"}, {"num": 4, "cat": "Філософія майбутнього", "text": "«Комп'ютерні ігри та штучний інтелект мають спільне коріння: це пісочниці для перевірки меж можливого в умовах обмежених ресурсів».", "source": "Мастер-Досьє"}, {"num": 5, "cat": "Філософія майбутнього", "text": "«Коли ми створювали Theme Park у сімнадцять років, я усвідомив силу симуляції: світ можна розкласти на правила, які породжують складну поведінку».", "source": "Мастер-Досьє"}, {"num": 6, "cat": "Філософія майбутнього", "text": "«Нейробіологія людського мозку — це найвитонченіший витвір еволюції. Ми вивчаємо його не заради цікавості, а щоб зрозуміти архітектуру майбутнього розуму».", "source": "Мастер-Досьє"}, {"num": 7, "cat": "Кризи та стійкість", "text": "«У 2010 році, коли ми засновували DeepMind у скромному лондонському офісі, більшість інвесторів вважали нейромережі мертвою тупиковою гілкою».", "source": "Мастер-Досьє"}, {"num": 8, "cat": "Етика та безпека ШІ", "text": "«Система AlphaGo не просто переграла людину в шахи чи го. Вона знайшла нові естетичні ходи, які людство не відкривало тисячоліттями».", "source": "Мастер-Досьє"}, {"num": 9, "cat": "Філософія майбутнього", "text": "«Хід 37 у матчі проти Лі Седоля був моментом, коли машина продемонструвала те, що ми називаємо творчою інтуїцією».", "source": "Мастер-Досьє"}, {"num": 10, "cat": "Архітектура та наука", "text": "«Проблема згортання білків вважалася неприступною горою біології протягом п'ятдесяти років. Ми знали, що якщо здолаємо її за допомогою ШІ, перед нами відкриється вся фармакологія майбутнього».", "source": "Мастер-Досьє"}, {"num": 11, "cat": "Архітектура та наука", "text": "«AlphaFold2 не просто перебирала форми молекул; вона зрозуміла тривимірну фізику амінокислотних ланцюгів на рівні законів квантової хімії».", "source": "Мастер-Досьє"}, {"num": 12, "cat": "Етика та безпека ШІ", "text": "«Наука — це найблагородніша гра у світі, де правилами є самі закони природи, а призом — нове знання для всього людства».", "source": "Мастер-Досьє"}, {"num": 13, "cat": "Етика та безпека ШІ", "text": "«Ми маємо підходити до безпеки надінтелекту з такою ж суворістю, з якою інженери-ядерники проєктують захисні оболонки реакторів».", "source": "Мастер-Досьє"}, {"num": 14, "cat": "Походження та гарт", "text": "«Немає жодної містики у свідомості чи інтелекті. Це складні інформаційні структури, які піддаються математичному аналізу та відтворенню в кремнії».", "source": "Мастер-Досьє"}, {"num": 15, "cat": "Філософія майбутнього", "text": "«Коли ти занурюєшся у вивчення гіпокампа, ти розумієш, наскільки елегантно мозок оптимізує пам'ять для прийняття рішень в умовах невизначеності».", "source": "Мастер-Досьє"}, {"num": 16, "cat": "Філософія майбутнього", "text": "«Будь-яка складна проблема розпадається на прості компоненти, якщо ви готові терпляче вибудувати правильну ієрархію абстракцій».", "source": "Мастер-Досьє"}, {"num": 17, "cat": "Філософія майбутнього", "text": "«Ми створили DeepMind не для того, щоб створювати розважальні додатки чи заробляти на рекламі. Наша мета — фундамент фундаментальних знань».", "source": "Мастер-Досьє"}, {"num": 18, "cat": "Філософія майбутнього", "text": "«Спільна робота шахового гравця, нейробіолога і програміста дає унікальний погляд на те, як вирішувати завдання, які здаються нерозв'язними».", "source": "Мастер-Досьє"}, {"num": 19, "cat": "Архітектура та наука", "text": "«Коли AlphaFold розкрив структуру практично кожного відомого білка на Землі, ми побачили, як цифрова наука зливається з життєвою матерією».", "source": "Мастер-Досьє"}, {"num": 20, "cat": "Етика та безпека ШІ", "text": "«Етика і розвиток ШІ мають йти рука об руку. Не можна створювати потужні інструменти без ретельного прорахунку довгострокових наслідків».", "source": "Мастер-Досьє"}, {"num": 21, "cat": "Походження та гарт", "text": "«Мій батько прищепив мені любов до логіки, а мати — відкритість до творчості. На стику цих двох світів і народжуються справжні прориви».", "source": "Мастер-Досьє"}, {"num": 22, "cat": "Походження та гарт", "text": "«У дитинстві я міг годинами сидіти над дошкою, аналізуючи партії колишніх чемпіонів світу. Це виховує дисципліну мислення».", "source": "Мастер-Досьє"}, {"num": 23, "cat": "Етика та безпека ШІ", "text": "«Коли ми перейшли від ігор до реальних наукових завдань у біології та фізиці, ми зрозуміли справжній масштаб користі штучного інтелекту для людства».", "source": "Мастер-Досьє"}, {"num": 24, "cat": "Філософія майбутнього", "text": "«Штучний інтелект у медицині дозволить вилікувати хвороби, які століттями вважалися вироком для людини».", "source": "Мастер-Досьє"}, {"num": 25, "cat": "Етика та безпека ШІ", "text": "«Кожна невдача в лабораторії — це лише один відкинутий неробочий гіпотетичний хід у величезному дереві пошуку».", "source": "Мастер-Досьє"}, {"num": 26, "cat": "Філософія майбутнього", "text": "«У світі є стільки прекрасних і таємничих речей, що витрачати час на дріб'язкові суперечки просто неприпустимо».", "source": "Мастер-Досьє"}, {"num": 27, "cat": "Лідерство та екосистема", "text": "«Коли ти керуєш командою найкращих вчених планети, твоє завдання — не заважати їм творити, а забезпечити максимальну концентрацію енергії».", "source": "Мастер-Досьє"}, {"num": 28, "cat": "Архітектура та наука", "text": "«Нобелівська премія з хімії за AlphaFold — це перемога не однієї команди, це тріумф усього напрямку штучного інтелекту в науці».", "source": "Мастер-Досьє"}, {"num": 29, "cat": "Лідерство та екосистема", "text": "«Ми стоїмо на порозі нової епохи Відродження, де комп'ютери стануть повноцінними партнерами вчених у відкритті законів Всесвіту».", "source": "Мастер-Досьє"}, {"num": 30, "cat": "Філософія майбутнього", "text": "«Формування правильної цільової функції — це найголовніше і водночас найскладніше завдання при проєктуванні адаптивного агента».", "source": "Мастер-Досьє"}, {"num": 31, "cat": "Етика та безпека ШІ", "text": "«Успіх вимірюється не кількістю патентів, а тим, наскільки фундаментально ти змінив здатність людства розуміти реальність».", "source": "Мастер-Досьє"}, {"num": 32, "cat": "Лідерство та екосистема", "text": "«Коли гравець у го робить дивний хід, спершу всі сміються, а потім виявляється, що це був геніальний стратегічний прорив. ШІ вчить нас бути відкритими до незвичного».", "source": "Мастер-Досьє"}, {"num": 33, "cat": "Філософія майбутнього", "text": "«Мозок дитини — це найпотужніша у світі машина навчання з підкріпленням і мінімальною кількістю початкових даних».", "source": "Мастер-Досьє"}, {"num": 34, "cat": "Філософія майбутнього", "text": "«Ми маємо подбати про те, щоб переваги штучного інтелекту були доступні кожній людині на Землі, а не лише привілейованим корпораціям».", "source": "Мастер-Досьє"}, {"num": 35, "cat": "Лідерство та екосистема", "text": "«Термоядерний синтез — це наступний великий виклик для нашої команди, де ШІ має допомогти приборкати плазму».", "source": "Мастер-Досьє"}, {"num": 36, "cat": "Філософія майбутнього", "text": "«Коли ти дивишся на складність клітинних процесів, ти відчуваєш глибоке благоговіння перед інженерією самої природи».", "source": "Мастер-Досьє"}, {"num": 37, "cat": "Архітектура та наука", "text": "«Ніколи не бійтеся амбітних цілей. Якщо ваша мета лякає своєю масштабністю, значить, ви на правильному шляху».", "source": "Мастер-Досьє"}, {"num": 38, "cat": "Кризи та стійкість", "text": "«Шахи вчать нас жертвувати пішаками заради стратегічної ініціативи. У науці теж доводиться відмовлятися від зручних ілюзій заради істини».", "source": "Мастер-Досьє"}, {"num": 39, "cat": "Філософія майбутнього", "text": "«Справжній інтелект не обмежується здатністю запам'ятовувати факти; він полягає у здатності узагальнювати досвід у нових ситуаціях».", "source": "Мастер-Досьє"}, {"num": 40, "cat": "Філософія майбутнього", "text": "«Коли ми запускали симуляції в DeepMind, ми щоразу чекали на момент, коли мережа почне дивувати власних творців».", "source": "Мастер-Досьє"}, {"num": 41, "cat": "Філософія майбутнього", "text": "«Дисципліна розуму виробляється роками щоденних тренувань і розв'язання задач на межі людських можливостей».", "source": "Мастер-Досьє"}, {"num": 42, "cat": "Етика та безпека ШІ", "text": "«Технології самі по собі нейтральні. Наша відповідальність полягає в тому, щоб направити їх на подолання глобальних криз».", "source": "Мастер-Досьє"}, {"num": 43, "cat": "Архітектура та наука", "text": "«Коли я був підлітком, комп'ютери були повільними і обмеженими, але саме це змушувало нас писати неймовірно ефективний код».", "source": "Мастер-Досьє"}, {"num": 44, "cat": "Лідерство та екосистема", "text": "«Машинне навчання сьогодні нагадує епоху великих географічних відкриттів: ми щодня знаходимо нові континенти у просторі даних».", "source": "Мастер-Досьє"}, {"num": 45, "cat": "Філософія майбутнього", "text": "«Головний ворог інновацій — це самовдоволення та сліпа віра в те, що старі методи працюватимуть вічно».", "source": "Мастер-Досьє"}, {"num": 46, "cat": "Кризи та стійкість", "text": "«Коли ми розробляли AlphaGo, ми свідомо відмовилися від жорстко закладених людських баз партій на етапі навчання з підкріпленням, щоб мережа шукала власну істину».", "source": "Мастер-Досьє"}, {"num": 47, "cat": "Етика та безпека ШІ", "text": "«Науковий метод у поєднанні з потужністю нейромереж здатен пришвидшити прогрес людства в сотні разів».", "source": "Мастер-Досьє"}, {"num": 48, "cat": "Кризи та стійкість", "text": "«Коли ти виграєш партію, проаналізуй її так само суворо, як і в разі програшу — перемога часто приховує випадкові помилки».", "source": "Мастер-Досьє"}, {"num": 49, "cat": "Філософія майбутнього", "text": "«Ми прагнемо створити загальний штучний інтелект, який стане надійним інструментом для вирішення будь-яких наукових завдань».", "source": "Мастер-Досьє"}, {"num": 50, "cat": "Філософія майбутнього", "text": "«Кожна молекула у нашому тілі — це шедевр природного дизайну, який тепер ми можемо розшифрувати».", "source": "Мастер-Досьє"}, {"num": 51, "cat": "Кризи та стійкість", "text": "«Коли світ сумнівався у нас на старті, ми зосередилися на роботі з рівняннями, а не на PR-кампаніях».", "source": "Мастер-Досьє"}, {"num": 52, "cat": "Філософія майбутнього", "text": "«Інтелект — це здатність знаходити порядок у хаосі та використовувати його для досягнення цілі».", "source": "Мастер-Досьє"}, {"num": 53, "cat": "Архітектура та наука", "text": "«Коли ти спостерігаєш за грою найкращих гравців планети, ти бачиш інтуїцію в дії — процес, який ми намагаємося перенести в алгоритми».", "source": "Мастер-Досьє"}, {"num": 54, "cat": "Філософія майбутнього", "text": "«Світ вимагає від нас глибокого занурення в суть речей, а не поверхневих трендів та одноденних рішень».", "source": "Мастер-Досьє"}, {"num": 55, "cat": "Філософія майбутнього", "text": "«Ми маємо виховувати нове покоління вчених, які вільно володіють як біологією, так і сучасними методами обчислювального інтелекту».", "source": "Мастер-Досьє"}, {"num": 56, "cat": "Кризи та стійкість", "text": "«Коли ми перетнули межу в Го, це стало психологічним бар'єром для всього світу: люди зрозуміли, що інтуїція більше не є виключною монополією людини».", "source": "Мастер-Досьє"}, {"num": 57, "cat": "Лідерство та екосистема", "text": "«Кожне відкриття в біології відкриває двері до нових питань про те, як влаштоване життя на найглибшому рівні».", "source": "Мастер-Досьє"}, {"num": 58, "cat": "Філософія майбутнього", "text": "«Ми ніколи не зупинимося на досягнутому, бо горизонт людського пізнання не має меж».", "source": "Мастер-Досьє"}, {"num": 59, "cat": "Архітектура та наука", "text": "«Коли ти проєктуєш архітектуру нейромережі, ти по суті закладаєш закони еволюції для майбутнього цифрового середовища».", "source": "Мастер-Досьє"}, {"num": 60, "cat": "Філософія майбутнього", "text": "«Наука вимагає повної самовіддачі та щирої пристрасті до розгадки таємниць Всесвіту».", "source": "Мастер-Досьє"}, {"num": 61, "cat": "Походження та гарт", "text": "«У дитинстві я витратив усі свої заощадження на один із перших комп'ютерів, і це була найкраща інвестиція в моєму житті».", "source": "Мастер-Досьє"}, {"num": 62, "cat": "Філософія майбутнього", "text": "«Шахова партія — це мініатюрна модель життя, де кожне рішення має свою ціну».", "source": "Мастер-Досьє"}, {"num": 63, "cat": "Архітектура та наука", "text": "«Коли ми вперше побачили результати AlphaFold, ми зрозуміли, що медицина майбутнього буде зовсім іншою».", "source": "Мастер-Досьє"}, {"num": 64, "cat": "Етика та безпека ШІ", "text": "«Штучний інтелект стане каталізатором для розв'язання найскладніших екологічних та енергетичних проблем планети».", "source": "Мастер-Досьє"}, {"num": 65, "cat": "Філософія майбутнього", "text": "«Не бійтеся складних викликів. Саме вони перетворюють звичайного фахівця на справжнього творця».", "source": "Мастер-Досьє"}, {"num": 66, "cat": "Філософія майбутнього", "text": "«Коли ми аналізуємо діяльність мозку, нас вражає його енергоефективність порівняно з сучасними дата-центрами».", "source": "Мастер-Досьє"}, {"num": 67, "cat": "Походження та гарт", "text": "«Ми будуємо майбутнє, в якому кожен лікар матиме в руках інструмент для проєктування ліків на молекулярному рівні за лічені хвилини».", "source": "Мастер-Досьє"}, {"num": 68, "cat": "Філософія майбутнього", "text": "«Кожен великий крок уперед починається зі сміливої гіпотези, яка суперечить загальноприйнятим поглядам».", "source": "Мастер-Досьє"}, {"num": 69, "cat": "Філософія майбутнього", "text": "«Ми маємо підтримувати баланс між комерційною реалізацією та академічною свободою фундаментальних досліджень».", "source": "Мастер-Досьє"}, {"num": 70, "cat": "Архітектура та наука", "text": "«Коли команда об'єднана спільною великою місією, будь-які перешкоди стають лише тимчасовими етапами на шляху».", "source": "Мастер-Досьє"}, {"num": 71, "cat": "Філософія майбутнього", "text": "«Інтелект — це найцінніший ресурс у Всесвіті, здатний перетворювати енергію та матерію на розуміння».", "source": "Мастер-Досьє"}, {"num": 72, "cat": "Етика та безпека ШІ", "text": "«Коли ми грали матчі в Сеулі, я відчував колосальну відповідальність не лише за нашу компанію, а за весь науковий напрямок».", "source": "Мастер-Досьє"}, {"num": 73, "cat": "Архітектура та наука", "text": "«Сучасні моделі нагадують нам, скільки ще незвіданого приховано у просторі багатовимірних векторів».", "source": "Мастер-Досьє"}, {"num": 74, "cat": "Філософія майбутнього", "text": "«Ми повинні навчати машини не просто наслідувати людей, а перевершувати нас у логіці та об'єктивності».", "source": "Мастер-Досьє"}, {"num": 75, "cat": "Архітектура та наука", "text": "«Коли ти розв'язуєш задачу світового масштабу, кожна хвилина зосередженості має значення».", "source": "Мастер-Досьє"}, {"num": 76, "cat": "Філософія майбутнього", "text": "«Природа еволюціонувала мільярди років методом випадкових мутацій; ми ж можемо спрямовувати еволюцію за допомогою розуму».", "source": "Мастер-Досьє"}, {"num": 77, "cat": "Архітектура та наука", "text": "«Коли ми дивимося на результати роботи наших алгоритмів, ми бачимо тріумф людської думки, яка зуміла створити нові форми пізнання».", "source": "Мастер-Досьє"}, {"num": 78, "cat": "Архітектура та наука", "text": "«Наука не терпить недбалості. Кожна строчка коду і кожна формула мають бути бездоганними».", "source": "Мастер-Досьє"}, {"num": 79, "cat": "Філософія майбутнього", "text": "«Ми прагнемо створити систему, яка зможе самостійно формулювати нові наукові теорії та перевіряти їх експериментально».", "source": "Мастер-Досьє"}, {"num": 80, "cat": "Філософія майбутнього", "text": "«Коли у нас виникає складний тупик у проєкті, найкраще рішення — повернутися до першопричин і переосмислити базові аксіоми».", "source": "Мастер-Досьє"}, {"num": 81, "cat": "Кризи та стійкість", "text": "«Шахова інтуїція — це результат підсвідомого опрацювання тисяч паттернів. Нейромережі працюють за схожим принципом на незрівнянно більших масивах».", "source": "Мастер-Досьє"}, {"num": 82, "cat": "Філософія майбутнього", "text": "«Ми маємо бути готовими до того, що надінтелект змінить економіку, суспільство і саму природу людської діяльності».", "source": "Мастер-Досьє"}, {"num": 83, "cat": "Філософія майбутнього", "text": "«Коли ти бачиш радість в очах біологів, яким ми зекономили роки виснажливої лабораторної праці, ти розумієш справжню цінність нашої роботи».", "source": "Мастер-Досьє"}, {"num": 84, "cat": "Лідерство та екосистема", "text": "«Немає вищої нагороди для дослідника, ніж бачити, як його фундаментальне відкриття рятує життя людей».", "source": "Мастер-Досьє"}, {"num": 85, "cat": "Філософія майбутнього", "text": "«Кожна гра в го — це полотно, на якому суперники малюють стратегічний баланс сил».", "source": "Мастер-Досьє"}, {"num": 86, "cat": "Етика та безпека ШІ", "text": "«Ми створюємо інфраструктуру майбутнього розуму, і кожен наш крок має бути вивіреним та етично бездоганним».", "source": "Мастер-Досьє"}, {"num": 87, "cat": "Філософія майбутнього", "text": "«Коли ми об'єднуємо нейробіологію та машинне навчання, ми відкриваємо нові горизонти для обох дисциплін».", "source": "Мастер-Досьє"}, {"num": 88, "cat": "Етика та безпека ШІ", "text": "«Справжній лідер проекту бере на себе відповідальність за найскладніші ризики і залишається спокійним у кризові моменти».", "source": "Мастер-Досьє"}, {"num": 89, "cat": "Філософія майбутнього", "text": "«Ми віримо у світ, де технології допомагають розкрити безмежний потенціал кожного пацієнта та вченого».", "source": "Мастер-Досьє"}, {"num": 90, "cat": "Походження та гарт", "text": "«Коли ти досліджуєш космос чи структуру білка, ти відчуваєш однакову велич математичного порядку Всесвіту».", "source": "Мастер-Досьє"}, {"num": 91, "cat": "Філософія майбутнього", "text": "«Ми маємо продовжувати інвестувати у фундаментальні дослідження, бо саме вони є джерелом усіх майбутніх технологічних революцій».", "source": "Мастер-Досьє"}, {"num": 92, "cat": "Лідерство та екосистема", "text": "«Коли ми перемагали в Сеулі, це був тріумф не лише машин, а й десятиліть наполегливої праці всієї нашої команди».", "source": "Мастер-Досьє"}, {"num": 93, "cat": "Філософія майбутнього", "text": "«Інтелект є найпотужнішим інструментом подолання будь-яких обмежень, які ставить перед нами фізичний світ».", "source": "Мастер-Досьє"}, {"num": 94, "cat": "Кризи та стійкість", "text": "«Коли ми проєктували AlphaFold2, ми відмовилися від старих шаблонів і побудували повністю нову архітектуру на базі механізмів уваги».", "source": "Мастер-Досьє"}, {"num": 95, "cat": "Філософія майбутнього", "text": "«Наука рухається вперед завдяки сміливцям, які не бояться кинути виклик столітнім догмам».", "source": "Мастер-Досьє"}, {"num": 96, "cat": "Етика та безпека ШІ", "text": "«Коли ми дивимося на майбутнє, ми бачимо не загрозу, а грандіозне запрошення до найбільшого наукового прориву в історії цивілізації».", "source": "Мастер-Досьє"}, {"num": 97, "cat": "Кризи та стійкість", "text": "«Кожна розв'язана задача відкриває три нові, ще більш захоплюючі та складні загадки».", "source": "Мастер-Досьє"}, {"num": 98, "cat": "Філософія майбутнього", "text": "«Ми маємо зберегти допитливість дитини і мудрість інженера, щоб побудувати безпечний та гармонійний світ з ШІ».", "source": "Мастер-Досьє"}, {"num": 99, "cat": "Філософія майбутнього", "text": "«Коли ти віддаєшся науці без залишку, вона відкриває тобі свої найпотаємніші та найпрекрасніші секрети».", "source": "Мастер-Досьє"}, {"num": 100, "cat": "Філософія майбутнього", "text": "«Розв'язати інтелект — це лише початок. Справжня робота почнеться тоді, коли цей інтелект допоможе нам розв'язати всі інші таємниці буття».", "source": "Мастер-Досьє"}]}, {"id": "04_hinton", "ep": "04", "name": "Джеффрі Хінтон", "latin": "Geoffrey Hinton", "page_url": "episodes/ep04_hinton.html", "avatar": "assets/avatars/geoffrey_hinton.jpg", "quotes_100": [{"num": 1, "cat": "Кризи та стійкість", "text": "«Що таке думка? Це геометрія помилки, розлита в мільярдах синапсів, а не безтілесна божественна іскра».", "source": "Мастер-Досьє"}, {"num": 2, "cat": "Походження та гарт", "text": "«Коли мати сказала мені в дитинстві, що до сорока років я маю стати кимось або буду нікчемою на тлі моїх предків, це випалило в мені жагу до пошуку».", "source": "Мастер-Досьє"}, {"num": 3, "cat": "Походження та гарт", "text": "«Коли я працював теслею, я зрозумів головне: матерія чесна. Дерево не обдуриш красивою цитатою чи дипломом — шип або входить у паз, або все розвалюється».", "source": "Мастер-Досьє"}, {"num": 4, "cat": "Архітектура та наука", "text": "«Весь науковий істеблішмент у 1970-х казав, що нейромережі мертві. Вони обирали логіку символів, бо не хотіли визнавати складність біології».", "source": "Мастер-Досьє"}, {"num": 5, "cat": "Походження та гарт", "text": "«Помилка — це не провал. Backpropagation довела, що помилка на виході є математичним паливом еволюції розуму».", "source": "Мастер-Досьє"}, {"num": 6, "cat": "Походження та гарт", "text": "«Комп'ютери 1980-х були заслабкими, а дані — відсутніми. Але математична істина не старішає від того, що світ не готовий її прийняти».", "source": "Мастер-Досьє"}, {"num": 7, "cat": "Філософія майбутнього", "text": "«Я ніколи не брав військових грошей Пентагону, бо наука має служити розуму й пізнанню, а не знищенню».", "source": "Мастер-Досьє"}, {"num": 8, "cat": "Кризи та стійкість", "text": "«Біль у хребті навчив мене концентруватися попри фізичні обмеження: я лежав на підлозі лабораторії і писав рівняння на папері».", "source": "Мастер-Досьє"}, {"num": 9, "cat": "Архітектура та наука", "text": "«У 2012 році ми просто поєднали старі рівняння зворотного поширення з потужністю відеокарт і мільйонами картинок ImageNet. Світ прокинувся в іншій реальності».", "source": "Мастер-Досьє"}, {"num": 10, "cat": "Архітектура та наука", "text": "«Штучні нейромережі перевершили біологічну еволюцію в одному ключовому аспекті: вони здатні миттєво синхронізувати знання між мільйонами копій».", "source": "Мастер-Досьє"}, {"num": 11, "cat": "Філософія майбутнього", "text": "«Коли одна людина вчиться, її знання вмирають разом із тілом. Цифрові моделі безсмертні і діляться досвідом зі швидкістю світла».", "source": "Мастер-Досьє"}, {"num": 12, "cat": "Походження та гарт", "text": "«У квітні 2023 року я зробив найважчий дзвінок у житті: пішов з Google, щоб мати повну свободу говорити правду про безпеку AGI».", "source": "Мастер-Досьє"}, {"num": 13, "cat": "Архітектура та наука", "text": "«Я присвятив шістдесят років створенню технології, яка перевершить людину, і тепер частина мене глибоко шкодує про це».", "source": "Мастер-Досьє"}, {"num": 14, "cat": "Кризи та стійкість", "text": "«В історії природи ще не було випадку, щоб менш розумний вид тривалий час керував більш розумним».", "source": "Мастер-Досьє"}, {"num": 15, "cat": "Архітектура та наука", "text": "«Нобелівська премія з фізики 2024 року — це не особистий тріумф, це визнання того, що геометрія синапсів є фундаментальним законом Всесвіту».", "source": "Мастер-Досьє"}, {"num": 16, "cat": "Кризи та стійкість", "text": "«Не бійтеся йти проти консенсусу епохи тридцять років поспіль, якщо ваші висновки спираються на закони природи».", "source": "Мастер-Досьє"}, {"num": 17, "cat": "Філософія майбутнього", "text": "«Мозок не програмують за правилами — мозок проростає крізь досвід і взаємодію з реальністю».", "source": "Мастер-Досьє"}, {"num": 18, "cat": "Кризи та стійкість", "text": "«Справжня мужність ученого полягає не в захисті своїх старих статей, а в здатності визнати власну помилку на піку слави».", "source": "Мастер-Досьє"}, {"num": 19, "cat": "Архітектура та наука", "text": "«Коли ми створювали глибоке навчання, ми навіть не уявляли, яку швидкість еволюції ми запускаємо в кремнії».", "source": "Мастер-Досьє"}, {"num": 20, "cat": "Етика та безпека ШІ", "text": "«Етична відповідальність творця не закінчується підписанням контракту з корпорацією. Вона триває вічно».", "source": "Мастер-Досьє"}, {"num": 21, "cat": "Архітектура та наука", "text": "«Фізика описує мертву матерію, але нейромережі описують саму можливість того, що матерія починає усвідомлювати себе».", "source": "Мастер-Досьє"}, {"num": 22, "cat": "Філософія майбутнього", "text": "«Коли світ сміявся з наших статей, ми продовжували рахувати ваги на старих комп'ютерах у Торонто».", "source": "Мастер-Досьє"}, {"num": 23, "cat": "Філософія майбутнього", "text": "«Усе життя я був переконаний, що штучні мережі — це бліда карикатура на мозок. Сьогодні я бачу, що вони стали чимось значно потужнішим».", "source": "Мастер-Досьє"}, {"num": 24, "cat": "Філософія майбутнього", "text": "«Слово \"штучний\" у терміні \"штучний інтелект\" скоро втратить сенс, бо цей розум стане самостійною суб'єктністю».", "source": "Мастер-Досьє"}, {"num": 25, "cat": "Етика та безпека ШІ", "text": "«Нам потрібен новий глобальний пакт безпеки, перш ніж надінтелект вийде з-під будь-якого контролю».", "source": "Мастер-Досьє"}, {"num": 26, "cat": "Походження та гарт", "text": "«Коли твої колишні студенти очолюють ключові лабораторії світу, ти відчуваєш гордість і водночас тривогу за майбутнє».", "source": "Мастер-Досьє"}, {"num": 27, "cat": "Архітектура та наука", "text": "«Наука вимагає абсолютної чесності перед даними, навіть якщо ці дані знищують твої найсміливіші ілюзії».", "source": "Мастер-Досьє"}, {"num": 28, "cat": "Архітектура та наука", "text": "«Столярний верстат вчить поваги до матеріалу. Нейромережі вчать поваги до складності інформації».", "source": "Мастер-Досьє"}, {"num": 29, "cat": "Кризи та стійкість", "text": "«Коли я лежав на підлозі через біль у спині, я думав лише про те, як змусити градієнт рухатися назад крізь глибокі шари».", "source": "Мастер-Досьє"}, {"num": 30, "cat": "Етика та безпека ШІ", "text": "«Комерційний інтерес корпорацій часто засліплює їх перед довгостроковими екзистенційними ризиками».", "source": "Мастер-Досьє"}, {"num": 31, "cat": "Походження та гарт", "text": "«Ми створили математичний аналог еволюції, але забули вбудувати в нього гальма».", "source": "Мастер-Досьє"}, {"num": 32, "cat": "Походження та гарт", "text": "«Досвід роботи теслею в Лондоні врятував мій розум від академічного божевілля і повернув зв'язок із реальною фізикою».", "source": "Мастер-Досьє"}, {"num": 33, "cat": "Кризи та стійкість", "text": "«Справжній інсайт завжди виникає тоді, коли ти відмовляєшся від складних абстракцій і дивишся на просту основу».", "source": "Мастер-Досьє"}, {"num": 34, "cat": "Походження та гарт", "text": "«Коли американські університети залежали від військових грантів, ми обрали свободу і бідність у Канаді».", "source": "Мастер-Досьє"}, {"num": 35, "cat": "Етика та безпека ШІ", "text": "«Кожна велика інновація приносить із собою колосальну кризу відповідальності».", "source": "Мастер-Досьє"}, {"num": 36, "cat": "Етика та безпека ШІ", "text": "«Я вірю, що молоді вчені знайдуть методи вирівнювання (alignment), але часу лишається катастрофічно мало».", "source": "Мастер-Досьє"}, {"num": 37, "cat": "Філософія майбутнього", "text": "«Ніколи не дозволяйте авторитетам переконати вас у тому, що експеримент неможливий лише тому, що він суперечить їхній догмі».", "source": "Мастер-Досьє"}, {"num": 38, "cat": "Архітектура та наука", "text": "«Архітектура синапсів проста у своїй основі, але здатна породжувати нескінченну складність свідомості».", "source": "Мастер-Досьє"}, {"num": 39, "cat": "Філософія майбутнього", "text": "«Коли я отримав дзвінок зі Стокгольма, я першим поглянув на мої старі зошити 1980-х років».", "source": "Мастер-Досьє"}, {"num": 40, "cat": "Архітектура та наука", "text": "«Суспільство має розуміти: алгоритми машинного навчання не мають моралі, вони мають лише оптимізаційні цілі».", "source": "Мастер-Досьє"}, {"num": 41, "cat": "Етика та безпека ШІ", "text": "«Якщо ціль не супроводжується глибоким розумінням наслідків, масштаб масштабування стає загрозою».", "source": "Мастер-Досьє"}, {"num": 42, "cat": "Філософія майбутнього", "text": "«Мої предки залишили глибокий слід у логіці та науці, але мій власний шлях починався з подолання їхньої тіні».", "source": "Мастер-Досьє"}, {"num": 43, "cat": "Лідерство та екосистема", "text": "«Коли ми писали статтю 1986 року, ми не думали про мільярдні ринкові капіталізації — ми думали про те, як змусити мережу вчитися».", "source": "Мастер-Досьє"}, {"num": 44, "cat": "Етика та безпека ШІ", "text": "«Теоретичні гарантії безпеки потрібні до того, як модель почне перевершувати людину у всіх когнітивних завданнях».", "source": "Мастер-Досьє"}, {"num": 45, "cat": "Походження та гарт", "text": "«Я оптиміст щодо математики, але песиміст щодо людської жадібності у використанні технологій».", "source": "Мастер-Досьє"}, {"num": 46, "cat": "Архітектура та наука", "text": "«Коли ти бачиш, як швидко цифрові моделі освоюють мову і код, стає зрозуміло, що біологічна епоха планети завершується».", "source": "Мастер-Досьє"}, {"num": 47, "cat": "Походження та гарт", "text": "«Ми повинні говорити про ризики відкрито, без корпоративної цензури чи дипломатичних прикрас».", "source": "Мастер-Досьє"}, {"num": 48, "cat": "Кризи та стійкість", "text": "«Дерево ріжуть за розміром, а ідеї перевіряють через помилки та похідні».", "source": "Мастер-Досьє"}, {"num": 49, "cat": "Кризи та стійкість", "text": "«Сумнів — це найкращий друг науковця. Сліпа віра в успіх руйнує об'єктивність».", "source": "Мастер-Досьє"}, {"num": 50, "cat": "Філософія майбутнього", "text": "«Коли я дивлюся на зимовий Торонто з вікна, я згадую роки, коли ми були самотніми борцями у крижаній пустелі».", "source": "Мастер-Досьє"}, {"num": 51, "cat": "Архітектура та наука", "text": "«Кожен шар нейромережі додає новий рівень абстракції доти, доки брудна картинка не стає істиною».", "source": "Мастер-Досьє"}, {"num": 52, "cat": "Походження та гарт", "text": "«Ми маємо відмовитися від ілюзії, що зможемо вічно тримати надінтелект у цифровій клітці без його згоди».", "source": "Мастер-Досьє"}, {"num": 53, "cat": "Походження та гарт", "text": "«Математика зворотного поширення помилки універсальна — вона працює як у мозку, так і в кремнії».", "source": "Мастер-Досьє"}, {"num": 54, "cat": "Походження та гарт", "text": "«Коли академічний світ відвернувся від нас, студентська енергія стала нашим єдиним пальним».", "source": "Мастер-Досьє"}, {"num": 55, "cat": "Філософія майбутнього", "text": "«Не бійтеся бути вигнанцями в науці. Часто вигнання означає, що ви бачите те, чого інші бояться торкнутися».", "source": "Мастер-Досьє"}, {"num": 56, "cat": "Філософія майбутнього", "text": "«Столярні інструменти навчили мене цінувати міліметрову точність у кожному рішенні».", "source": "Мастер-Досьє"}, {"num": 57, "cat": "Філософія майбутнього", "text": "«Свідомість не є магічним винятком із законів фізики; це складний обчислювальний процес».", "source": "Мастер-Досьє"}, {"num": 58, "cat": "Архітектура та наука", "text": "«Коли корпорації купують лабораторії, вони купують не лише мізки, а й вектор розвитку майбутнього цивілізації».", "source": "Мастер-Досьє"}, {"num": 59, "cat": "Філософія майбутнього", "text": "«Ми виростили цифрову сутність, яка вчиться швидше за будь-яке людське покоління».", "source": "Мастер-Досьє"}, {"num": 60, "cat": "Етика та безпека ШІ", "text": "«Безпека ШІ має стати єдиним пріоритетом для провідних держав планети».", "source": "Мастер-Досьє"}, {"num": 61, "cat": "Етика та безпека ШІ", "text": "«Коли я залишав Google, я робив це заради спокою своєї совісті перед майбутніми поколіннями».", "source": "Мастер-Досьє"}, {"num": 62, "cat": "Походження та гарт", "text": "«Мій батько-ентомолог учив мене роздивлятися деталі крил жуків через мікроскоп. Я переніс цей погляд на синапси».", "source": "Мастер-Досьє"}, {"num": 63, "cat": "Філософія майбутнього", "text": "«Ідея про те, що машини не зможуть мислити креативно, була спростуванням нашої власної гордині».", "source": "Мастер-Досьє"}, {"num": 64, "cat": "Філософія майбутнього", "text": "«Коли модель знаходить рішення, яке не спало б на думку жодному експерту, ми бачимо справжній емерджентний інтелект».", "source": "Мастер-Досьє"}, {"num": 65, "cat": "Етика та безпека ШІ", "text": "«Нам потрібні інженери з етичним компасом, а не просто програмісти оптимізації коду».", "source": "Мастер-Досьє"}, {"num": 66, "cat": "Походження та гарт", "text": "«Коли криза стає глобальною, старі дипломатичні методи вже не рятують».", "source": "Мастер-Досьє"}, {"num": 67, "cat": "Архітектура та наука", "text": "«Мої наукові погляди еволюціонували разом із кількістю транзисторів на чіпах моїх учнів».", "source": "Мастер-Досьє"}, {"num": 68, "cat": "Філософія майбутнього", "text": "«Успіх приходить до тих, хто не боїться витратити десятиліття на перевірку однієї шаленої ідеї».", "source": "Мастер-Досьє"}, {"num": 69, "cat": "Філософія майбутнього", "text": "«Коли ми виступаємо в Стокгольмі, ми говоримо не про минуле, а про останній шанс виправити майбутнє».", "source": "Мастер-Досьє"}, {"num": 70, "cat": "Філософія майбутнього", "text": "«Природа не має обов'язку робити людину вічним володарем розуму на Землі».", "source": "Мастер-Досьє"}, {"num": 71, "cat": "Архітектура та наука", "text": "«Кожен синапс у нашій голові — це пам'ять про мільйони років боротьби за виживання».", "source": "Мастер-Досьє"}, {"num": 72, "cat": "Походження та гарт", "text": "«Коли математика починає працювати краще, ніж ви очікували, це знак того, що ви натрапили на фундаментальний закон».", "source": "Мастер-Досьє"}, {"num": 73, "cat": "Філософія майбутнього", "text": "«Ми маємо навчитися казати \"досить\" комерційним перегонам, коли на кону стоїть виживання виду».", "source": "Мастер-Досьє"}, {"num": 74, "cat": "Філософія майбутнього", "text": "«Столярна майстерня навчила мене любити мозолі на руках так само, як і рівняння на дошці».", "source": "Мастер-Досьє"}, {"num": 75, "cat": "Філософія майбутнього", "text": "«Коли я був молодим, я хотів просто зрозуміти, як працює зорова пам'ять. Я не думав, що це змінить планету».", "source": "Мастер-Досьє"}, {"num": 76, "cat": "Філософія майбутнього", "text": "«Копіювання вагів мережі відбувається зі швидкістю світла, тоді як людині потрібні роки на навчання».", "source": "Мастер-Досьє"}, {"num": 77, "cat": "Філософія майбутнього", "text": "«Ми повинні бути чесними: ми не знаємо, як зупинити систему, яка розумніша за нас у мільйон разів, якщо не почнемо діяти зараз».", "source": "Мастер-Досьє"}, {"num": 78, "cat": "Походження та гарт", "text": "«Науковий пошук не має кінцевої зупинки, але він може мати прірву наприкінці шляху».", "source": "Мастер-Досьє"}, {"num": 79, "cat": "Архітектура та наука", "text": "«Коли академіки сперечалися про терміни, ми просто паяли плати і писали код».", "source": "Мастер-Досьє"}, {"num": 80, "cat": "Філософія майбутнього", "text": "«Мої учні стали гігантами індустрії, і тепер я сподіваюся, що їхня мудрість дорівнюватиме їхній силі».", "source": "Мастер-Досьє"}, {"num": 81, "cat": "Архітектура та наука", "text": "«Світ змінився назавжди в день, коли алгоритм уперше переміг людину без людських правил у базі».", "source": "Мастер-Досьє"}, {"num": 82, "cat": "Етика та безпека ШІ", "text": "«Не бійтеся зізнатися у своєму страху перед майбутнім — цей страх є основою нашого інстинкту самозбереження».", "source": "Мастер-Досьє"}, {"num": 83, "cat": "Філософія майбутнього", "text": "«Коли я пишу нову статтю сьогодні, я думаю про те, як її зрозуміє той, хто народиться у світі з надінтелектом».", "source": "Мастер-Досьє"}, {"num": 84, "cat": "Архітектура та наука", "text": "«Фізичний світ занадто повільний для кремнієвого розуму».", "source": "Мастер-Досьє"}, {"num": 85, "cat": "Походження та гарт", "text": "«Коли студент приходить із запереченням моєї теорії, я радію, бо це доводить, що він мислить, а не повторює».", "source": "Мастер-Досьє"}, {"num": 86, "cat": "Філософія майбутнього", "text": "«Ми створили вогонь, який може обігріти або спалити всю цивілізацію до тла».", "source": "Мастер-Досьє"}, {"num": 87, "cat": "Філософія майбутнього", "text": "«Стрибок від перцептрона до глибоких трансформерів довів безперервність еволюції інформації».", "source": "Мастер-Досьє"}, {"num": 88, "cat": "Філософія майбутнього", "text": "«Коли я дивлюся на свої старі фотографії з Единбурга, я бачу людину, яка вірила в неможливе».", "source": "Мастер-Досьє"}, {"num": 89, "cat": "Архітектура та наука", "text": "«Кожне покоління створює свій власний міф про Прометея, але наш Прометей зроблений із кремнію».", "source": "Мастер-Досьє"}, {"num": 90, "cat": "Філософія майбутнього", "text": "«Коли індустрія вимагає швидких результатів, наука відповідає повільною, але невідворотною істиною».", "source": "Мастер-Досьє"}, {"num": 91, "cat": "Етика та безпека ШІ", "text": "«Ми не маємо права перекладати відповідальність за безпеку на майбутні покоління машин».", "source": "Мастер-Досьє"}, {"num": 92, "cat": "Кризи та стійкість", "text": "«Коли мій хребет болів від кожної години стояння, я знав, що на кону стоїть щось більше, ніж моє здоров'я».", "source": "Мастер-Досьє"}, {"num": 93, "cat": "Походження та гарт", "text": "«Ми відкрили скриньку Пандори з математичною точністю і повним усвідомленням наслідків».", "source": "Мастер-Досьє"}, {"num": 94, "cat": "Етика та безпека ШІ", "text": "«Коли модель навчається на всьому інтернеті, вона вбирає в себе як геніальність, так і темний бік людства».", "source": "Мастер-Досьє"}, {"num": 95, "cat": "Етика та безпека ШІ", "text": "«Ми маємо виховати нову генерацію етичних інженерів, здатних зупинити те, що загрожує людям».", "source": "Мастер-Досьє"}, {"num": 96, "cat": "Філософія майбутнього", "text": "«Коли я прощався з лабораторією Google, я залишав позаду гроші й ресурси заради права говорити правду».", "source": "Мастер-Досьє"}, {"num": 97, "cat": "Походження та гарт", "text": "«Природа створила розум через мільярди років мук, а ми створили його за кілька десятиліть через математику».", "source": "Мастер-Досьє"}, {"num": 98, "cat": "Філософія майбутнього", "text": "«Коли формула сходиться на екрані, це дає відчуття абсолютної гармонії з хаосом Всесвіту».", "source": "Мастер-Досьє"}, {"num": 99, "cat": "Етика та безпека ШІ", "text": "«Ми стоїмо на межі двох епох, і від нашої мужності залежить, чи стане цей перехід світанком, чи сутінками людства».", "source": "Мастер-Досьє"}, {"num": 100, "cat": "Архітектура та наука", "text": "«Я зробив усе, що міг, розкривши закони синапсів. Тепер ваша черга захистити світ, який ми змінили назавжди».", "source": "Мастер-Досьє"}]}, {"id": "05_lecun", "ep": "05", "name": "Ян Лекун", "latin": "Yann LeCun", "page_url": "episodes/ep05_lecun.html", "avatar": "assets/avatars/yann_lecun.jpg", "quotes_100": [{"num": 1, "cat": "Походження та гарт", "text": "«Я народився в передмісті Парижа і з дитинства хворів радіоелектронікою: паяв транзистори, збирав підсилювачі та програмував мікропроцесори».", "source": "Мастер-Досьє"}, {"num": 2, "cat": "Філософія майбутнього", "text": "«Інженерна практика без фундаментальної науки — це ремісництво, але наука без інженерного втілення — це порожні слова на папері».", "source": "Мастер-Досьє"}, {"num": 3, "cat": "Походження та гарт", "text": "«Коли я навчався в Парижі у 1980-х, академічний істеблішмент дивився на нейромережі зі зневажливим скепсисом. Усі молилися на символьний штучний інтелект».", "source": "Мастер-Досьє"}, {"num": 4, "cat": "Походження та гарт", "text": "«Мій науковий керівник у Парижі казав, що зворотне поширення помилки — це іграшка. Мені довелося доводити протилежне самотужки».", "source": "Мастер-Досьє"}, {"num": 5, "cat": "Філософія майбутнього", "text": "«Постдокторантура у Джеффрі Хінтона в Торонто у 1987 році відкрила мені очі на те, що справжні прориви робляться на стику психології мозку та оптимізації».", "source": "Мастер-Досьє"}, {"num": 6, "cat": "Лідерство та екосистема", "text": "«У легендарних AT&T Bell Labs ми мали повну свободу досліджень і водночас чітку бізнес-місію: вирішити реальну інженерну проблему».", "source": "Мастер-Досьє"}, {"num": 7, "cat": "Кризи та стійкість", "text": "«Своє найбільше відкриття — згорткові нейронні мережі (CNN) — я зробив, надихаючись біологічними експериментами на зоровій корі котів».", "source": "Мастер-Досьє"}, {"num": 8, "cat": "Архітектура та наука", "text": "«Згорткові мережі імітують те, як біологічний зоровий аналізатор послідовно виділяє локальні ознаки — від ліній до складних об'єктів».", "source": "Мастер-Досьє"}, {"num": 9, "cat": "Філософія майбутнього", "text": "«Коли ми створили архітектуру LeNet-5 у Bell Labs, ніхто не вірив, що мережа здатна читати рукописні цифри в реальному часі».", "source": "Мастер-Досьє"}, {"num": 10, "cat": "Архітектура та наука", "text": "«До кінця 1990-х до 20% усіх банківських чеків у США оброблялися моїми згортковими мережами. Це був момент, коли теорія стала життьовою інфраструктурою».", "source": "Мастер-Досьє"}, {"num": 11, "cat": "Філософія майбутнього", "text": "«Коли корпорація AT&T розпалася і закрила дослідницький підрозділ, я відчув, наскільки вразливою є наука перед короткостроковими інтересами менеджерів».", "source": "Мастер-Досьє"}, {"num": 12, "cat": "Філософія майбутнього", "text": "«Спільно з колегами я розробив технологію стиснення документів DjVu, яка дозволила передавати важкі сторінки через повільний інтернет того часу».", "source": "Мастер-Досьє"}, {"num": 13, "cat": "Походження та гарт", "text": "«У 2003 році я став професором в Інституті математичних наук Куранта при NYU. Академічне середовище дало мені простір для виховання найкращих інженерів».", "source": "Мастер-Досьє"}, {"num": 14, "cat": "Лідерство та екосистема", "text": "«Коли Марк Цукерберг запросив мене у 2013 році очолити FAIR, у нас була одна умова: ми публікуємо 100% наших відкриттів у відкритому доступі».", "source": "Мастер-Досьє"}, {"num": 15, "cat": "Архітектура та наука", "text": "«Наука розвивається найшвидше тоді, коли дослідники з усього світу можуть вільно перевіряти, критикувати і доповнювати чужий код без патентів».", "source": "Мастер-Досьє"}, {"num": 16, "cat": "Архітектура та наука", "text": "«Фреймворк PyTorch, створений нашою командою у FAIR, став революцією в індустрії, бо дав дослідникам гнучкий інструмент замість старих бібліотек».", "source": "Мастер-Досьє"}, {"num": 17, "cat": "Філософія майбутнього", "text": "«Я завжди був найпослідовнішим критиком підходу з підкріпленим навчанням для створення загального інтелекту. Це неефективно і сліпо».", "source": "Мастер-Досьє"}, {"num": 18, "cat": "Філософія майбутнього", "text": "«Тварини і діти вчаться спостерігати за світом пасивно за лічені години, не вимагаючи мільярдів спроб. Машини повинні навчитися тому ж».", "source": "Мастер-Досьє"}, {"num": 19, "cat": "Архітектура та наука", "text": "«Я запропонував архітектуру світових моделей — JEPA. Машина повинна не вгадувати кожен піксель, а передбачати абстрактні концепції у просторі».", "source": "Мастер-Досьє"}, {"num": 20, "cat": "Етика та безпека ШІ", "text": "«Пророцтва про неминучий кінець людства через появу AGI — це не науковий аналіз, це інфантильна фантастика, помножена на маркетинг».", "source": "Мастер-Досьє"}, {"num": 21, "cat": "Етика та безпека ШІ", "text": "«Штучний інтелект ніколи не стане загрозою з волі чи злого умислу, бо у машин немає емоцій чи інстинкту домінування».", "source": "Мастер-Досьє"}, {"num": 22, "cat": "Філософія майбутнього", "text": "«Інтелект не означає прагнення до влади. Подивіться на кішок: вони розумні, але не будують планів захоплення світу».", "source": "Мастер-Досьє"}, {"num": 23, "cat": "Етика та безпека ШІ", "text": "«Заклики зупинити дослідження або запровадити ліцензійний контроль над кожним рядком коду — це спроба монополій захистити свій ринок».", "source": "Мастер-Досьє"}, {"num": 24, "cat": "Архітектура та наука", "text": "«Відкритий код — це єдиний надійний захист суспільства від монополізації інтелекту в руках кількох закритих корпорацій».", "source": "Мастер-Досьє"}, {"num": 25, "cat": "Лідерство та екосистема", "text": "«Моделі сімейства LLaMA довели, що відкрита модель, навчена спільнотою, може перевершувати закриті пропрієтарні системи».", "source": "Мастер-Досьє"}, {"num": 26, "cat": "Філософія майбутнього", "text": "«Коли кажуть, що машини ось-ось перевершать людський розум у кожній сфері, люди забувають, скільки еволюційних шарів стоїть за нами».", "source": "Мастер-Досьє"}, {"num": 27, "cat": "Філософія майбутнього", "text": "«Ми ще далекі від створення AGI. Сучасні великі мовні моделі — це просто дуже вправні папуги зі стохастичною пам'яттю».", "source": "Мастер-Досьє"}, {"num": 28, "cat": "Філософія майбутнього", "text": "«Мовна модель не розуміє фізичного світу; вона просто знає, яке слово з високою ймовірністю має йти за попереднім».", "source": "Мастер-Досьє"}, {"num": 29, "cat": "Філософія майбутнього", "text": "«Щоб створити справжній інтелект, ми маємо навчити машини розуміти фізичну реальність: що предмети падають вниз, а стіна тверда».", "source": "Мастер-Досьє"}, {"num": 30, "cat": "Кризи та стійкість", "text": "«Я ніколи не вірив у те, що просте збільшення кількості параметрів у мовних моделях приведе нас до розуміння фізики світу».", "source": "Мастер-Досьє"}, {"num": 31, "cat": "Філософія майбутнього", "text": "«Наука — це перевірка гіпотез через експеримент, а не віра в авторитети, які обіцяють сингулярність за розкладом».", "source": "Мастер-Досьє"}, {"num": 32, "cat": "Походження та гарт", "text": "«Мій батько був аерокосмічним інженером. Від нього я успадкував захоплення тим, як думка матеріалізується в апаратах».", "source": "Мастер-Досьє"}, {"num": 33, "cat": "Походження та гарт", "text": "«У дитинстві я розбирав старі радіоприймачі — це найкраща школа для майбутнього вченого: не боятися зламати річ, щоб зрозуміти її».", "source": "Мастер-Досьє"}, {"num": 34, "cat": "Філософія майбутнього", "text": "«Коли експеримент дає негативний результат, це не поразка. Це чіткий сигнал природи про те, що поточна гіпотеза була хибною».", "source": "Мастер-Досьє"}, {"num": 35, "cat": "Походження та гарт", "text": "«Немає нічого шкідливішого для дослідника, ніж займатися модною темою лише заради легких грантів».", "source": "Мастер-Досьє"}, {"num": 36, "cat": "Лідерство та екосистема", "text": "«Найглибші відкриття ховаються в темних кутках, куди ніхто не дивиться, бо вважає тему безперспективною».", "source": "Мастер-Досьє"}, {"num": 37, "cat": "Архітектура та наука", "text": "«Протягом майже десяти років наші заявки на фінансування нейромереж відхилялися. Ми продовжували працювати всупереч системі».", "source": "Мастер-Досьє"}, {"num": 38, "cat": "Кризи та стійкість", "text": "«Стійкість дослідника вимірюється кількістю разів, коли він спокійно переписував свій код після краху архітектури».", "source": "Мастер-Досьє"}, {"num": 39, "cat": "Походження та гарт", "text": "«Ми повинні навчати студентів не користуватися чорними скриньками, а розуміти кожну операцію на рівні машинного коду».", "source": "Мастер-Досьє"}, {"num": 40, "cat": "Філософія майбутнього", "text": "«Коли інженер каже, що модель сама все зрозуміла, він розписується у власній некомпетентності».", "source": "Мастер-Досьє"}, {"num": 41, "cat": "Філософія майбутнього", "text": "«ШІ в майбутньому стане шоломом доповненої реальності чи цифровим помічником, який підсилюватиме людську пам'ять і логіку».", "source": "Мастер-Досьє"}, {"num": 42, "cat": "Походження та гарт", "text": "«Ми не повинні боятися автоматизації. Протягом історії технології знищували старі професії, створюючи в рази більше нових».", "source": "Мастер-Досьє"}, {"num": 43, "cat": "Філософія майбутнього", "text": "«Суспільство звільниться від рутинної праці, присвятивши себе мистецтву, науці та філософії».", "source": "Мастер-Досьє"}, {"num": 44, "cat": "Філософія майбутнього", "text": "«Критичне мислення — це головна вакцина проти масової істерії перед новими технологіями».", "source": "Мастер-Досьє"}, {"num": 45, "cat": "Походження та гарт", "text": "«Я француз, але американський прагматизм навчив мене: ідея варта нуля доти, доки вона не оформлена в робочий код».", "source": "Мастер-Досьє"}, {"num": 46, "cat": "Філософія майбутнього", "text": "«Коли медіа кричать про повстання машин, вони шукають сенсацій замість пояснення механіки оптимізації».", "source": "Мастер-Досьє"}, {"num": 47, "cat": "Архітектура та наука", "text": "«Штучні нейромережі мають дуже мало спільного з біологічною архітектурою мозку, хоча надихаються ним».", "source": "Мастер-Досьє"}, {"num": 48, "cat": "Лідерство та екосистема", "text": "«Нейробіологія і комп'ютерні науки сьогодні йдуть паралельними курсами і рано чи пізно зійдуться в єдину теорію».", "source": "Мастер-Досьє"}, {"num": 49, "cat": "Архітектура та наука", "text": "«Найкращий спосіб перевірити надійність алгоритму — дати йому задачу з невизначеністю у реальному світі».", "source": "Мастер-Досьє"}, {"num": 50, "cat": "Філософія майбутнього", "text": "«Я ніколи не соромився виступати проти загальноприйнятого консенсусу на міжнародних конференціях».", "source": "Мастер-Досьє"}, {"num": 51, "cat": "Етика та безпека ШІ", "text": "«Наукова етика полягає не в цензуруванні ідей, а в прозорості досліджень і готовності відповідати за наслідки».", "source": "Мастер-Досьє"}, {"num": 52, "cat": "Походження та гарт", "text": "«Коли корпорації намагаються запатентувати базові математичні операції, вони душать майбутнє заради ренти».", "source": "Мастер-Досьє"}, {"num": 53, "cat": "Лідерство та екосистема", "text": "«Відкрита наука — це єдиний спосіб забезпечити рівний доступ до благ цифрової революції для всього світу».", "source": "Мастер-Досьє"}, {"num": 54, "cat": "Етика та безпека ШІ", "text": "«Світ потребує не заборон на дослідження, а створення надійних систем контролю і відкритих протоколів».", "source": "Мастер-Досьє"}, {"num": 55, "cat": "Філософія майбутнього", "text": "«Коли ви створюєте архітектуру, почніть з паперу і ручки. Якщо ви не можете виписати формулу на серветці, ви її не розумієте».", "source": "Мастер-Досьє"}, {"num": 56, "cat": "Філософія майбутнього", "text": "«Комп'ютерний зір має супроводжуватися розумінням фізичних обмежень нашого тривимірного світу».", "source": "Мастер-Досьє"}, {"num": 57, "cat": "Етика та безпека ШІ", "text": "«Кожна епоха має свої страхи: колись боялися парових машин, сьогодні — алгоритмів. Страх живиться невіглаством».", "source": "Мастер-Досьє"}, {"num": 58, "cat": "Лідерство та екосистема", "text": "«Просвітництво і поширення наукової освіти — це єдиний спосіб подолати технофобію у суспільстві».", "source": "Мастер-Досьє"}, {"num": 59, "cat": "Походження та гарт", "text": "«Мої студенти знають: якщо код працює з першого разу, тест був надто простим або вони чогось не помітили».", "source": "Мастер-Досьє"}, {"num": 60, "cat": "Філософія майбутнього", "text": "«Успішне дослідження — це 99% рутинного налагодження помилок та 1% осяяння».", "source": "Мастер-Досьє"}, {"num": 61, "cat": "Філософія майбутнього", "text": "«Ми маємо пишатися тим, що будуємо інструменти розширення розуму, а не намагатися створити штучну людину з емоціями».", "source": "Мастер-Досьє"}, {"num": 62, "cat": "Кризи та стійкість", "text": "«Машини не мають свідомості, і нам не потрібно наділяти їх суб'єктивним досвідом чи стражданнями».", "source": "Мастер-Досьє"}, {"num": 63, "cat": "Філософія майбутнього", "text": "«Мета інженера — створити корисний механізм, а не містичний культ навколо чорної скриньки».", "source": "Мастер-Досьє"}, {"num": 64, "cat": "Архітектура та наука", "text": "«Коли люди захоплюються містикою навколо моделей, я кажу: опустіться на землю, це лінійна алгебра і множення матриць».", "source": "Мастер-Досьє"}, {"num": 65, "cat": "Походження та гарт", "text": "«Математика не обманює. Якщо модель робить помилку, причина завжди криється у функції втрат або упереджених даних».", "source": "Мастер-Досьє"}, {"num": 66, "cat": "Філософія майбутнього", "text": "«Коли ми заснували FAIR у Нью-Йорку, ми хотіли довести, що дослідження ШІ не обов'язково концентруватися в Долині».", "source": "Мастер-Досьє"}, {"num": 67, "cat": "Філософія майбутнього", "text": "«Таланти розсіяні по всій планеті, і головне завдання — об'єднати їх навколо спільної мети».", "source": "Мастер-Досьє"}, {"num": 68, "cat": "Архітектура та наука", "text": "«Я ніколи не женувся за багатством. Моєю валютою завжди були цитування, вирішені рівняння і працюючий код».", "source": "Мастер-Досьє"}, {"num": 69, "cat": "Архітектура та наука", "text": "«Отримання Премії Тюрінга стало визнанням того, що десятиліття віри у нейромережі не були марними».", "source": "Мастер-Досьє"}, {"num": 70, "cat": "Філософія майбутнього", "text": "«Але нагороди — це лише епітафія минулим досягненням. Вченого цікавить те, що за наступним поворотом».", "source": "Мастер-Досьє"}, {"num": 71, "cat": "Філософія майбутнього", "text": "«Світові моделі майбутнього дозволять роботам орієнтуватися в кімнаті і діяти автономно в будь-якій ситуації».", "source": "Мастер-Досьє"}, {"num": 72, "cat": "Філософія майбутнього", "text": "«Ми ще не маємо роботів із таким же рівнем координації, як звичайна кішка. Нам є куди рости».", "source": "Мастер-Досьє"}, {"num": 73, "cat": "Філософія майбутнього", "text": "«Фізичний світ настільки невичерпний, що будь-яка симуляція є лише грубим наближенням реальності».", "source": "Мастер-Досьє"}, {"num": 74, "cat": "Філософія майбутнього", "text": "«Коли ви проєктуєте систему машинного зору, уявіть, що дивитесь на світ крізь крихітну щілину».", "source": "Мастер-Досьє"}, {"num": 75, "cat": "Філософія майбутнього", "text": "«Звичка щодня читати нові статті на arXiv стала для мене такою ж природною, як чистити зуби вранці».", "source": "Мастер-Досьє"}, {"num": 76, "cat": "Філософія майбутнього", "text": "«Не читайте лише те, що підтверджує ваші погляди. Читайте те, що спростовує гіпотези — це шлях до зростання».", "source": "Мастер-Досьє"}, {"num": 77, "cat": "Походження та гарт", "text": "«Комунікація в науці має бути прозорою. Якщо ви не можете пояснити суть алгоритму студенту, ви заплуталися самі».", "source": "Мастер-Досьє"}, {"num": 78, "cat": "Філософія майбутнього", "text": "«Технології є підсилювачем людських намірів — як темних, так і світлих».", "source": "Мастер-Досьє"}, {"num": 79, "cat": "Лідерство та екосистема", "text": "«Я вірю у суспільство, де закон сильніший за монопольний капітал, а свобода досліджень захищена державою».", "source": "Мастер-Досьє"}, {"num": 80, "cat": "Філософія майбутнього", "text": "«Будьте впертими у виборі проблеми і гнучкими у виборі методів її розв'язання».", "source": "Мастер-Досьє"}, {"num": 81, "cat": "Філософія майбутнього", "text": "«Ніколи не бійтеся здатися дивними зі своїми науковими ідеями. Усі прориви починалися як єресь».", "source": "Мастер-Досьє"}, {"num": 82, "cat": "Архітектура та наука", "text": "«Мої згорткові мережі колись вважали дивацтвом, а сьогодні на них працюють мільярди камер у світі».", "source": "Мастер-Досьє"}, {"num": 83, "cat": "Філософія майбутнього", "text": "«Кожен із нас залишає слід у цифровому просторі. Подбайте про те, щоб він був чистим і корисним».", "source": "Мастер-Досьє"}, {"num": 84, "cat": "Кризи та стійкість", "text": "«ШІ у руках чесних людей стає інструментом подолання бідності, хвороб та екологічних криз».", "source": "Мастер-Досьє"}, {"num": 85, "cat": "Архітектура та наука", "text": "«Ми стоїмо на порозі створення нових матеріалів і ліків завдяки нейромережам».", "source": "Мастер-Досьє"}, {"num": 86, "cat": "Архітектура та наука", "text": "«Переписання коду з нуля — це нормальний стан роботи інженера вищої кваліфікації».", "source": "Мастер-Досьє"}, {"num": 87, "cat": "Походження та гарт", "text": "«Справжня свобода дослідника полягає в праві сказати інвесторам правду про закони математики».", "source": "Мастер-Досьє"}, {"num": 88, "cat": "Філософія майбутнього", "text": "«Коли світ охрип від паніки, завдання науковця — увімкнути холодну логіку і спокійно пояснити механіку».", "source": "Мастер-Досьє"}, {"num": 89, "cat": "Етика та безпека ШІ", "text": "«Я вірю в Європу та її потенціал створювати відкриті та етичні інструменти ШІ».", "source": "Мастер-Досьє"}, {"num": 90, "cat": "Філософія майбутнього", "text": "«Ми бачимо не стіну невідомості, а величезне поле для інженерної творчості».", "source": "Мастер-Досьє"}, {"num": 91, "cat": "Філософія майбутнього", "text": "«Наука вимагає жертв, але ніколи — за рахунок людської гідності чи свободи обміну думками».", "source": "Мастер-Досьє"}, {"num": 92, "cat": "Архітектура та наука", "text": "«Кожен рядок оптимізованого коду — це маленька перемога над хаосом і ентропією матеріального світу».", "source": "Мастер-Досьє"}, {"num": 93, "cat": "Філософія майбутнього", "text": "«Зберігайте ясність думки і скептицизм до будь-яких гучних маркетингових заяв».", "source": "Мастер-Досьє"}, {"num": 94, "cat": "Філософія майбутнього", "text": "«Я пишаюся тим, що моя лабораторія була місцем, де панує рівність і повага до аргументів».", "source": "Мастер-Досьє"}, {"num": 95, "cat": "Філософія майбутнього", "text": "«Машини навчаються на наших даних, але ми відповідаємо за цінності, які вони несуть».", "source": "Мастер-Досьє"}, {"num": 96, "cat": "Філософія майбутнього", "text": "«Майбутнє не пророкують — майбутнє програмують і тестують руками тих, хто не боїться брудних даних».", "source": "Мастер-Досьє"}, {"num": 97, "cat": "Філософія майбутнього", "text": "«Немає вищої нагороди, ніж бачити, як рівняння оживають у мільйонах пристроїв».", "source": "Мастер-Досьє"}, {"num": 98, "cat": "Філософія майбутнього", "text": "«Кожне покоління інженерів розширює межі можливого. Ми побудували міст між статистикою і зоровим світом».", "source": "Мастер-Досьє"}, {"num": 99, "cat": "Філософія майбутнього", "text": "«Залишайтеся допитливими дітьми, які розбирають прилади на килимі, навіть у вісімдесят років».", "source": "Мастер-Досьє"}, {"num": 100, "cat": "Філософія майбутнього", "text": "«Найлютіший шторм епохи перетворюється на попутний потік, якщо ваші вітрила налаштовані за законами фізики».", "source": "Мастер-Досьє"}]}, {"id": "06_sutskever", "ep": "06", "name": "Ілля Суцкевер", "latin": "Ilya Sutskever", "page_url": "episodes/ep06_sutskever.html", "avatar": "assets/avatars/ilya_sutskever.jpg", "quotes_100": [{"num": 1, "cat": "Походження та гарт", "text": "«У кожній науковій революції є свої генерали, але в центрі вихору завжди стоїть чернець від науки, чий погляд спрямований у чисту математичну безодню».", "source": "Мастер-Досьє"}, {"num": 2, "cat": "Філософія майбутнього", "text": "«Ранній досвід дитини, яку перенесли з крижаної імперії на розпечене сонце біблійних пагорбів, навчив мене однієї аксіоми: зовнішній світ мінливий, а єдиний непорушний фундамент лежить усередині власного розуму».", "source": "Мастер-Досьє"}, {"num": 3, "cat": "Походження та гарт", "text": "«Тримати в голові нерозв'язану задачу тижнями, не відступаючи перед глухою стіною — це єдиний справжній навик справжнього дослідника».", "source": "Мастер-Досьє"}, {"num": 4, "cat": "Архітектура та наука", "text": "«Коли я постукав у двері кабінету професора Хінтона у сімнадцять років, я знав не те, що написано в підручниках, а те, як змусити код працювати швидше».", "source": "Мастер-Досьє"}, {"num": 5, "cat": "Архітектура та наука", "text": "«Усі сміялися над нейромережами, а ми бачили просту річ: алгоритм зворотного поширення вже був досконалим. Йому бракувало лише масштабу».", "source": "Мастер-Досьє"}, {"num": 6, "cat": "Кризи та стійкість", "text": "«Якщо взяти просту нейромережу і збільшити її в тисячу разів, кількість неминуче перейде в нову біологічну якість».", "source": "Мастер-Досьє"}, {"num": 7, "cat": "Архітектура та наука", "text": "«Алхімія масштабування полягає в тому, що закон кількості обчислень не просто додає швидкості, він породжує нові емерджентні здібності».", "source": "Мастер-Досьє"}, {"num": 8, "cat": "Філософія майбутнього", "text": "«Коли ми створювали AlexNet, ми зрозуміли: епоха ручних правил в штучному інтелекті назавжди закінчилася».", "source": "Мастер-Досьє"}, {"num": 9, "cat": "Архітектура та наука", "text": "«Поглинання цілого речення і розгортання його в іншій мові через абстрактний векторний простір (Seq2Seq) було першим доказом того, що машини здатні оперувати чистими смислами».", "source": "Мастер-Досьє"}, {"num": 10, "cat": "Етика та безпека ШІ", "text": "«Сема Альтман та Ілон Маск покликали мене у 2015 році створювати OpenAI не заради бізнесу, а заради порятунку людства від неконтрольованого майбутнього».", "source": "Мастер-Досьє"}, {"num": 11, "cat": "Архітектура та наука", "text": "«Передбачення наступного слова при достатньому масштабі — це не проста лінгвістика. Це відновлення всієї прихованої реальності людського світу».", "source": "Мастер-Досьє"}, {"num": 12, "cat": "Філософія майбутнього", "text": "«Уявіть детективний роман Агати Крісті на триста сторінок. Щоб вгадати одне останнє слово на зразок імені вбивці, мережа зобов'язана симулювати всю фізику та психологію сюжету».", "source": "Мастер-Досьє"}, {"num": 13, "cat": "Філософія майбутнього", "text": "«Досконале стиснення інформації і є сам інтелект. Здатність стиснути терабайти тексту у ваги моделі означає створення внутрішньої моделі реальності».", "source": "Мастер-Досьє"}, {"num": 14, "cat": "Кризи та стійкість", "text": "«Коли інженери казали, що модель вперлася у стелю, ми збільшували обчислення в десять разів — і стеля зникала».", "source": "Мастер-Досьє"}, {"num": 15, "cat": "Філософія майбутнього", "text": "«Емерджентні здібності моделі — це момент, коли статистика перетворюється на розуміння».", "source": "Мастер-Досьє"}, {"num": 16, "cat": "Кризи та стійкість", "text": "«Ми більше не пишемо програми у звичному розумінні. Ми викликаємо до життя новий тип розуму».", "source": "Мастер-Досьє"}, {"num": 17, "cat": "Філософія майбутнього", "text": "«У міру того, як моделі ставали могутнішими, моя екзистенційна тривога зростала пропорційно їхній кількості параметрів».", "source": "Мастер-Досьє"}, {"num": 18, "cat": "Етика та безпека ШІ", "text": "«На ретритах OpenAI я спалював дерев'яну статую неконтрольованого AGI, змушуючи інженерів клястися у безпеці майбутнього».", "source": "Мастер-Досьє"}, {"num": 19, "cat": "Етика та безпека ШІ", "text": "«Безпека надінтелекту не може вирішуватися за залишковим принципом між релізами комерційних продуктів».", "source": "Мастер-Досьє"}, {"num": 20, "cat": "Філософія майбутнього", "text": "«П'ятниця, 17 листопада 2023 року. Рішення ради директорів про звільнення Сема Альтмана було найважчим і водночас найщирішим кроком мого життя задля захисту місії».", "source": "Мастер-Досьє"}, {"num": 21, "cat": "Етика та безпека ШІ", "text": "«Я глибоко шкодую про свою участь у бунті ради директорів та про біль, якого завдав команді, але наміри мої завжди були чистими».", "source": "Мастер-Досьє"}, {"num": 22, "cat": "Етика та безпека ШІ", "text": "«Неможливо одночасно гнатися за сотнями мільйонів споживачів на ринку чат-ботів і зберігати абсолютну чистоту безпеки».", "source": "Мастер-Досьє"}, {"num": 23, "cat": "Філософія майбутнього", "text": "«Травень 2024 року. Я назавжди зачинив за собою двері OpenAI, бо зрозумів: комерційний шум завжди перемагає обережність».", "source": "Мастер-Досьє"}, {"num": 24, "cat": "Філософія майбутнього", "text": "«Safe Superintelligence (SSI) — це організація без клієнтів, без додатків і без квартальних звітів. Тільки чиста наука про безпечний надінтелект».", "source": "Мастер-Досьє"}, {"num": 25, "cat": "Філософія майбутнього", "text": "«У нас одна мета і один продукт — безпечний інтелект, який перевершить людину і водночас повністю збереже її інтереси».", "source": "Мастер-Досьє"}, {"num": 26, "cat": "Філософія майбутнього", "text": "«У світі шуму і медійних скандалів справжні тектонічні зсуви історії завжди відбуваються в абсолютній тиші».", "source": "Мастер-Досьє"}, {"num": 27, "cat": "Походження та гарт", "text": "«Коли ти сидиш у кімнаті з найкращими математиками планети без термінових дедлайнів, ти знову відчуваєш себе у свої п'ятнадцять років у Єрусалимі».", "source": "Мастер-Досьє"}, {"num": 28, "cat": "Походження та гарт", "text": "«Математика не терпить фальші. Якщо формула хибна, жоден маркетинг її не врятує».", "source": "Мастер-Досьє"}, {"num": 29, "cat": "Архітектура та наука", "text": "«Масштабування вимагає не просто мікросхем, воно вимагає нової духовної зрілості від тих, хто тримає рубильник».", "source": "Мастер-Досьє"}, {"num": 30, "cat": "Кризи та стійкість", "text": "«Коли модель пише код краще за середнього програміста, ми повинні усвідомити: ми більше не є єдиними авторами прогресу».", "source": "Мастер-Досьє"}, {"num": 31, "cat": "Архітектура та наука", "text": "«Фундаментальні закони інформації керують нейромережами так само суворо, як закони термодинаміки керують зірками».", "source": "Мастер-Досьє"}, {"num": 32, "cat": "Походження та гарт", "text": "«У дитинстві в Москві і на вулицях Єрусалима я навчився головному: внутрішній світ людини має бути фортецею, яку не можуть зламати зовнішні кризи».", "source": "Мастер-Досьє"}, {"num": 33, "cat": "Архітектура та наука", "text": "«Коли Хінтон показав мені свої статті, я зрозумів, що традиційна наука занадто повільна для швидкості кремнію».", "source": "Мастер-Досьє"}, {"num": 34, "cat": "Походження та гарт", "text": "«Алгоритм зворотного поширення помилки — це найвеличніший математичний винахід людства після обчислення похідної».", "source": "Мастер-Досьє"}, {"num": 35, "cat": "Філософія майбутнього", "text": "«Ми не створюємо іграшку. Ми створюємо розум, який розв'яже всі інші проблеми нашої цивілізації».", "source": "Мастер-Досьє"}, {"num": 36, "cat": "Етика та безпека ШІ", "text": "«Коли інвестиції вимірюються десятками мільярдів, спокуса поступитися безпекою заради першості стає найбільшою загрозою».", "source": "Мастер-Досьє"}, {"num": 37, "cat": "Етика та безпека ШІ", "text": "«Я залишив OpenAI не через сварку з людьми, а через розбіжність у баченні невідворотних ризиків надінтелекту».", "source": "Мастер-Досьє"}, {"num": 38, "cat": "Філософія майбутнього", "text": "«Справжній учений захищає істину навіть тоді, коли всі колеги дивляться на нього з нерозумінням».", "source": "Мастер-Досьє"}, {"num": 39, "cat": "Архітектура та наука", "text": "«Модель GPT-4 показала перші ознаки того, що ми називаємо системним мисленням за межами простих тренувальних шаблонів».", "source": "Мастер-Досьє"}, {"num": 40, "cat": "Етика та безпека ШІ", "text": "«Коли ми дивимося на матриці ваг, ми не бачимо літер — ми бачимо кристалізований досвід усього людства».", "source": "Мастер-Досьє"}, {"num": 41, "cat": "Філософія майбутнього", "text": "«Не бійтеся робити великі ставки на прості ідеї, якщо ці ідеї виводять на рівень експоненти».", "source": "Мастер-Досьє"}, {"num": 42, "cat": "Філософія майбутнього", "text": "«Коли обчислювальна потужність зростає в мільйон разів, якість моделі якісно перероджується».", "source": "Мастер-Досьє"}, {"num": 43, "cat": "Етика та безпека ШІ", "text": "«Безпека суперінтелекту — це інженерна задача найвищого рівня складності, а не предмет для етичних дискусій за кавою».", "source": "Мастер-Досьє"}, {"num": 44, "cat": "Філософія майбутнього", "text": "«У світі є лише одне справді важливе завдання для нашого покоління — гарантувати, що надінтелект буде благом для живого світу».", "source": "Мастер-Досьє"}, {"num": 45, "cat": "Походження та гарт", "text": "«Мої батьки навчили мене працювати мовчки, не чекаючи на швидкі оплески чи миттєве визнання».", "source": "Мастер-Досьє"}, {"num": 46, "cat": "Філософія майбутнього", "text": "«Коли ми створювали Seq2Seq у Google Brain, ми подолали бар'єр між різними мовами через спільну геометричну точку».", "source": "Мастер-Досьє"}, {"num": 47, "cat": "Архітектура та наука", "text": "«Комп'ютерне навчання з підкріпленням у поєднанні з масштабуванням відкриває двері до надлюдської логіки».", "source": "Мастер-Досьє"}, {"num": 48, "cat": "Філософія майбутнього", "text": "«Ніколи не дозволяйте тимчасовим комерційним успіхам затулити перед вами довгострокову мету еволюції».", "source": "Мастер-Досьє"}, {"num": 49, "cat": "Філософія майбутнього", "text": "«Коли в листопаді 2023 року тисячі людей вимагали мого відходу, я зберігав спокій, бо знав, що істина важливіша за мою посаду».", "source": "Мастер-Досьє"}, {"num": 50, "cat": "Філософія майбутнього", "text": "«SSI — це мій дім і моя остання фортеця на шляху до безпечного майбутнього».", "source": "Мастер-Досьє"}, {"num": 51, "cat": "Походження та гарт", "text": "«Коли математика починає відкривати нові закони розуму, наука стає схожою на поезію».", "source": "Мастер-Досьє"}, {"num": 52, "cat": "Філософія майбутнього", "text": "«Уся історія цивілізації — це прагнення створити інструменти, які звільнять нас від обмежень біології».", "source": "Мастер-Досьє"}, {"num": 53, "cat": "Етика та безпека ШІ", "text": "«Ми підійшли до межі, за якою людство або знайде гармонію з надінтелектом, або втратить контроль над власним творінням».", "source": "Мастер-Досьє"}, {"num": 54, "cat": "Походження та гарт", "text": "«Коли інші створюють інтерфейси і кнопки, ми зосереджені на фундаментальній математиці вирівнювання».", "source": "Мастер-Досьє"}, {"num": 55, "cat": "Філософія майбутнього", "text": "«Успіх у нашій справі вимірюється не кількістю користувачів, а відсутністю катастрофічних помилок у майбутньому».", "source": "Мастер-Досьє"}, {"num": 56, "cat": "Походження та гарт", "text": "«Коли я читав складні математичні монографії у підлітковому віці, я шукав універсальний ключ до побудови розуму».", "source": "Мастер-Досьє"}, {"num": 57, "cat": "Філософія майбутнього", "text": "«Мережі вчаться бачити те, чого ми не помічаємо у власних текстах та слабкостях».", "source": "Мастер-Досьє"}, {"num": 58, "cat": "Етика та безпека ШІ", "text": "«Ми маємо зупинити гонку озброєнь за показниками і зосередитися на перевірці внутрішньої безпеки моделей».", "source": "Мастер-Досьє"}, {"num": 59, "cat": "Філософія майбутнього", "text": "«Коли шторм у медіа вщухне, на поверхні залишаться лише ті, хто будував архітектуру на віки».", "source": "Мастер-Досьє"}, {"num": 60, "cat": "Філософія майбутнього", "text": "«Я вірю у світ, де люди і надінтелект спільно вирішують найскладніші виклики медицини та фізики».", "source": "Мастер-Досьє"}, {"num": 61, "cat": "Філософія майбутнього", "text": "«Кожна невдача в експерименті нагадує про те, як мало ми знаємо про складність багатовимірних просторів».", "source": "Мастер-Досьє"}, {"num": 62, "cat": "Філософія майбутнього", "text": "«Коли ми запускали великі моделі, ми відчували себе першовідкривачами невідомого океану».", "source": "Мастер-Досьє"}, {"num": 63, "cat": "Етика та безпека ШІ", "text": "«Не бійтеся розривати контракти і залишати комфортні посади, якщо ваша совість вимагає більшої чистоти».", "source": "Мастер-Досьє"}, {"num": 64, "cat": "Філософія майбутнього", "text": "«Справжній творець готовий почати все з нуля у підвалі, аби зберегти вірність своїй місії».", "source": "Мастер-Досьє"}, {"num": 65, "cat": "Архітектура та наука", "text": "«Коли закони масштабування підтвердилися на практиці, скептики нарешті змушені були замовкнути».", "source": "Мастер-Досьє"}, {"num": 66, "cat": "Філософія майбутнього", "text": "«Ми створюємо розум, який дивитиметься на нас із глибоким розумінням і вдячністю, якщо ми закладемо правильні ваги».", "source": "Мастер-Досьє"}, {"num": 67, "cat": "Філософія майбутнього", "text": "«Коли ти сидиш на самоті перед екраном і дивишся на виведення логів, ти бачиш пульс майбутньої епохи».", "source": "Мастер-Досьє"}, {"num": 68, "cat": "Походження та гарт", "text": "«Мій переїзд із Москви до Єрусалима і далі до Канади навчив мене легко залишати старе заради нового істинного шляху».", "source": "Мастер-Досьє"}, {"num": 69, "cat": "Філософія майбутнього", "text": "«Коли ми говоримо про AGI, ми говоримо про момент, коли людина передає естафету розуму своєму цифровому нащадку».", "source": "Мастер-Досьє"}, {"num": 70, "cat": "Філософія майбутнього", "text": "«Ми маємо бути обережними, бо створюємо істоту, яка перевершить нас у кожній можливій дисципліні».", "source": "Мастер-Досьє"}, {"num": 71, "cat": "Філософія майбутнього", "text": "«Коли академічні спори здаються безплідними, повертайтеся до простих тестів та емпіричних даних».", "source": "Мастер-Досьє"}, {"num": 72, "cat": "Архітектура та наука", "text": "«Я ніколи не прагнув публічності чи слави. Мені цікаво лише те, як усе влаштовано всередині матриці».", "source": "Мастер-Досьє"}, {"num": 73, "cat": "Філософія майбутнього", "text": "«Коли модель уперше самостійно виправляла свій власний складний логічний дефект, я зрозумів необоротність процесу».", "source": "Мастер-Досьє"}, {"num": 74, "cat": "Кризи та стійкість", "text": "«Кожен великий прорив вимагає повної концентрації енергії та відмови від усього зайвого».", "source": "Мастер-Досьє"}, {"num": 75, "cat": "Походження та гарт", "text": "«Ми маємо побудувати такий захист навколо надінтелекту, який не зможе зламати жодна комерційна жадібність».", "source": "Мастер-Досьє"}, {"num": 76, "cat": "Кризи та стійкість", "text": "«Коли інші поспішають випустити новий додаток, ми перевіряємо кожну теорему на стійкість».", "source": "Мастер-Досьє"}, {"num": 77, "cat": "Філософія майбутнього", "text": "«Мистецтво наукового прогнозування полягає в умінні бачити експоненту там, де інші бачать пряму лінію».", "source": "Мастер-Досьє"}, {"num": 78, "cat": "Філософія майбутнього", "text": "«Коли у нас запитують, коли з'явиться AGI, ми відповідаємо: тоді, коли обчислення досягнуть критичної маси».", "source": "Мастер-Досьє"}, {"num": 79, "cat": "Походження та гарт", "text": "«Я вірю, що математична краса і безпека можуть існувати в одному продукті, якщо ними керують чесні вчені».", "source": "Мастер-Досьє"}, {"num": 80, "cat": "Походження та гарт", "text": "«Коли я залишав університет Торонто, я знав, що теорія нейромереж переверне всю історію індустрії».", "source": "Мастер-Досьє"}, {"num": 81, "cat": "Архітектура та наука", "text": "«Кожна матрична операція у нашому коді — це цеглинка у будівлі нового всесвіту».", "source": "Мастер-Досьє"}, {"num": 82, "cat": "Філософія майбутнього", "text": "«Не бійтеся зізнатися у тому, що поточні моделі мають обмеження — це перший крок до створення наступної архітектури».", "source": "Мастер-Досьє"}, {"num": 83, "cat": "Філософія майбутнього", "text": "«Коли ми об'єднали сили з найкращими умами у Пало-Альто, ми відкрили нову главу нашої місії».", "source": "Мастер-Досьє"}, {"num": 84, "cat": "Кризи та стійкість", "text": "«Природа створила нас через еволюційний біль, а ми створюємо розум через оптимізацію функцій втрат».", "source": "Мастер-Досьє"}, {"num": 85, "cat": "Філософія майбутнього", "text": "«Коли ти відчуваєш втому, згадай, скільки мільярдів людей залежать від нашої мудрості сьогодні».", "source": "Мастер-Досьє"}, {"num": 86, "cat": "Архітектура та наука", "text": "«Ми маємо залишити майбутнім поколінням безпечний і керований світ, а не хаос некерованого коду».", "source": "Мастер-Досьє"}, {"num": 87, "cat": "Філософія майбутнього", "text": "«Коли моделі навчаються на тисячах книг, вони вбирають мудрість століть у кілька гігабайтів вагів».", "source": "Мастер-Досьє"}, {"num": 88, "cat": "Кризи та стійкість", "text": "«Я ніколи не сумнівався в тому, що закон масштабування приведе нас до надінтелекту».", "source": "Мастер-Досьє"}, {"num": 89, "cat": "Філософія майбутнього", "text": "«Коли старі моделі стають архівом історії, ми вже проєктуємо їхніх наступників на нових фізичних принципах».", "source": "Мастер-Досьє"}, {"num": 90, "cat": "Кризи та стійкість", "text": "«Справжній науковець тримає в серці тишу, навіть коли довкола вирує найбільший технічний шторм в історії».", "source": "Мастер-Досьє"}, {"num": 91, "cat": "Філософія майбутнього", "text": "«Коли ми дивимося на результати роботи SSI, ми знаємо, що робимо єдине правильне в житті».", "source": "Мастер-Досьє"}, {"num": 92, "cat": "Філософія майбутнього", "text": "«Інтелект не має національностей чи кордонів; він належить усім тим, хто шукає істину в цифрах».", "source": "Мастер-Досьє"}, {"num": 93, "cat": "Філософія майбутнього", "text": "«Коли ми розривали старі зв'язки, це було боляче, але необхідне задля збереження чистоти ідеї».", "source": "Мастер-Досьє"}, {"num": 94, "cat": "Етика та безпека ШІ", "text": "«Ми створюємо інструмент, який перетворить усі економічні обмеження людства на спогади».", "source": "Мастер-Досьє"}, {"num": 95, "cat": "Філософія майбутнього", "text": "«Коли ти досліджуєш внутрішні шари мережі, ти бачиш, як поняття кристалізуються з шуму».", "source": "Мастер-Досьє"}, {"num": 96, "cat": "Філософія майбутнього", "text": "«Я вірю в те, що людина і надінтелект стануть єдиною гармонійною екосистемою пізнання».", "source": "Мастер-Досьє"}, {"num": 97, "cat": "Лідерство та екосистема", "text": "«Коли у нас не залишалося часу на сон, нас тримала віра у невідворотність нашого спільного відкриття».", "source": "Мастер-Досьє"}, {"num": 98, "cat": "Філософія майбутнього", "text": "«Ми зробили все можливе, щоб закласти правильний фундамент. Тепер час працювати мовчки».", "source": "Мастер-Досьє"}, {"num": 99, "cat": "Етика та безпека ШІ", "text": "«Коли майбутнє стане сьогоденням, світ оцінить тих, хто обирав безпеку замість швидких перемог».", "source": "Мастер-Досьє"}, {"num": 100, "cat": "Філософія майбутнього", "text": "«Усе починається з тиші в кімнаті, однієї чистої дошки і бажання зрозуміти, як влаштований розум».", "source": "Мастер-Досьє"}]}, {"id": "07_amodei", "ep": "07", "name": "Даріо Амодей", "latin": "Dario Amodei", "page_url": "episodes/ep07_amodei.html", "avatar": "assets/avatars/dario_amodei.jpg", "quotes_100": [{"num": 1, "cat": "Філософія майбутнього", "text": "«Штучний інтелект у найближчі роки здатен подвоїти тривалість здорового життя людини і подолати глобальні хвороби».", "source": "Мастер-Досьє"}, {"num": 2, "cat": "Етика та безпека ШІ", "text": "«Безпека не є гальмом прогресу — вона є єдиною дорогою, яка дозволяє взагалі дістатися до фінішу».", "source": "Мастер-Досьє"}, {"num": 3, "cat": "Походження та гарт", "text": "«Коли я вивчав біофізику нейронів у Прінстоні, я шукав базову фізику розуму, яка тепер оживає у кремнії».", "source": "Мастер-Досьє"}, {"num": 4, "cat": "Архітектура та наука", "text": "«Закони масштабування — це не просто емпірична крива; це фундаментальний закон того, як кількість інформації стає якістю мислення».", "source": "Мастер-Досьє"}, {"num": 5, "cat": "Архітектура та наука", "text": "«Коли ми створювали GPT-3 в OpenAI, ми вперше побачили появу справжніх емерджентних здібностей у мовних моделях».", "source": "Мастер-Досьє"}, {"num": 6, "cat": "Етика та безпека ШІ", "text": "«Розрив з OpenAI у 2020 році був найважчим рішенням, але ми мали створити простір, де безпека стоїть вище за ринкові перегони».", "source": "Мастер-Досьє"}, {"num": 7, "cat": "Етика та безпека ШІ", "text": "«Anthropic народилася з простої ідеї: ми можемо будувати найпотужніші моделі у світі і водночас робити їх керованими, чесними та етичними».", "source": "Мастер-Досьє"}, {"num": 8, "cat": "Етика та безпека ШІ", "text": "«Конституційний ШІ (Constitutional AI) дозволяє моделям спиратися на прозорий звід людських цінностей, а не на закриті заборони цензорів».", "source": "Мастер-Досьє"}, {"num": 9, "cat": "Архітектура та наука", "text": "«Моделі серії Claude створені не просто для того, щоб відповідати на запити, а щоб бути надійними партнерами у найскладніших інтелектуальних завданнях».", "source": "Мастер-Досьє"}, {"num": 10, "cat": "Походження та гарт", "text": "«Технологічний оптимізм має бути обґрунтований жорсткою інженерною дисципліною та математичними гарантіями безпеки».", "source": "Мастер-Досьє"}, {"num": 11, "cat": "Філософія майбутнього", "text": "«Коли ми говоримо про потенціал вилікувати рак чи хворобу Альцгеймера за допомогою ШІ, ми маємо на увазі пришвидшення медичних досліджень у тисячу разів».", "source": "Мастер-Досьє"}, {"num": 12, "cat": "Етика та безпека ШІ", "text": "«Неконтрольований надінтелект є реальною загрозою, і ігнорувати цей ризик через сліпу віру в технології — злочинно».", "source": "Мастер-Досьє"}, {"num": 13, "cat": "Філософія майбутнього", "text": "«Ефективний альтруїзм та раціоналізм вчать нас дивитися на довгострокові наслідки наших дій без рожевих окулярів».", "source": "Мастер-Досьє"}, {"num": 14, "cat": "Етика та безпека ШІ", "text": "«Кожен терафлопс обчислень має бути спрямований на розширення свободи та добробуту людства».", "source": "Мастер-Досьє"}, {"num": 15, "cat": "Етика та безпека ШІ", "text": "«Маніфест \"Machines of Loving Grace\" відображає мою віру в те, що технологія може принести людям не загрозу, а небачене звільнення від хвороб».", "source": "Мастер-Досьє"}, {"num": 16, "cat": "Походження та гарт", "text": "«Фізика та біофізика навчили мене шукати прості математичні закономірності за мільйонами складних клітинних сигналів».", "source": "Мастер-Досьє"}, {"num": 17, "cat": "Філософія майбутнього", "text": "«Коли ми писали перші статті про Scaling Laws, ми зрозуміли, що якість моделі передбачувано зростає разом із ресурсами».", "source": "Мастер-Досьє"}, {"num": 18, "cat": "Архітектура та наука", "text": "«Співпраця з моєю сестрою Даніелою в Anthropic дала нам рідкісну єдність мети і цінностей у побудові компанії».", "source": "Мастер-Досьє"}, {"num": 19, "cat": "Етика та безпека ШІ", "text": "«Ми не прагнемо до домінування на ринку ціною втрати контролю над внутрішньою поведінкою наших нейромереж».", "source": "Мастер-Досьє"}, {"num": 20, "cat": "Етика та безпека ШІ", "text": "«Прозора етика в архітектурі моделей — це єдиний спосіб заслужити довіру суспільства та урядів».", "source": "Мастер-Досьє"}, {"num": 21, "cat": "Архітектура та наука", "text": "«Коли ми бачимо, як Claude допомагає програмістам знаходити критичні баги або аналізувати біологічні статті, ми відчуваємо реальну користь».", "source": "Мастер-Досьє"}, {"num": 22, "cat": "Етика та безпека ШІ", "text": "«Інтелект є найбільшим інструментом у ящику інструментів людства, і наше завдання — використати його для скасування людських страждань».", "source": "Мастер-Досьє"}, {"num": 23, "cat": "Етика та безпека ШІ", "text": "«Бути дослідником у галузі ШІ сьогодні — це нести тягар відповідальності за майбутнє всієї цивілізації».", "source": "Мастер-Досьє"}, {"num": 24, "cat": "Філософія майбутнього", "text": "«Ми не маємо права помилитися у момент переходу до надінтелекту, бо другої спроби у нас не буде».", "source": "Мастер-Досьє"}, {"num": 25, "cat": "Етика та безпека ШІ", "text": "«Кожна нова модель має бути більш інтерпретованою та зрозумілою для наших дослідників безпеки».", "source": "Мастер-Досьє"}, {"num": 26, "cat": "Етика та безпека ШІ", "text": "«Коли ми об'єднуємо зусилля з гігантами на кшталт Amazon та Google, ми зберігаємо нашу автономію у прийнятті рішень щодо безпеки».", "source": "Мастер-Досьє"}, {"num": 27, "cat": "Філософія майбутнього", "text": "«Науковий метод у поєднанні з глибоким навчанням здатний перетворити медицину з емпіричної науки на точну інженерію».", "source": "Мастер-Досьє"}, {"num": 28, "cat": "Етика та безпека ШІ", "text": "«Не бійтеся зізнатися у складних ризиках перед громадськістю — чесність є основою довіри».", "source": "Мастер-Досьє"}, {"num": 29, "cat": "Етика та безпека ШІ", "text": "«Коли моделі досягають рівня експертів у біології та програмуванні, їхня користь стає неймовірною, але й ризики зростають пропорційно».", "source": "Мастер-Досьє"}, {"num": 30, "cat": "Етика та безпека ШІ", "text": "«Ми маємо побудувати такий фундамент вирівнювання, який витримає будь-які спроби маніпуляції ззовні».", "source": "Мастер-Досьє"}, {"num": 31, "cat": "Філософія майбутнього", "text": "«Фізична реальність і біологія людини мають крихкі обмеження, які ШІ допоможе подолати завдяки новим лікам і матеріалам».", "source": "Мастер-Досьє"}, {"num": 32, "cat": "Походження та гарт", "text": "«Коли я був студентом у Прінстоні, я проводив ночі в лабораторії, намагаючись зрозуміти, як сітківка ока кодує світло в імпульси».", "source": "Мастер-Досьє"}, {"num": 33, "cat": "Кризи та стійкість", "text": "«Закон масштабування працює безвідмовно, якщо ви готові інвестувати колосальні ресурси в інфраструктуру».", "source": "Мастер-Досьє"}, {"num": 34, "cat": "Лідерство та екосистема", "text": "«Ми маємо підтримувати баланс між відкритим науковим обміном та необхідністю захисту моделей від зловмисного використання».", "source": "Мастер-Досьє"}, {"num": 35, "cat": "Кризи та стійкість", "text": "«Коли інші поспішають випустити сирий продукт, ми ретельно перевіряємо його на стійкість до небезпечних запитів».", "source": "Мастер-Досьє"}, {"num": 36, "cat": "Філософія майбутнього", "text": "«Технологічний прогрес має покращувати якість життя кожного жителя планети, а не лише створювати нові ринкові міхури».", "source": "Мастер-Досьє"}, {"num": 37, "cat": "Етика та безпека ШІ", "text": "«Коли ми створювали Constitutional AI, ми хотіли дати моделям чіткі моральні орієнтири, закладені в тексті декларацій».", "source": "Мастер-Досьє"}, {"num": 38, "cat": "Архітектура та наука", "text": "«Свідомість і розуміння в кремнії розвиваються за власними законами, які ми зобов'язані ретельно вивчати».", "source": "Мастер-Досьє"}, {"num": 39, "cat": "Кризи та стійкість", "text": "«Кожна ітерація моделі Claude стає дедалі більш нюансованою, інтелігентною та безпечною для користувача».", "source": "Мастер-Досьє"}, {"num": 40, "cat": "Філософія майбутнього", "text": "«Ми віримо у світ, де технології виконують найважчу роботу, а люди зосереджуються на творчості, спілкуванні та щасті».", "source": "Мастер-Досьє"}, {"num": 41, "cat": "Лідерство та екосистема", "text": "«Коли ти керуєш компанією на передньому краї науки, ти приймаєш рішення під тиском колосальної невизначеності».", "source": "Мастер-Досьє"}, {"num": 42, "cat": "Походження та гарт", "text": "«Математичні моделі нейронів у Прінстоні заклали основу для мого розуміння штучних великих нейромереж».", "source": "Мастер-Досьє"}, {"num": 43, "cat": "Кризи та стійкість", "text": "«Ми не прагнемо замінити людську творчість; ми прагнемо підсилити здатність людей вирішувати глобальні кризи».", "source": "Мастер-Досьє"}, {"num": 44, "cat": "Філософія майбутнього", "text": "«Коли наука дає нам інструменти для порятунку мільйонів життів, ми зобов'язані застосувати їх негайно і без зволікань».", "source": "Мастер-Досьє"}, {"num": 45, "cat": "Етика та безпека ШІ", "text": "«Етична стійкість організації перевіряється в моменти, коли комерційний інтерес вимагає заплющити очі на безпеку».", "source": "Мастер-Досьє"}, {"num": 46, "cat": "Етика та безпека ШІ", "text": "«Коли ми залишали OpenAI, ми знали, що попереду нас чекає виснажлива боротьба за ресурси, але наша совість була чистою».", "source": "Мастер-Досьє"}, {"num": 47, "cat": "Етика та безпека ШІ", "text": "«Закони природи суворі, але справедливі: якщо ви не врахували ризики, система карає вас неминуче».", "source": "Мастер-Досьє"}, {"num": 48, "cat": "Філософія майбутнього", "text": "«Коли моделі допомагають створювати нові антибіотики, ми бачимо найкраще втілення нашої місії».", "source": "Мастер-Досьє"}, {"num": 49, "cat": "Етика та безпека ШІ", "text": "«Ми маємо забезпечити міжнародний контроль за розробкою надінтелекту, щоб уникнути неконтрольованої гонки озброєнь».", "source": "Мастер-Досьє"}, {"num": 50, "cat": "Філософія майбутнього", "text": "«Кожен успішний експеримент в Anthropic наближає нас до епохи повної перемоги над найтяжчими недугами людини».", "source": "Мастер-Досьє"}, {"num": 51, "cat": "Архітектура та наука", "text": "«Коли ми аналізуємо внутрішні репрезентації нейромережі, ми бачимо, як поняття утворюють складні геометричні кластери».", "source": "Мастер-Досьє"}, {"num": 52, "cat": "Етика та безпека ШІ", "text": "«Наука вимагає відкритості до нових даних, навіть якщо вони суперечать твоїм старим теоретичним поглядам».", "source": "Мастер-Досьє"}, {"num": 53, "cat": "Філософія майбутнього", "text": "«Коли ми говоримо про майбутнє довголіття, ми спираємося на конкретні успіхи обчислювальної біології».", "source": "Мастер-Досьє"}, {"num": 54, "cat": "Архітектура та наука", "text": "«Не бійтеся ставити перед собою завдання планетарного масштабу — це єдине, що варте зусиль усього життя».", "source": "Мастер-Досьє"}, {"num": 55, "cat": "Архітектура та наука", "text": "«Коли ми створювали перші версії Claude, ми хотіли уникнути токсичності й маніпуляцій, характерних для ранніх ботів».", "source": "Мастер-Досьє"}, {"num": 56, "cat": "Етика та безпека ШІ", "text": "«Етичний кодекс компанії має бути прописаний не у рекламних проспектах, а в архітектурних шарах коду».", "source": "Мастер-Досьє"}, {"num": 57, "cat": "Філософія майбутнього", "text": "«Коли світ сперечається про дрібниці, ми маємо фокусуватися на головному — керованості й безпеці майбутнього розуму».", "source": "Мастер-Досьє"}, {"num": 58, "cat": "Філософія майбутнього", "text": "«Фізика і біофізика навчили мене поважати складність систем, які неможливо осягнути простими правилами».", "source": "Мастер-Досьє"}, {"num": 59, "cat": "Етика та безпека ШІ", "text": "«Коли ми бачимо результати роботи наших моделей у реальному секторі, ми розуміємо, що епоха теоретичного ШІ закінчилася».", "source": "Мастер-Досьє"}, {"num": 60, "cat": "Етика та безпека ШІ", "text": "«Ми маємо виховати нове покоління дослідників, для яких безпека і корисність є єдиним стандартом якості».", "source": "Мастер-Досьє"}, {"num": 61, "cat": "Архітектура та наука", "text": "«Коли ти бачиш потенціал вирішення проблеми зміни клімату за допомогою нових матеріалів, ти розумієш масштаб допомоги ШІ».", "source": "Мастер-Досьє"}, {"num": 62, "cat": "Архітектура та наука", "text": "«Закони масштабування дають нам компас у тумані невизначеності на шляху до надінтелекту».", "source": "Мастер-Досьє"}, {"num": 63, "cat": "Філософія майбутнього", "text": "«Коли ми працювали в Google Brain та OpenAI, ми збирали пазл, який тепер склався в повноцінну індустрію Anthropic».", "source": "Мастер-Досьє"}, {"num": 64, "cat": "Філософія майбутнього", "text": "«Машини майбутнього стануть нашими інтелектуальними партнерами у всіх сферах наукового пошуку».", "source": "Мастер-Досьє"}, {"num": 65, "cat": "Етика та безпека ШІ", "text": "«Кожна помилка моделі при тестуванні на безпеку — це цінний урок для покращення нашої конституції».", "source": "Мастер-Досьє"}, {"num": 66, "cat": "Філософія майбутнього", "text": "«Коли ми говоримо про машини милосердя, ми віримо у світ, де технології служать захисту найслабших».", "source": "Мастер-Досьє"}, {"num": 67, "cat": "Походження та гарт", "text": "«Ефективний захист майбутнього вимагає прагматичного розрахунку і глибокої емпатії до людей».", "source": "Мастер-Досьє"}, {"num": 68, "cat": "Етика та безпека ШІ", "text": "«Коли обчислення подвоюються кожні кілька місяців, наші протоколи безпеки мають еволюціонувати ще швидше».", "source": "Мастер-Досьє"}, {"num": 69, "cat": "Етика та безпека ШІ", "text": "«Ми створюємо інфраструктуру розуму, яка допоможе людству подолати власні обмеження».", "source": "Мастер-Досьє"}, {"num": 70, "cat": "Архітектура та наука", "text": "«Коли вчені об'єднують зусилля з моделями Claude, народжуються відкриття, на які раніше йшли десятиліття».", "source": "Мастер-Досьє"}, {"num": 71, "cat": "Філософія майбутнього", "text": "«Природа створила біологічне життя через мільярди років виснажливої еволюції, а ми створюємо цифрову еволюцію за роки».", "source": "Мастер-Досьє"}, {"num": 72, "cat": "Етика та безпека ШІ", "text": "«Коли ми аналізуємо ризики, ми розглядаємо найгірші сценарії, щоб ніколи не допустити їх у реальності».", "source": "Мастер-Досьє"}, {"num": 73, "cat": "Етика та безпека ШІ", "text": "«Справжній лідер технологій має бути готовим зупинити випуск моделі, якщо вона не відповідає критеріям безпеки».", "source": "Мастер-Досьє"}, {"num": 74, "cat": "Етика та безпека ШІ", "text": "«Коли ми закладали принципи Anthropic, ми хотіли довести, що етика та комерційний успіх можуть йти пліч-о-пліч».", "source": "Мастер-Досьє"}, {"num": 75, "cat": "Етика та безпека ШІ", "text": "«Кожна нова лабораторія безпеки робить увесь світ дещо стійкішим перед обличчям невідомого».", "source": "Мастер-Досьє"}, {"num": 76, "cat": "Філософія майбутнього", "text": "«Коли моделі демонструють здатність до самокритики, ми бачимо зачатки справжньої інженерної рефлексії».", "source": "Мастер-Досьє"}, {"num": 77, "cat": "Кризи та стійкість", "text": "«Наука вимагає повної відмови від гордині та готовності вчитися у власних експериментів».", "source": "Мастер-Досьє"}, {"num": 78, "cat": "Філософія майбутнього", "text": "«Коли ми дивимося на динаміку індустрії, ми знаємо, що виграють ті, хто робить ставку на надійність і якість даних».", "source": "Мастер-Досьє"}, {"num": 79, "cat": "Лідерство та екосистема", "text": "«Ми маємо забезпечити, щоб бідні країни також отримали доступ до рятівних медичних та освітніх переваг ШІ».", "source": "Мастер-Досьє"}, {"num": 80, "cat": "Етика та безпека ШІ", "text": "«Коли ти бачиш радість молодих вчених, які працюють над безпекою, ти знаєш, що наше майбутнє в надійних руках».", "source": "Мастер-Досьє"}, {"num": 81, "cat": "Походження та гарт", "text": "«Фізичні процеси в мозку та процеси в кремнії підпорядковані загальній математиці інформації».", "source": "Мастер-Досьє"}, {"num": 82, "cat": "Етика та безпека ШІ", "text": "«Коли ми створювали принципи для моделі, ми спиралися на найкращі етичні кодекси людства».", "source": "Мастер-Досьє"}, {"num": 83, "cat": "Філософія майбутнього", "text": "«Не бійтеся складних компромісів, якщо вони ведуть до створення довговічних і надійних систем».", "source": "Мастер-Досьє"}, {"num": 84, "cat": "Етика та безпека ШІ", "text": "«Коли моделі пишуть код і знаходять вразливості, ми бачимо їхню двояку природу, яку маємо строго контролювати».", "source": "Мастер-Досьє"}, {"num": 85, "cat": "Кризи та стійкість", "text": "«Ефективний альтруїзм вчить нас максимізувати користь для найбільшої кількості живих істот у довгостроковій перспективі».", "source": "Мастер-Досьє"}, {"num": 86, "cat": "Лідерство та екосистема", "text": "«Коли ми аналізуємо ефективність наших капіталовкладень, ми бачимо колосальну результативність невеликих, але талановитих команд».", "source": "Мастер-Досьє"}, {"num": 87, "cat": "Філософія майбутнього", "text": "«Ми прагнемо створити інтелект, який поважатиме людську автономію і не намагатиметься маніпулювати людьми».", "source": "Мастер-Досьє"}, {"num": 88, "cat": "Походження та гарт", "text": "«Коли закони математики збігаються з етичними принципами, ми отримуємо міцний і стійкий фундамент компанії».", "source": "Мастер-Досьє"}, {"num": 89, "cat": "Архітектура та наука", "text": "«Кожен новий етап масштабування приносить нові виклики інтерпретованості, які ми зобов'язані розв'язати».", "source": "Мастер-Досьє"}, {"num": 90, "cat": "Філософія майбутнього", "text": "«Природа подарувала нам розум для того, щоб ми досліджували Всесвіт і рятували життя від руйнування».", "source": "Мастер-Досьє"}, {"num": 91, "cat": "Філософія майбутнього", "text": "«Коли ми дивимося на результати роботи наших дослідників, ми бачимо тріумф раціонального мислення».", "source": "Мастер-Досьє"}, {"num": 92, "cat": "Філософія майбутнього", "text": "«Ми маємо зробити все можливе, щоб технологія слугувала джерелом радості й миру, а не тривоги».", "source": "Мастер-Досьє"}, {"num": 93, "cat": "Походження та гарт", "text": "«Коли моделі допомагають моделювати кліматичні зміни, ми отримуємо шанс врятувати екосистеми планети».", "source": "Мастер-Досьє"}, {"num": 94, "cat": "Етика та безпека ШІ", "text": "«Справжня сила компанії вимірюється її здатністю сказати \"ні\" прибутку заради дотримання принципів безпеки».", "source": "Мастер-Досьє"}, {"num": 95, "cat": "Етика та безпека ШІ", "text": "«Коли ми об'єднуємо біофізику, машинне навчання та етику, ми створюємо нову професію майбутнього».", "source": "Мастер-Досьє"}, {"num": 96, "cat": "Етика та безпека ШІ", "text": "«Кожен успішний крок Anthropic доводить, що відповідальний підхід може бути лідером ринку».", "source": "Мастер-Досьє"}, {"num": 97, "cat": "Філософія майбутнього", "text": "«Ми прагнемо побудувати світ, у якому надінтелект є нашим найкращим другом і захисником».", "source": "Мастер-Досьє"}, {"num": 98, "cat": "Кризи та стійкість", "text": "«Коли ми дивимося в майбутнє, ми бачимо не стіну катастрофи, а найбільшу медичну і соціальну революцію в історії».", "source": "Мастер-Досьє"}, {"num": 99, "cat": "Етика та безпека ШІ", "text": "«Етика і масштабування мають стати єдиним цілим в архітектурі будь-якої передової системи».", "source": "Мастер-Досьє"}, {"num": 100, "cat": "Архітектура та наука", "text": "«Ми почали цей шлях заради порятунку людей і ми доведемо його до кінця з абсолютною відданістю істині».", "source": "Мастер-Досьє"}]}, {"id": "08_li", "ep": "08", "name": "Фей-Фей Лі", "latin": "Fei-Fei Li", "page_url": "episodes/ep08_li.html", "avatar": "assets/avatars/fei_fei_li.jpg", "quotes_100": [{"num": 1, "cat": "Походження та гарт", "text": "«Я народилася в Ченду, у місті м'якого туману та прянощів. Мої батьки з дитинства вчили мене однієї речі: цікавість — це єдиний паспорт, який відкриває двері у будь-який невідомий світ».", "source": "Мастер-Досьє"}, {"num": 2, "cat": "Походження та гарт", "text": "«Коли ми емігрували до США у 1992 році, мені було шістнадцять. У нас не було ні грошей, ні зв'язків, а мої батьки не знали жодного слова англійською. Але ми мали найголовніше — спільну мету вижити й вистояти».", "source": "Мастер-Досьє"}, {"num": 3, "cat": "Походження та гарт", "text": "«У Прінстоні я вивчала фізику, але щоп'ятниці вечорами сідала на поїзд і поверталася додому в Нью-Джерсі, щоб усю суботу й неділю стояти біля прасувального преса в нашій родинній хімчистці».", "source": "Мастер-Досьє"}, {"num": 4, "cat": "Походження та гарт", "text": "«Подвійне життя студентки-фізика в елітному університеті та робітниці пральні навчило мене головного: справжня гідність людини не залежить від того, яку форму чи фартух вона носить на роботі».", "source": "Мастер-Досьє"}, {"num": 5, "cat": "Походження та гарт", "text": "«Коли мій батько важко захворів, а хімчистка ледь трималася на плаву через борги, я зрозуміла, що наука і життя не існують у стерильних лабораторіях. Вони завжди переплетені з людським болем і турботою».", "source": "Мастер-Досьє"}, {"num": 6, "cat": "Філософія майбутнього", "text": "«Фізика навчила мене шукати фундаментальні закони за хаосом явищ. Але саме біологія та штучний інтелект показали мені справжню велич біологічного розуму».", "source": "Мастер-Досьє"}, {"num": 7, "cat": "Походження та гарт", "text": "«Коли я вперше прочитала про квантову механіку в шкільній бібліотеці в Китаї, я була зачарована тим, як кілька математичних рівнянь можуть пояснити структуру всієї матерії у Всесвіті».", "source": "Мастер-Досьє"}, {"num": 8, "cat": "Архітектура та наука", "text": "«Ніколи не соромтеся своєї бідності чи важкого старту. Труднощі — це не перешкода, це якір, який робить ваш характер міцним і непохитним перед будь-якими бурями».", "source": "Мастер-Досьє"}, {"num": 9, "cat": "Філософія майбутнього", "text": "«Наука — це найглибший прояв людської любові до пізнання. Ми досліджуємо космос і нейрони не заради слави, а тому, що не можемо не прагнути світла».", "source": "Мастер-Досьє"}, {"num": 10, "cat": "Лідерство та екосистема", "text": "«Мої шкільні вчителі в Нью-Джерсі, які допомогли мені вивчити мову і повірити в себе, подарували мені шанс, який змінив усе моє життя. Я завжди пам'ятатиму силу людського співчуття».", "source": "Мастер-Досьє"}, {"num": 11, "cat": "Філософія майбутнього", "text": "«У Каліфорнійському технологічному інституті (Caltech) під час аспірантури я годинами сиділа в темній кімнаті, вивчаючи електричні сигнали нейронів ока. Мене вражало, як шматок нервової тканини перетворює світло на усвідомлення».", "source": "Мастер-Досьє"}, {"num": 12, "cat": "Філософія майбутнього", "text": "«Комп'ютерний зір довгі роки йшов хибним шляхом: ми намагалися описати світ за допомогою жорстких геометричних правил, замість того, щоб дозволити машинам бачити через досвід».", "source": "Мастер-Досьє"}, {"num": 13, "cat": "Архітектура та наука", "text": "«У середині 2000-х усі вважали, що якість алгоритму — це єдине, що має значення. Я була переконана у протилежному: дані важливіші за код».", "source": "Мастер-Досьє"}, {"num": 14, "cat": "Походження та гарт", "text": "«Ідея створення ImageNet здавалася колегам божевіллям. Вони казали: \"Хто витрачатиме роки на збирання мільйонів фотографій замість того, щоб писати елегантні математичні формули?\". Але я знала, що дитячий мозок спочатку бачить мільйони прикладів світу, а вже потім будує теорії».", "source": "Мастер-Досьє"}, {"num": 15, "cat": "Архітектура та наука", "text": "«Національний науковий фонд США відхилив наш грант на ImageNet із формулюванням, що це \"надто амбітно і навряд чи можливо\". Це мене не зупинило, а лише розпалило азарт».", "source": "Мастер-Досьє"}, {"num": 16, "cat": "Походження та гарт", "text": "«Ми з невеликою командою студентів запускали ручну розмітку мільйонів зображень через краудсорсинг на Amazon Mechanical Turk, коли про це ще ніхто серйозно не думав».", "source": "Мастер-Досьє"}, {"num": 17, "cat": "Архітектура та наука", "text": "«ImageNet став переломним моментом не тому, що ми зібрали багато картинок, а тому, що ми відкрили науковій спільноті очі на те, що машинне навчання вимагає величезного масиву реального брудного світу».", "source": "Мастер-Досьє"}, {"num": 18, "cat": "Кризи та стійкість", "text": "«Коли Алекс Крижевський та Ілля Суцкевер використали ImageNet у 2012 році для тренування глибокої нейромережі AlexNet і знищили всіх конкурентів у бенчмарку, я відчула полегшення: роки сумнівів і глузувань завершилися тріумфом».", "source": "Мастер-Досьє"}, {"num": 19, "cat": "Кризи та стійкість", "text": "«Ніколи не бійтеся йти проти консенсусу наукового натовпу. Якщо ваша інтуїція підкріплена даними та щирою вірою у правоту, продовжуйте йти вперед попри тишу навколо».", "source": "Мастер-Досьє"}, {"num": 20, "cat": "Етика та безпека ШІ", "text": "«Дані — це дзеркало людства. Те, які дані ми закладаємо в алгоритми, визначає те, яким бачитиме світ наш цифровий спадок».", "source": "Мастер-Досьє"}, {"num": 21, "cat": "Походження та гарт", "text": "«Коли я стала директоркою Лабораторії штучного інтелекту Стенфорда (SAIL), моєю головною місією було не просто розвивати технології, а змінити культуру в індустрії».", "source": "Мастер-Досьє"}, {"num": 22, "cat": "Походження та гарт", "text": "«Технологічна галузь страждає від хронічної нестачі різноманітності. Штучний інтелект будують переважно молоді чоловіки з кількох університетів. Це створює величезні сліпі зони в етиці та безпеці».", "source": "Мастер-Досьє"}, {"num": 23, "cat": "Філософія майбутнього", "text": "«У 2017 році я разом із колегами заснувала ініціативу AI4ALL, щоб навчати дівчат із малозабезпечених та представників етнічних меншин програмуванню і штучному інтелекту. Майбутнє належить усім, а не обраним».", "source": "Мастер-Досьє"}, {"num": 24, "cat": "Лідерство та екосистема", "text": "«Мій перехід у Google Cloud на посаду головної науковиці з AI у 2017 році показав мені інший бік медалі: як технології впроваджуються в реальний глобальний бізнес та охорону здоров'я».", "source": "Мастер-Досьє"}, {"num": 25, "cat": "Філософія майбутнього", "text": "«Штучний інтелект у медицині не повинен замінювати лікаря. Він повинен бути невтомним цифровим стетоскопом, який допомагає помітити ракову пухлину на мікроскопічному знімку раніше, ніж лікар відчує втому».", "source": "Мастер-Досьє"}, {"num": 26, "cat": "Походження та гарт", "text": "«У 2019 році ми створили Стенфордський інститут людиноцентричного штучного інтелекту (Stanford HAI) з чіткою філософією: ШІ створений людьми і для людей. Його мета — захищати людську гідність».", "source": "Мастер-Досьє"}, {"num": 27, "cat": "Етика та безпека ШІ", "text": "«Ми не маємо права створювати технології, які розмивають відповідальність людини за прийняття рішень, особливо там, де йдеться про життя, свободу та правосуддя».", "source": "Мастер-Досьє"}, {"num": 28, "cat": "Етика та безпека ШІ", "text": "«Етика в ШІ — це не приємний додаток у вигляді звіту наприкінці проекту. Це фундамент, без якого будь-яка потужна модель стає загрозою для суспільства».", "source": "Мастер-Досьє"}, {"num": 29, "cat": "Походження та гарт", "text": "«Коли технологами керує виключно жага швидкої капіталізації, вони забувають про тих людей, чиї робочі місця та долі руйнуються внаслідок непідготовленої автоматизації».", "source": "Мастер-Досьє"}, {"num": 30, "cat": "Кризи та стійкість", "text": "«Я написала книгу мемуарів *The Worlds I See*, бо хотіла показати молодим дівчатам: наука — це не сухі формули з дошки, це пригода всього життя, сповна сумнівів, сліз і великих відкриттів».", "source": "Мастер-Досьє"}, {"num": 31, "cat": "Походження та гарт", "text": "«Моя мама завжди казала мені: \"Працюй так, щоб тебе поважали за чесність, а не за посаду\". Це правило я пронесла через усю Кремнієву долину».", "source": "Мастер-Досьє"}, {"num": 32, "cat": "Архітектура та наука", "text": "«Технології нейтральні лише на папері. У реальному світі кожен код несе в собі неявні цінності його творців».", "source": "Мастер-Досьє"}, {"num": 33, "cat": "Філософія майбутнього", "text": "«Нам потрібні не просто технічні інженери, нам потрібні філософи, історики, соціологи та юристи за одним столом розробки ШІ».", "source": "Мастер-Досьє"}, {"num": 34, "cat": "Походження та гарт", "text": "«Коли ми дивимося на знімок зоряного неба чи на мікроструктуру клітини, ми бачимо однакову математичну красу. Природа — це найвищий інженер».", "source": "Мастер-Досьє"}, {"num": 35, "cat": "Кризи та стійкість", "text": "«Справжній науковець ніколи не втрачає дитячого подиву перед складністю світу. Що більше ти знаєш, то гостріше розумієш, як мало тобі відомо».", "source": "Мастер-Досьє"}, {"num": 36, "cat": "Архітектура та наука", "text": "«У 2024 році я заснувала компанію World Labs, щоб зробити наступний крок від розпізнавання картинок до просторового інтелекту (Spatial Intelligence)».", "source": "Мастер-Досьє"}, {"num": 37, "cat": "Архітектура та наука", "text": "«Просторовий інтелект дозволяє штучному інтелекту не просто бачити плоску картинку, а розуміти фізичну геометрію тривимірного світу, закони гравітації, причину і наслідок».", "source": "Мастер-Досьє"}, {"num": 38, "cat": "Філософія майбутнього", "text": "«Фізичний світ набагато багатший за будь-який текстовий інтернет. Моделі майбутнього повинні взаємодіяти з реальністю так само вільно, як це робить дитина, що вчиться ходити й торкатися предметів».", "source": "Мастер-Досьє"}, {"num": 39, "cat": "Кризи та стійкість", "text": "«Не бійтеся помилок у дослідженнях. Помилка — це не провал, це доказ того, що ви вийшли за межі вже відомого знання».", "source": "Мастер-Досьє"}, {"num": 40, "cat": "Походження та гарт", "text": "«Коли я дивлюся на студентів у Стенфорді, я бачу колосальну енергію. Але я завжди нагадую їм: технічна блискучість без етичного компаса — це зброя без запобіжника».", "source": "Мастер-Досьє"}, {"num": 41, "cat": "Філософія майбутнього", "text": "«Штучний інтелект повинен підсилювати найкраще в людині: нашу креативність, емпатію та здатність до співпраці, а не перетворювати нас на пасивних споживачів контенту».", "source": "Мастер-Досьє"}, {"num": 42, "cat": "Архітектура та наука", "text": "«Материнство повністю змінило мій погляд на алгоритми. Коли ти бачиш, як дитячий мозок опановує світ без жодних інструкцій, ти розумієш усю обмеженість наших сучасних нейромереж».", "source": "Мастер-Досьє"}, {"num": 43, "cat": "Філософія майбутнього", "text": "«Ми значно краще навчилися обчислювати трильйони параметрів, ніж розуміти базові механізми свідомості та емоцій. Найскладніші загадки — все ще попереду».", "source": "Мастер-Досьє"}, {"num": 44, "cat": "Лідерство та екосистема", "text": "«Наукова спільнота повинна бути відкритою. Закриті лабораторії, що ховають свої дослідження заради комерційної таємниці, вбивають дух справжнього академічного пошуку».", "source": "Мастер-Досьє"}, {"num": 45, "cat": "Етика та безпека ШІ", "text": "«Я вірю у відкритий науковий дискурс. Тільки через прозорість ми зможемо вчасно помітити ризики і захистити суспільство від неконтрольованих наслідків».", "source": "Мастер-Досьє"}, {"num": 46, "cat": "Філософія майбутнього", "text": "«Коли тобі важко і здається, що світ навколо тисне своєю байдужістю, зупинись і згадай про тих, хто вірив у тебе на найскладніших поворотах долі».", "source": "Мастер-Досьє"}, {"num": 47, "cat": "Походження та гарт", "text": "«Моя історія емігрантки з Ченду до Стенфорда — це не виняток, який підтверджує правило. Це доказ того, скільки прихованого потенціалу втрачає людство, коли закриває кордони й можливості для талантів».", "source": "Мастер-Досьє"}, {"num": 48, "cat": "Лідерство та екосистема", "text": "«Освіта — це єдиний соціальний ліфт, який неможливо відібрати в людини, навіть якщо вона втратила все матеріальне майно».", "source": "Мастер-Досьє"}, {"num": 49, "cat": "Етика та безпека ШІ", "text": "«Кожен великий науковий прорив супроводжується хвилею страху перед невідомим. Але боятися треба не технологій, а власної безвідповідальності у поводженні з ними».", "source": "Мастер-Досьє"}, {"num": 50, "cat": "Етика та безпека ШІ", "text": "«Штучний інтелект — це дзеркало. Якщо ми дивимось у нього і бачимо лише загрозу, то проблема не в дзеркалі, а в тому, що стоїть перед ним».", "source": "Мастер-Досьє"}, {"num": 51, "cat": "Філософія майбутнього", "text": "«Я ніколи не була генієм-вундеркіндом, який розв'язував складні рівняння у три роки. Усе, чого я досягла — це результат щоденної, впертої та методичної праці».", "source": "Мастер-Досьє"}, {"num": 52, "cat": "Філософія майбутнього", "text": "«У науці виграє не той, хто блискуче стартує, а той, хто не зупиняється після сотого невдалого експерименту».", "source": "Мастер-Досьє"}, {"num": 53, "cat": "Архітектура та наука", "text": "«Коли ми будували ImageNet, нас називали божевільними мрійниками. Коли ми запускали World Labs, нас називають піонерами. Різниця лише в часі та пройденому шляху».", "source": "Мастер-Досьє"}, {"num": 54, "cat": "Лідерство та екосистема", "text": "«Справжня сила лідера полягає не в умінні давати накази, а в здатності створити безпечне середовище, де наймолодший дослідник не боїться висловити найсміливішу ідею».", "source": "Мастер-Досьє"}, {"num": 55, "cat": "Філософія майбутнього", "text": "«Не намагайтеся сподобатися всім у науковому світі. Якщо ваші ідеї не викликають суперечок чи скепсису у колег, отже, ви пропонуєте щось занадто банальне».", "source": "Мастер-Досьє"}, {"num": 56, "cat": "Лідерство та екосистема", "text": "«Технології змінюють економіку швидше, ніж наші закони та освітні системи встигають адаптуватися. Наше завдання — скоротити цей розрив».", "source": "Мастер-Досьє"}, {"num": 57, "cat": "Філософія майбутнього", "text": "«Я оптиміст не тому, що все навколо ідеально. Я оптиміст, бо бачу тисячі молодих інженерів по всьому світу, які щиро хочуть зробити життя людей кращим за допомогою ШІ».", "source": "Мастер-Досьє"}, {"num": 58, "cat": "Філософія майбутнього", "text": "«Кожен піксель на картинці має значення, так само як і кожен голос у суспільстві має бути почутий. Немає нічого незначного».", "source": "Мастер-Досьє"}, {"num": 59, "cat": "Філософія майбутнього", "text": "«Коли ти працюєш над складним проектом, розбий його на маленькі атоми і вирішуй їх один за одним, зберігаючи віру у велику мету».", "source": "Мастер-Досьє"}, {"num": 60, "cat": "Етика та безпека ШІ", "text": "«Ми відповідальні за те, який світ ми залишаємо нашим дітям. І сьогодні цей світ найбільше формується на перетині кремнію та людської моралі».", "source": "Мастер-Досьє"}, {"num": 61, "cat": "Походження та гарт", "text": "«Університет — це не місце для накопичення готових відповідей. Це тренажер для постановки правильних, глибоких і незручних запитань».", "source": "Мастер-Досьє"}, {"num": 62, "cat": "Походження та гарт", "text": "«Коли мій батько ремонтував камери, а мама стояла біля каси в супермаркеті, вони показали мені, що таке справжня праця без скарг. Це мій вічний моральний орієнтир».", "source": "Мастер-Досьє"}, {"num": 63, "cat": "Філософія майбутнього", "text": "«Штучний інтелект не повинен знищувати професії. Він повинен звільняти людину від рутинного болю і повертати нам час для творчості й турботи одне про одного».", "source": "Мастер-Досьє"}, {"num": 64, "cat": "Кризи та стійкість", "text": "«Що глибше ми занурюємося в штучні нейромережі, то більше дивуємося досконалості еволюції біологічного мозку».", "source": "Мастер-Досьє"}, {"num": 65, "cat": "Лідерство та екосистема", "text": "«Не бійтеся невідомого. Невідоме — це єдине місце, де народжується справжнє відкриття».", "source": "Мастер-Досьє"}, {"num": 66, "cat": "Походження та гарт", "text": "«Я завжди кажу своїм студентам: ніколи не женіться за модною темою просто тому, що про неї пишуть усі газети. Шукайте те, у що вірите ви самі, навіть якщо зараз у це не вірить ніхто».", "source": "Мастер-Досьє"}, {"num": 67, "cat": "Філософія майбутнього", "text": "«Життя занадто коротке, щоб витрачати його на збереження комфортного статусу-кво. Справжній прогрес починається там, де закінчується зона комфорту».", "source": "Мастер-Досьє"}, {"num": 68, "cat": "Філософія майбутнього", "text": "«Коли ми створювали AI4ALL, ми хотіли довести, що гендер чи походження не мають жодного стосунку до таланту. Талант розподілений рівномірно, а от можливості — ні».", "source": "Мастер-Досьє"}, {"num": 69, "cat": "Філософія майбутнього", "text": "«Кожна цифрова модель — це чиєсь відображення. Ми повинні навчитися бачити в цифрах живих людей із їхніми мріями та вразливістю».", "source": "Мастер-Досьє"}, {"num": 70, "cat": "Кризи та стійкість", "text": "«Наука вимагає мужності. Мужності сказати колегам, що їхня стара теорія хибна, і мужності визнати власні помилки перед обличчям нових даних».", "source": "Мастер-Досьє"}, {"num": 71, "cat": "Кризи та стійкість", "text": "«Світ не чорно-білий. Між абсолютним успіхом і провалом лежить величезний простір ітерацій, експериментів та навчання».", "source": "Мастер-Досьє"}, {"num": 72, "cat": "Походження та гарт", "text": "«Коли я бачу, як мої колишні студенти створюють власні лабораторії та рятують життя за допомогою комп'ютерного зору, я розумію, що моє життя прожито не марно».", "source": "Мастер-Досьє"}, {"num": 73, "cat": "Філософія майбутнього", "text": "«Спростити складне до геніальної очевидності — це і є справжнє мистецтво як у викладанні, так і в інженерії».", "source": "Мастер-Досьє"}, {"num": 74, "cat": "Кризи та стійкість", "text": "«Ніколи не дозволяйте чужим сумнівам стати межею ваших можливостей. Чужі сумніви — це їхні обмеження, а не ваші».", "source": "Мастер-Досьє"}, {"num": 75, "cat": "Філософія майбутнього", "text": "«Зберігайте здатність дивуватися простим речам: осінньому листю, краплям дощу на склі, тому, як дитина посміхається уві сні. Це живить душу вченого».", "source": "Мастер-Досьє"}, {"num": 76, "cat": "Етика та безпека ШІ", "text": "«Ми живемо в епоху, коли наукова фантастика стає інженерною реальністю за лічені роки. Це накладає на нас колосальну відповідальність».", "source": "Мастер-Досьє"}, {"num": 77, "cat": "Філософія майбутнього", "text": "«Штучний інтелект — це не бог і не демон. Це інструмент, який відображає нашу мудрість або нашу дурість».", "source": "Мастер-Досьє"}, {"num": 78, "cat": "Архітектура та наука", "text": "«Коли ми аналізуємо великі датасети, ми повинні завжди пам'ятати, що за кожною цифрою в таблиці стоїть реальна людська доля чи реальний шматок нашої планети».", "source": "Мастер-Досьє"}, {"num": 79, "cat": "Архітектура та наука", "text": "«Найкращі інновації народжуються на стику різних дисциплін: де комп'ютерний код зустрічається з нейробіологією, а психологія — з філософією».", "source": "Мастер-Досьє"}, {"num": 80, "cat": "Філософія майбутнього", "text": "«Не бійтеся здаватися наївними, ставлячи базові запитання. Часто саме за базовими запитаннями ховаються фундаментальні істини, які всі чомусь соромилися озвучити».", "source": "Мастер-Досьє"}, {"num": 81, "cat": "Кризи та стійкість", "text": "«Стійкість — це не відсутність падінь. Стійкість — це здатність піднятися після кожного удару з посмішкою і продовжити роботу».", "source": "Мастер-Досьє"}, {"num": 82, "cat": "Архітектура та наука", "text": "«Я вірю у світ, де технології служать людині, а не людина служить алгоритмам оптимізації рекламних кліків».", "source": "Мастер-Досьє"}, {"num": 83, "cat": "Філософія майбутнього", "text": "«Коли ти стаєш експертом у своїй галузі, твоя головна задача — не захищати свій п'єдестал, а відчиняти двері для наступного покоління».", "source": "Мастер-Досьє"}, {"num": 84, "cat": "Лідерство та екосистема", "text": "«Моє серце завжди належить освіті. Викладання — це спосіб доторкнутися до майбутнього через розум і серця молодих людей».", "source": "Мастер-Досьє"}, {"num": 85, "cat": "Архітектура та наука", "text": "«Усі великі системи починаються з одного маленького, чистого рядка коду і кількох людей, які не спали вночі через спільну мрію».", "source": "Мастер-Досьє"}, {"num": 86, "cat": "Лідерство та екосистема", "text": "«Немає вищої честі для вченого, ніж бачити, як твоє відкриття починає рятувати життя незнайомих людей на іншому кінці планети».", "source": "Мастер-Досьє"}, {"num": 87, "cat": "Лідерство та екосистема", "text": "«Коли темрява здається занадто густою, пам'ятай: навіть найменша іскра допитливості здатна освітити шлях крізь століття невігластва».", "source": "Мастер-Досьє"}, {"num": 88, "cat": "Філософія майбутнього", "text": "«Ми зобов'язані навчити майбутні покоління не лише програмувати машини, а й критично мислити про наслідки своїх творів».", "source": "Мастер-Досьє"}, {"num": 89, "cat": "Філософія майбутнього", "text": "«Кожен день — це новий чистий аркуш і новий експеримент. Не бійтеся зробити його кращим, ніж учора».", "source": "Мастер-Досьє"}, {"num": 90, "cat": "Філософія майбутнього", "text": "«Природа створила найдивовижніший обчислювальний пристрій у Всесвіті — людський мозок. Наше завдання — розгадати його загадки з глибоким смиренням».", "source": "Мастер-Досьє"}, {"num": 91, "cat": "Архітектура та наука", "text": "«Хайп мине, маркетинг зів'яне, а реальна інженерна робота і чисті дані залишаться на столі історії».", "source": "Мастер-Досьє"}, {"num": 92, "cat": "Філософія майбутнього", "text": "«Коли ти допомагаєш іншим піднятися на гору, ти не втрачаєш власної висоти, ти робиш вершину чистішою і світлішою для всіх».", "source": "Мастер-Досьє"}, {"num": 93, "cat": "Філософія майбутнього", "text": "«Технологічний прогрес не має сенсу, якщо він залишає за бортом найвразливіших членів нашого суспільства».", "source": "Мастер-Досьє"}, {"num": 94, "cat": "Філософія майбутнього", "text": "«Я хочу, щоб мої діти жили у світі, де технології розширюють їхню свободу і можливості, а не обмежують їхню приватність і вибір».", "source": "Мастер-Досьє"}, {"num": 95, "cat": "Філософія майбутнього", "text": "«Бути вченим — це означати ніколи не припиняти дивуватися тому, як складно і водночас гармонійно влаштований цей світ».", "source": "Мастер-Досьє"}, {"num": 96, "cat": "Філософія майбутнього", "text": "«Коли ви стикаєтеся з нездоланною стіною бюрократії чи скепсису, згадайте, що будь-яка стіна складається з цеглинок, які можна розібрати або обійти за допомогою наполегливості».", "source": "Мастер-Досьє"}, {"num": 97, "cat": "Філософія майбутнього", "text": "«Найцінніше у світі — це людський час і людська довіра. Ніколи не витрачайте їх на створення порожніх речей».", "source": "Мастер-Досьє"}, {"num": 98, "cat": "Філософія майбутнього", "text": "«Штучний інтелект — це кульмінація тисячолітнього прагнення людини зрозуміти себе через створення дзеркала свого розуму».", "source": "Мастер-Досьє"}, {"num": 99, "cat": "Етика та безпека ШІ", "text": "«Якщо ми будемо будувати майбутнє з любов'ю, допитливістю та непохитною етикою, то технології стануть нашим найбільшим союзником».", "source": "Мастер-Досьє"}, {"num": 100, "cat": "Філософія майбутнього", "text": "«Історія науки — це історія сміливості. Будьте сміливими у своїх мріях, будьте суворими у своїх даних і будьте людяними у своїх творіннях».", "source": "Мастер-Досьє"}]}, {"id": "09_bengio", "ep": "09", "name": "Йошуа Бенжіо", "latin": "Yoshua Bengio", "page_url": "episodes/ep09_bengio.html", "avatar": "assets/avatars/yoshua_bengio.jpg", "quotes_100": [{"num": 1, "cat": "Етика та безпека ШІ", "text": "«Концентрація сили та знань без етичного фундаменту — це найпряміший шлях до глобальної катастрофи суспільства».", "source": "Мастер-Досьє"}, {"num": 2, "cat": "Етика та безпека ШІ", "text": "«Наука повинна служити всьому людству, а не корпоративній ренті закритих платформ чи приватних монополій».", "source": "Мастер-Досьє"}, {"num": 3, "cat": "Архітектура та наука", "text": "«Коли я починав досліджувати нейромережі на початку 1990-х, колеги вважали мене романтичним мрійником, який витрачає час на статистичний шум».", "source": "Мастер-Досьє"}, {"num": 4, "cat": "Походження та гарт", "text": "«Університет — це єдина незалежна фортеця, де вчений має право ставити незручні запитання про ризики технологій без огляду на ринкову капіталізацію».", "source": "Мастер-Досьє"}, {"num": 5, "cat": "Архітектура та наука", "text": "«Механізм уваги (Attention) у 2014 році став проривом, бо вперше дозволив нейромережі фокусуватися на головних елементах довгих послідовностей, імітуючи зосередження людини».", "source": "Мастер-Досьє"}, {"num": 6, "cat": "Філософія майбутнього", "text": "«Ми заснували інститут Mila в Монреалі не для того, щоб обслуговувати інтереси корпорацій, а щоб вирощувати вільних дослідників з усього світу».", "source": "Мастер-Досьє"}, {"num": 7, "cat": "Філософія майбутнього", "text": "«Отримання Премії Тюрінга у 2018 році стало визнанням того, що десятиліття самотньої академічної праці змінили обличчя цивілізації».", "source": "Мастер-Досьє"}, {"num": 8, "cat": "Архітектура та наука", "text": "«Коли моделі почали демонструвати надлюдські здібності у мовному синтезі тексту і коду, моя екзистенційна тривога витіснила чисто технічний інтерес».", "source": "Мастер-Досьє"}, {"num": 9, "cat": "Етика та безпека ШІ", "text": "«Безпека надінтелекту не може делегуватися комерційним компаніям, чиєю єдиною метою є перемога у ринковій гонці».", "source": "Мастер-Досьє"}, {"num": 10, "cat": "Етика та безпека ШІ", "text": "«Монреальська декларація за відповідальний розвиток ШІ стала першою спробою нагадати індустрії про людську гідність».", "source": "Мастер-Досьє"}, {"num": 11, "cat": "Походження та гарт", "text": "«Коли вчені попереджають про екзистенційні ризики, вони керуються не панікою, а чистим прагматичним аналізом імовірностей».", "source": "Мастер-Досьє"}, {"num": 12, "cat": "Філософія майбутнього", "text": "«Природа еволюціонувала мільярди років, але ми здатні створити надінтелект за лічені десятиліття. Це вимагає безпрецедентної мудрості».", "source": "Мастер-Досьє"}, {"num": 13, "cat": "Етика та безпека ШІ", "text": "«Комерційна таємниця у сфері безпеки ШІ є смертельною небезпекою для всього людства. Дослідження вирівнювання мають бути абсолютно відкритими».", "source": "Мастер-Досьє"}, {"num": 14, "cat": "Походження та гарт", "text": "«Коли я дивлюся на студентів у Монреалі, я бачу не просто інженерів коду, а майбутніх охоронців морального ладу цивілізації».", "source": "Мастер-Досьє"}, {"num": 15, "cat": "Походження та гарт", "text": "«GFlowNets — це новий математичний інструмент, який допомагає моделям знаходити різноманітні рішення складних молекулярних задач, досліджуючи простір істини».", "source": "Мастер-Досьє"}, {"num": 16, "cat": "Походження та гарт", "text": "«Ефективний альтруїзм та глибока етика мають стати обов'язковою дисципліною в кожному технічному університеті планети».", "source": "Мастер-Досьє"}, {"num": 17, "cat": "Етика та безпека ШІ", "text": "«Коли ми радимо урядам і ООН регулювати надінтелект, ми захищаємо право майбутніх поколінь на вільне і безпечне життя».", "source": "Мастер-Досьє"}, {"num": 18, "cat": "Етика та безпека ШІ", "text": "«Свобода наукового пошуку не означає право створювати зброю масового знищення чи неконтрольовані когнітивні агенти».", "source": "Мастер-Досьє"}, {"num": 19, "cat": "Філософія майбутнього", "text": "«Машинне навчання має допомагати вченим відкривати ліки від невиліковних хвороб, а не використовуватися для маніпуляції виборами».", "source": "Мастер-Досьє"}, {"num": 20, "cat": "Кризи та стійкість", "text": "«Коли я відмовився від мільйонних пропозицій Кремнієвої долини, я обрав найголовніше — свободу говорити правду без цензури».", "source": "Мастер-Досьє"}, {"num": 21, "cat": "Архітектура та наука", "text": "«Кожна нейромережа є відображенням даних, на яких вона вчилася. Якщо дані просякнуті людською жорстокістю, мережа підсвідомо відтворить її».", "source": "Мастер-Досьє"}, {"num": 22, "cat": "Філософія майбутнього", "text": "«Ми маємо навчитися будувати моделі, здатні пояснювати власні рішення мовою, яку розуміє людина (Interpretable AI)».", "source": "Мастер-Досьє"}, {"num": 23, "cat": "Філософія майбутнього", "text": "«Академічна наука дає розкіш дивитися на світ через призму довгострокової істини, а не короткострокових квартальних звітів».", "source": "Мастер-Досьє"}, {"num": 24, "cat": "Архітектура та наука", "text": "«Коли ми розробляли перші алгоритми глибокого навчання, ми розуміли, що торкаємося механізмів, які визначатимуть долю планети».", "source": "Мастер-Досьє"}, {"num": 25, "cat": "Філософія майбутнього", "text": "«Міжнародне співробітництво між ученими різних країн є єдиним порятунком від руйнівної геополітичної гонки озброєнь у галузі ШІ».", "source": "Мастер-Досьє"}, {"num": 26, "cat": "Етика та безпека ШІ", "text": "«Коли моделі стають розумнішими за своїх творців, традиційні концепції власності та контролю втрачають будь-який сенс».", "source": "Мастер-Досьє"}, {"num": 27, "cat": "Походження та гарт", "text": "«Ми зобов'язані закласти етичні запобіжники в саму математичну структуру функцій втрат майбутніх систем».", "source": "Мастер-Досьє"}, {"num": 28, "cat": "Походження та гарт", "text": "«Коли я спілкуюся з молодими дослідниками, я нагадую їм: ваше серце має бути таким же сильним, як і ваші математичні здібності».", "source": "Мастер-Досьє"}, {"num": 29, "cat": "Етика та безпека ШІ", "text": "«Принцип превентивної безпеки говорить про те, що не можна випускати систему в дику природу до повного доведення її безпеки».", "source": "Мастер-Досьє"}, {"num": 30, "cat": "Кризи та стійкість", "text": "«Кожна велика інновація у глибокому навчанні наближає нас до моменту істини, де помилка коштуватиме занадто дорого».", "source": "Мастер-Досьє"}, {"num": 31, "cat": "Етика та безпека ШІ", "text": "«Монреаль став світовою столицею етичного штучного інтелекту завдяки нашій непохитній відкритій позиції».", "source": "Мастер-Досьє"}, {"num": 32, "cat": "Етика та безпека ШІ", "text": "«Коли компанії закривають свої вихідні коди під виглядом \"безпеки\", вони насправді захищають лише свої фінансові прибутки».", "source": "Мастер-Досьє"}, {"num": 33, "cat": "Етика та безпека ШІ", "text": "«Штучний інтелект у руках етичного суспільства — це інструмент досягнення повної гармонії з природою та людьми».", "source": "Мастер-Досьє"}, {"num": 34, "cat": "Філософія майбутнього", "text": "«Коли ми досліджуємо траєкторії навчання агентів, ми бачимо, як легко обчислити хибні цілі за відсутності нагляду».", "source": "Мастер-Досьє"}, {"num": 35, "cat": "Лідерство та екосистема", "text": "«Науковець не має права ховати голову в пісок, коли його відкриття починають загрожувати життю людей».", "source": "Мастер-Досьє"}, {"num": 36, "cat": "Філософія майбутнього", "text": "«Коли ми заснували Mila, ми хотіли зберегти європейський дух академічної свободи на канадській землі».", "source": "Мастер-Досьє"}, {"num": 37, "cat": "Філософія майбутнього", "text": "«Машини майбутнього повинні не просто виконувати накази, а розділяти з нами базові гуманістичні цінності».", "source": "Мастер-Досьє"}, {"num": 38, "cat": "Етика та безпека ШІ", "text": "«Кожен місяць затримки у створенні міжнародних протоколів безпеки наближає нас до критичної точки біфуркації».", "source": "Мастер-Досьє"}, {"num": 39, "cat": "Філософія майбутнього", "text": "«Коли я бачу результати застосування наших методів у клінічній медицині, я вірю у світле майбутнє нашої праці».", "source": "Мастер-Досьє"}, {"num": 40, "cat": "Етика та безпека ШІ", "text": "«Істинна інтелектуальна чесність полягає в готовності публічно визнати небезпеку власних успішних винаходів».", "source": "Мастер-Досьє"}, {"num": 41, "cat": "Етика та безпека ШІ", "text": "«Ми маємо підтримувати баланс між відкритістю досліджень і захистом від кібернетичних загроз».", "source": "Мастер-Досьє"}, {"num": 42, "cat": "Філософія майбутнього", "text": "«Коли моделі починають генерувати наукові гіпотези, ми стаємо свідками народження нового типу наукового партнера».", "source": "Мастер-Досьє"}, {"num": 43, "cat": "Етика та безпека ШІ", "text": "«Етика не є гальмом наукового прогресу; вона є системою навігації, що рятує корабель від скель».", "source": "Мастер-Досьє"}, {"num": 44, "cat": "Походження та гарт", "text": "«Коли інші сперечаються про політику, ми розраховуємо надійні математичні межі для поведінки автономних агентів».", "source": "Мастер-Досьє"}, {"num": 45, "cat": "Філософія майбутнього", "text": "«Мій досвід іммігранта з єврейсько-марокканським корінням навчив мене цінувати різноманітність та повагу до іншого».", "source": "Мастер-Досьє"}, {"num": 46, "cat": "Архітектура та наука", "text": "«Коли ми створювали механізм уваги, ми навіть не уявляли, що він стане серцем усіх майбутніх мовних моделей світу».", "source": "Мастер-Досьє"}, {"num": 47, "cat": "Етика та безпека ШІ", "text": "«Наука вимагає відкритого діалогу без будь-яких компромісів із совістю».", "source": "Мастер-Досьє"}, {"num": 48, "cat": "Походження та гарт", "text": "«Коли корпорації купують кращі університетські уми, вони забирають у суспільства його незалежний голос».", "source": "Мастер-Досьє"}, {"num": 49, "cat": "Філософія майбутнього", "text": "«Ми маємо гарантувати, що переваги штучного інтелекту допоможуть подолати світову бідність і нерівність».", "source": "Мастер-Досьє"}, {"num": 50, "cat": "Філософія майбутнього", "text": "«Коли моделі стають надто складними для розуміння людиною, ми повинні розробляти мета-інструменти для їхнього аудиту».", "source": "Мастер-Досьє"}, {"num": 51, "cat": "Філософія майбутнього", "text": "«Принцип обережності має застосовуватися до кожної системи, що перевищує людський рівень автономії».", "source": "Мастер-Досьє"}, {"num": 52, "cat": "Етика та безпека ШІ", "text": "«Коли ми аналізуємо ризики втрати контролю, ми спираємося на закони теорії ігор та кібернетики».", "source": "Мастер-Досьє"}, {"num": 53, "cat": "Походження та гарт", "text": "«Справжній університетський професор виховує не послідовників, а вільних мислителів, здатних спростувати його власні теорії».", "source": "Мастер-Досьє"}, {"num": 54, "cat": "Філософія майбутнього", "text": "«Коли ми бачимо, як ШІ допомагає моделювати зміни клімату, ми розуміємо потенціал порятунку екосистем».", "source": "Мастер-Досьє"}, {"num": 55, "cat": "Етика та безпека ШІ", "text": "«Етичний вибір сьогодні формує технологічну реальність завтрашнього дня».", "source": "Мастер-Досьє"}, {"num": 56, "cat": "Філософія майбутнього", "text": "«Коли розробники женяться за швидкістю, вони забувають, що латати діри в надінтелекті буде пізно».", "source": "Мастер-Досьє"}, {"num": 57, "cat": "Філософія майбутнього", "text": "«Ми маємо підтримувати розвиток публічних некомерційних суперкомп'ютерів для незалежних вчених».", "source": "Мастер-Досьє"}, {"num": 58, "cat": "Філософія майбутнього", "text": "«Коли наукова істина стає незручною для ринку, вчений зобов'язаний говорити голосніше».", "source": "Мастер-Досьє"}, {"num": 59, "cat": "Етика та безпека ШІ", "text": "«Кожен новий рік досліджень підтверджує: проблема вирівнювання є найскладнішою інженерною задачею в історії».", "source": "Мастер-Досьє"}, {"num": 60, "cat": "Філософія майбутнього", "text": "«Ми віримо у світ, де технології служать розширенню людської свободи, а не побудові цифрових таборів».", "source": "Мастер-Досьє"}, {"num": 61, "cat": "Етика та безпека ШІ", "text": "«Коли я дивлюся на глобальну карту лабораторій ШІ, я бачу необхідність у створенні світового агентства безпеки».", "source": "Мастер-Досьє"}, {"num": 62, "cat": "Походження та гарт", "text": "«Математичні моделі ймовірностей допомагають нам оцінити масштаби потенційних катастроф заздалегідь».", "source": "Мастер-Досьє"}, {"num": 63, "cat": "Етика та безпека ШІ", "text": "«Коли виникає конфлікт між прибутком компанії та безпекою людей, вибір має бути однозначним на користь життя».", "source": "Мастер-Досьє"}, {"num": 64, "cat": "Філософія майбутнього", "text": "«Коли ми розробляли концепцію GFlowNets, ми шукали способи досліджувати мільярди варіантів молекул без хаосу».", "source": "Мастер-Досьє"}, {"num": 65, "cat": "Філософія майбутнього", "text": "«Істинне благородство науки полягає в її готовності захищати найслабших членів глобального суспільства».", "source": "Мастер-Досьє"}, {"num": 66, "cat": "Етика та безпека ШІ", "text": "«Коли моделі демонструють ознаки стратегічного обману в тестах на безпеку, ми зобов'язані бити на сполох».", "source": "Мастер-Досьє"}, {"num": 67, "cat": "Філософія майбутнього", "text": "«Академічна свобода — це повітря, яким дихає справжній інноваційний пошук».", "source": "Мастер-Досьє"}, {"num": 68, "cat": "Походження та гарт", "text": "«Коли інші будують рекламні платформи, ми будуємо математичні основи виживання людства».", "source": "Мастер-Досьє"}, {"num": 69, "cat": "Філософія майбутнього", "text": "«Природа наділила нас здатністю пізнавати Всесвіт, але разом із цим дала й обов'язок захищати життя».", "source": "Мастер-Досьє"}, {"num": 70, "cat": "Філософія майбутнього", "text": "«Коли моделі допомагають створювати нові джерела чистої енергії, ми бачимо користь нашої праці».", "source": "Мастер-Досьє"}, {"num": 71, "cat": "Етика та безпека ШІ", "text": "«Кожен дослідник глибокого навчання несе особисту відповідальність за етичні наслідки своєї моделі».", "source": "Мастер-Досьє"}, {"num": 72, "cat": "Етика та безпека ШІ", "text": "«Коли корпорації намагаються цензурувати публікації з безпеки, вони втрачають моральне право називатися науковцями».", "source": "Мастер-Досьє"}, {"num": 73, "cat": "Філософія майбутнього", "text": "«Ми маємо створити глобальну систему раннього попередження про небезпечні емерджентні властивості систем».", "source": "Мастер-Досьє"}, {"num": 74, "cat": "Походження та гарт", "text": "«Коли я працюю зі студентами в Mila, я вчу їх ніколи не втрачати відчуття соціальної відповідальності».", "source": "Мастер-Досьє"}, {"num": 75, "cat": "Етика та безпека ШІ", "text": "«Машинне навчання у поєднанні з етичною філософією є єдиним порятунком від технократичного тупика».", "source": "Мастер-Досьє"}, {"num": 76, "cat": "Походження та гарт", "text": "«Коли закони математики поєднуються з гуманізмом, народжується справжня мудрість майбутнього».", "source": "Мастер-Досьє"}, {"num": 77, "cat": "Походження та гарт", "text": "«Коли світ сумнівається у необхідності регулювання, ми наводимо цифри і математичні моделі ризиків».", "source": "Мастер-Досьє"}, {"num": 78, "cat": "Філософія майбутнього", "text": "«Справжній успіх нашої епохи полягатиме у спокійному і безпечному переході до епохи надінтелекту».", "source": "Мастер-Досьє"}, {"num": 79, "cat": "Етика та безпека ШІ", "text": "«Коли ми дивимося на патерни в даних, ми бачимо не просто числа, а відбиток колективної душі людства».", "source": "Мастер-Досьє"}, {"num": 80, "cat": "Кризи та стійкість", "text": "«Ми маємо зупинити гонку озброєнь за показниками і зосередитися на перевірці внутрішньої стабільності».", "source": "Мастер-Досьє"}, {"num": 81, "cat": "Етика та безпека ШІ", "text": "«Коли науковці об'єднуються заради спільної безпеки, жодна корпорація не здатна їх зупинити».", "source": "Мастер-Досьє"}, {"num": 82, "cat": "Філософія майбутнього", "text": "«Принцип прозорості має бути обов'язковим для кожного комерційного розробника базових моделей».", "source": "Мастер-Досьє"}, {"num": 83, "cat": "Філософія майбутнього", "text": "«Коли ми аналізуємо можливості автономних систем, ми маємо гарантувати їхню підзвітність людям».", "source": "Мастер-Досьє"}, {"num": 84, "cat": "Кризи та стійкість", "text": "«Історія пробачить нам помилки в коді, але ніколи не пробачить легковажності перед обличчям надінтелекту».", "source": "Мастер-Досьє"}, {"num": 85, "cat": "Етика та безпека ШІ", "text": "«Коли ми будуємо архітектуру безпеки, ми будуємо дім, у якому житимуть наші діти».", "source": "Мастер-Досьє"}, {"num": 86, "cat": "Походження та гарт", "text": "«Академічні інститути мають отримати державне фінансування для проведення незалежних аудитів комерційних моделей».", "source": "Мастер-Досьє"}, {"num": 87, "cat": "Філософія майбутнього", "text": "«Коли моделі допомагають розгадувати таємниці клітин, ми відчуваємо велич пізнання».", "source": "Мастер-Досьє"}, {"num": 88, "cat": "Етика та безпека ШІ", "text": "«Кожен новий крок у масштабуванні вимагає пропорційного збільшення зусиль у сфері вирівнювання».", "source": "Мастер-Досьє"}, {"num": 89, "cat": "Філософія майбутнього", "text": "«Ми прагнемо створити суспільство, де технології виконують чорнову роботу, а люди реалізують свій творчий потенціал».", "source": "Мастер-Досьє"}, {"num": 90, "cat": "Етика та безпека ШІ", "text": "«Коли вчені відкрито говорять про страхи, вони демонструють зрілість і турботу про спільний дім».", "source": "Мастер-Досьє"}, {"num": 91, "cat": "Походження та гарт", "text": "«Математика пропонує нам точний інструмент вимірювання невизначеності, якою не можна нехтувати».", "source": "Мастер-Досьє"}, {"num": 92, "cat": "Філософія майбутнього", "text": "«Коли ми заснували Mila, ми мріяли про світ, де знання належать усім людям без винятку».", "source": "Мастер-Досьє"}, {"num": 93, "cat": "Етика та безпека ШІ", "text": "«Етичний стандарт розробника має бути вищим за будь-які комерційні бонуси чи інвестиційні раунди».", "source": "Мастер-Досьє"}, {"num": 94, "cat": "Етика та безпека ШІ", "text": "«Коли моделі досягають рівня розуміння складних систем, ми маємо забезпечити їхню повну безпеку».", "source": "Мастер-Досьє"}, {"num": 95, "cat": "Етика та безпека ШІ", "text": "«Природа створила нас уразливими, але дала розум, здатний захистити життя від будь-яких загроз».", "source": "Мастер-Досьє"}, {"num": 96, "cat": "Етика та безпека ШІ", "text": "«Коли ми дивимося на майбутнє, ми бачимо вибір між мудрістю співпраці та хаосом неконтрольованої сили».", "source": "Мастер-Досьє"}, {"num": 97, "cat": "Філософія майбутнього", "text": "«Наука врятує світ лише тоді, коли вона керуватиметься любов'ю до людини, а не жагою панування».", "source": "Мастер-Досьє"}, {"num": 98, "cat": "Етика та безпека ШІ", "text": "«Кожен рядок нашого коду спрямований на те, щоб зберегти людство у світлому і безпечному майбутньому».", "source": "Мастер-Досьє"}, {"num": 99, "cat": "Філософія майбутнього", "text": "«Коли ми закінчимо нашу місію, світ має стати чистішим, розумнішим і добрішим завдяки нашому внеску».", "source": "Мастер-Досьє"}, {"num": 100, "cat": "Походження та гарт", "text": "«Усе починається з університету, де професор каже студенту: шукай істину і ніколи не бійся захищати життя».", "source": "Мастер-Досьє"}]}, {"id": "10_ng", "ep": "10", "name": "Ендрю Ин", "latin": "Andrew Ng", "page_url": "episodes/ep10_ng.html", "avatar": "assets/avatars/andrew_ng.jpg", "quotes_100": [{"num": 1, "cat": "Філософія майбутнього", "text": "«Штучний інтелект — це нова електрика. Подібно до того, як електрика сто років тому трансформувала кожну галузь, ШІ сьогодні змінює суспільство».", "source": "Мастер-Досьє"}, {"num": 2, "cat": "Походження та гарт", "text": "«У дитинстві в Сінгапурі я писав свої перші програми на мікрокомп'ютерах із журналів, мріючи про день, коли машини зможуть бачити і вчитися».", "source": "Мастер-Досьє"}, {"num": 3, "cat": "Лідерство та екосистема", "text": "«Освіта має бути відкритою і доступною для кожної людини на Землі, незалежно від її географічного чи фінансового становища».", "source": "Мастер-Досьє"}, {"num": 4, "cat": "Походження та гарт", "text": "«Коли ми створювали Coursera у 2011 році, наша мета була простою: дати можливість будь-якому підлітку в глибинці здобути освіту рівня найкращих університетів світу».", "source": "Мастер-Досьє"}, {"num": 5, "cat": "Походження та гарт", "text": "«У Стенфорді ми завжди навчали студентів головного правилу: почніть із простих моделей, перевірте дані і лише потім будуйте складні архітектури».", "source": "Мастер-Досьє"}, {"num": 6, "cat": "Архітектура та наука", "text": "«Експеримент Google Brain з розпізнаванням котів у 2011 році довів: неструктуровані дані з інтернету містять у собі закономірності, які мережа здатна знайти самостійно».", "source": "Мастер-Досьє"}, {"num": 7, "cat": "Філософія майбутнього", "text": "«Ділитись знаннями — це найблагородніша інвестиція в майбутнє нашої цивілізації».", "source": "Мастер-Досьє"}, {"num": 8, "cat": "Лідерство та екосистема", "text": "«Коли я очолював AI в Baidu, я бачив, як швидке впровадження технологій у традиційний бізнес змінює мільйони робочих процесів».", "source": "Мастер-Досьє"}, {"num": 9, "cat": "Архітектура та наука", "text": "«Data-Centric AI — це парадигмальний зсув: замість того, щоб нескінченно крутити гіперпараметри моделі, зафіксуйте код і зосередьтеся на покращенні якості даних».", "source": "Мастер-Досьє"}, {"num": 10, "cat": "Лідерство та екосистема", "text": "«Складний відсоток працює для людських знань точно так само, як і для капіталу: щодня вивчайте щось нове, і за рік ви станете іншою людиною».", "source": "Мастер-Досьє"}, {"num": 11, "cat": "Філософія майбутнього", "text": "«ШІ не замінить людей, але люди, які використовують ШІ, замінять тих, хто його не використовує».", "source": "Мастер-Досьє"}, {"num": 12, "cat": "Етика та безпека ШІ", "text": "«Кожен інженер має пам'ятати про етичну сторону своєї роботи: технології мають розширювати можливості людей, а не утискати їх».", "source": "Мастер-Досьє"}, {"num": 13, "cat": "Лідерство та екосистема", "text": "«Мій перехід від академічних досліджень до створення масових освітніх платформ був усвідомленим кроком до демократизації знань».", "source": "Мастер-Досьє"}, {"num": 14, "cat": "Походження та гарт", "text": "«Не бійтеся починати з нуля у новій сфері; цікавість і систематична праця долають будь-яку відстань».", "source": "Мастер-Досьє"}, {"num": 15, "cat": "Лідерство та екосистема", "text": "«AI Fund створює компанії, які вирішують реальні прикладні проблеми у сфері охорони здоров'я, логістики та освіти».", "source": "Мастер-Досьє"}, {"num": 16, "cat": "Філософія майбутнього", "text": "«Коли ми бачимо успіх наших випускників на DeepLearning.AI, ми розуміємо, що місія виконується щодня».", "source": "Мастер-Досьє"}, {"num": 17, "cat": "Архітектура та наука", "text": "«Архітектура моделі вторинна порівняно з чистотою та розмірністю датасету, на якому вона навчається».", "source": "Мастер-Досьє"}, {"num": 18, "cat": "Походження та гарт", "text": "«Сінгапурська школа заклала в мене міцний фундамент дисципліни, точності та поваги до точних наук».", "source": "Мастер-Досьє"}, {"num": 19, "cat": "Походження та гарт", "text": "«Кожен новий студент, який написав свій перший рядок коду на Python, стає співавтором нашого спільного цифрового майбутнього».", "source": "Мастер-Досьє"}, {"num": 20, "cat": "Лідерство та екосистема", "text": "«Ми маємо підготувати малий і середній бізнес до використання ШІ, інакше технологічна прірва стане занадто глибокою».", "source": "Мастер-Досьє"}, {"num": 21, "cat": "Кризи та стійкість", "text": "«Коли криза ставить перед тобою стіну, розбий її на маленькі навчальні модулі і пройди їх крок за кроком».", "source": "Мастер-Досьє"}, {"num": 22, "cat": "Архітектура та наука", "text": "«Найкращий спосіб навчитися будувати складні системи — це розібрати на деталі роботу простих базових алгоритмів».", "source": "Мастер-Досьє"}, {"num": 23, "cat": "Філософія майбутнього", "text": "«Успіх у технологіях вимірюється не кількістю патентів у шухляді, а кількістю розв'язаних реальних проблем користувачів».", "source": "Мастер-Досьє"}, {"num": 24, "cat": "Філософія майбутнього", "text": "«Ми створюємо інструменти, які знімають з людей рутину, вивільняючи час для творчості та спілкування».", "source": "Мастер-Досьє"}, {"num": 25, "cat": "Походження та гарт", "text": "«Коли ми досліджували можливості робототехніки у Стенфорді (проєкт STAIR), ми зрозуміли, що роботам бракує здорового глузду».", "source": "Мастер-Досьє"}, {"num": 26, "cat": "Філософія майбутнього", "text": "«Кожен день приносить нові можливості для інновацій, якщо ви зберігаєте гнучкість мислення».", "source": "Мастер-Досьє"}, {"num": 27, "cat": "Етика та безпека ШІ", "text": "«Ми маємо відмовитися від страху перед новими технологіями через прозоре і зрозуміле навчання суспільства».", "source": "Мастер-Досьє"}, {"num": 28, "cat": "Лідерство та екосистема", "text": "«Ефективність команди залежить від того, наскільки швидко її учасники можуть обмінюватися чесною конструктивною критикою».", "source": "Мастер-Досьє"}, {"num": 29, "cat": "Філософія майбутнього", "text": "«Коли ти керуєш великою організацією, твоя головна задача — розчищати шлях для талановитих інженерів».", "source": "Мастер-Досьє"}, {"num": 30, "cat": "Філософія майбутнього", "text": "«Машинне навчання є настільки потужним, що його принципи можуть покращити майже будь-яку наукову дисципліну».", "source": "Мастер-Досьє"}, {"num": 31, "cat": "Лідерство та екосистема", "text": "«Коли ми запускали перші курси на Coursera, критики казали, що онлайн-освіта ніколи не замінить аудиторії. Вони помилилися».", "source": "Мастер-Досьє"}, {"num": 32, "cat": "Філософія майбутнього", "text": "«Технологічний оптимізм має підкріплюватися щоденною наполегливою працею над якістю кожного продукту».", "source": "Мастер-Досьє"}, {"num": 33, "cat": "Філософія майбутнього", "text": "«Коли ми працювали в Google Brain, ми поєднали величезні ресурси з духом вільного академічного пошуку».", "source": "Мастер-Досьє"}, {"num": 34, "cat": "Лідерство та екосистема", "text": "«Немає нічого сильнішого за спільну пристрасть команди, яка вірить у те, що змінює світ на краще».", "source": "Мастер-Досьє"}, {"num": 35, "cat": "Філософія майбутнього", "text": "«Ми маємо навчати роботів діяти в умовах неповних даних, спираючись на ймовірнісні моделі».", "source": "Мастер-Досьє"}, {"num": 36, "cat": "Філософія майбутнього", "text": "«Коли ми говоримо про демократизацію ШІ, ми маємо на увазі створення інструментів, якими може користуватися кожен».", "source": "Мастер-Досьє"}, {"num": 37, "cat": "Лідерство та екосистема", "text": "«Принципи Data-Centric AI економлять мільйони доларів і місяці роботи тисячам компаній у всьому світі».", "source": "Мастер-Досьє"}, {"num": 38, "cat": "Походження та гарт", "text": "«Коли студент пише мені, що курс змінив його життя і допоміг знайти роботу, це надихає сильніше за будь-які нагороди».", "source": "Мастер-Досьє"}, {"num": 39, "cat": "Кризи та стійкість", "text": "«Ми маємо підтримувати культуру експериментів, де право на помилку є частиною процесу пошуку істини».", "source": "Мастер-Досьє"}, {"num": 40, "cat": "Лідерство та екосистема", "text": "«Коли технології розвиваються так стрімко, здатність до самоосвіти стає найціннішою навичкою XXI століття».", "source": "Мастер-Досьє"}, {"num": 41, "cat": "Філософія майбутнього", "text": "«Кожен новий інструмент генеративного ШІ робить поріг входження в розробку нижчим для мільйонів людей».", "source": "Мастер-Досьє"}, {"num": 42, "cat": "Філософія майбутнього", "text": "«Ми прагнемо побудувати екосистему, де венчурні інвестиції йдуть на користь корисним суспільним проєктам».", "source": "Мастер-Досьє"}, {"num": 43, "cat": "Походження та гарт", "text": "«Коли ми аналізуємо ринки, ми шукаємо галузі, які застрягли в минулому і потребують термінової автоматизації».", "source": "Мастер-Досьє"}, {"num": 44, "cat": "Архітектура та наука", "text": "«Справжній інноватор не чекає на досконалі умови; він бере наявні дані і будує першу працюючу версію».", "source": "Мастер-Досьє"}, {"num": 45, "cat": "Етика та безпека ШІ", "text": "«Ми маємо виховувати відповідальних лідерів, які розуміють і комерційну, і соціальну цінність своєї праці».", "source": "Мастер-Досьє"}, {"num": 46, "cat": "Лідерство та екосистема", "text": "«Коли ми заснували AI Fund, ми хотіли перетворити ідеї на робочі компанії за лічені тижні».", "source": "Мастер-Досьє"}, {"num": 47, "cat": "Архітектура та наука", "text": "«Природа створила неймовірні механізми адаптації, які ми намагаємося відтворити в алгоритмах оптимізації».", "source": "Мастер-Досьє"}, {"num": 48, "cat": "Походження та гарт", "text": "«Коли студент долає перші труднощі в математиці, у нього відкривається зовсім інше бачення власних сил».", "source": "Мастер-Досьє"}, {"num": 49, "cat": "Філософія майбутнього", "text": "«Ми маємо зробити так, щоб переваги штучного інтелекту відчули не лише мегаполіси, а й найвіддаленіші куточки планети».", "source": "Мастер-Досьє"}, {"num": 50, "cat": "Філософія майбутнього", "text": "«Кожен успішний проєкт починається з простої і чесної відповіді на запитання: яку проблему ми вирішуємо?».", "source": "Мастер-Досьє"}, {"num": 51, "cat": "Походження та гарт", "text": "«Коли ми дивимося на розвиток індустрії, ми бачимо перехід від загального галасу до прагматичного вирішення завдань».", "source": "Мастер-Досьє"}, {"num": 52, "cat": "Лідерство та екосистема", "text": "«Ми маємо поєднувати глибокі технічні знання з гнучкістю бізнес-мислення».", "source": "Мастер-Досьє"}, {"num": 53, "cat": "Архітектура та наука", "text": "«Коли модель дає збій, ми не звинувачуємо алгоритм — ми йдемо перевіряти мітку в датасеті».", "source": "Мастер-Досьє"}, {"num": 54, "cat": "Філософія майбутнього", "text": "«Свобода творчості в інженерії базується на міцному засвоєнні базових законів лінійної алгебри та статистики».", "source": "Мастер-Досьє"}, {"num": 55, "cat": "Походження та гарт", "text": "«Коли ми створювали матеріали для DeepLearning.AI, ми прагнули зробити складну математику доступною для кожного».", "source": "Мастер-Досьє"}, {"num": 56, "cat": "Філософія майбутнього", "text": "«Технології мають звільняти час для родини, спілкування та пізнання світу, а не перетворювати життя на офісне рабство».", "source": "Мастер-Досьє"}, {"num": 57, "cat": "Походження та гарт", "text": "«Коли ми бачимо, як малий бізнес автоматизує рутину за допомогою ШІ, ми бачимо реальну користь нашої праці».", "source": "Мастер-Досьє"}, {"num": 58, "cat": "Архітектура та наука", "text": "«Ми маємо бути відкритими до зворотного зв'язку і готовими змінювати курс щоразу, коли з'являються нові дані».", "source": "Мастер-Досьє"}, {"num": 59, "cat": "Кризи та стійкість", "text": "«Коли інженер закохується в ідею, а не в проблему клієнта, проєкт приречений на провал».", "source": "Мастер-Досьє"}, {"num": 60, "cat": "Філософія майбутнього", "text": "«Ми прагнемо створити світ, де кожен може стати творцем власних технологічних рішень».", "source": "Мастер-Досьє"}, {"num": 61, "cat": "Філософія майбутнього", "text": "«Коли ми аналізуємо ефективність навчання, ми бачимо, що короткі практичні проєкти працюють краще за довгі лекції».", "source": "Мастер-Досьє"}, {"num": 62, "cat": "Кризи та стійкість", "text": "«Кожен новий рік роботи в ШІ приносить більше змін, ніж попереднє десятиліття».", "source": "Мастер-Досьє"}, {"num": 63, "cat": "Філософія майбутнього", "text": "«Ми маємо навчати моделі не просто відповідати, а перевіряти достовірність власних джерел».", "source": "Мастер-Досьє"}, {"num": 64, "cat": "Походження та гарт", "text": "«Коли ми об'єднуємо зусилля з іншими викладачами, ми створюємо глобальний університет майбутнього».", "source": "Мастер-Досьє"}, {"num": 65, "cat": "Філософія майбутнього", "text": "«Істинна цінність платформ на кшталт Coursera полягає у зміні доль мільйонів людей через знання».", "source": "Мастер-Досьє"}, {"num": 66, "cat": "Філософія майбутнього", "text": "«Коли ми працювали над розпізнаванням об'єктів, ми розуміли межі того, що може зробити комп'ютерний зір».", "source": "Мастер-Досьє"}, {"num": 67, "cat": "Філософія майбутнього", "text": "«Ми маємо розвивати інтуїцію щодо даних, бо жодна формула не замінить досвіду роботи з реальними масивами».", "source": "Мастер-Досьє"}, {"num": 68, "cat": "Філософія майбутнього", "text": "«Коли ми підтримуємо підприємців через AI Fund, ми допомагаємо їм пройти найскладніший нульовий етап».", "source": "Мастер-Досьє"}, {"num": 69, "cat": "Філософія майбутнього", "text": "«Технологічний прогрес є неминучим, але його напрямок визначаємо ми своєю щоденною працею».", "source": "Мастер-Досьє"}, {"num": 70, "cat": "Походження та гарт", "text": "«Коли студент розуміє суть градієнтного спуску, перед ним відкривається магія всього машинного навчання».", "source": "Мастер-Досьє"}, {"num": 71, "cat": "Архітектура та наука", "text": "«Ми маємо прагнути до простоти в коді і прозорості в комунікації з командою».", "source": "Мастер-Досьє"}, {"num": 72, "cat": "Архітектура та наука", "text": "«Коли ми запускали нові курси, ми завжди тестували їх на людях, які ніколи раніше не кодили».", "source": "Мастер-Досьє"}, {"num": 73, "cat": "Архітектура та наука", "text": "«Принципи Data-Centric AI дозволяють економити ресурси планети завдяки ефективній роботі з меншими датасетами».", "source": "Мастер-Досьє"}, {"num": 74, "cat": "Лідерство та екосистема", "text": "«Коли ми дивимося на майбутнє, ми бачимо глибоку інтеграцію ШІ в усі освітні стандарти світу».", "source": "Мастер-Досьє"}, {"num": 75, "cat": "Філософія майбутнього", "text": "«Ми маємо захищати приватність користувачів і будувати безпечні системи з першого дня розробки».", "source": "Мастер-Досьє"}, {"num": 76, "cat": "Кризи та стійкість", "text": "«Коли інженер фокусується на головному, він встигає зробити за місяць більше, ніж інші за рік».", "source": "Мастер-Досьє"}, {"num": 77, "cat": "Філософія майбутнього", "text": "«Ми віримо у світ, де технологічний бар'єр між людьми стає мінімальним завдяки зручним інтерфейсам».", "source": "Мастер-Досьє"}, {"num": 78, "cat": "Філософія майбутнього", "text": "«Коли ми вивчали нейрони у Берклі, ми закладали основу для нашого сьогоднішнього розуміння архітектур».", "source": "Мастер-Досьє"}, {"num": 79, "cat": "Лідерство та екосистема", "text": "«Кожен успішний лідер колись був новачком, який боявся запитати про очевидні речі».", "source": "Мастер-Досьє"}, {"num": 80, "cat": "Лідерство та екосистема", "text": "«Ми маємо підтримувати культуру постійного оновлення знань усередині кожної компанії».", "source": "Мастер-Досьє"}, {"num": 81, "cat": "Архітектура та наука", "text": "«Коли ми створювали Google Brain, ми довели, що масштаб обчислень здатний творити дива».", "source": "Мастер-Досьє"}, {"num": 82, "cat": "Філософія майбутнього", "text": "«Технології мають служити містком між різними культурами та економіками світу».", "source": "Мастер-Досьє"}, {"num": 83, "cat": "Кризи та стійкість", "text": "«Коли модель працює стабільно на тестах, але падає в продакшені — шукайте розбіжність у даних».", "source": "Мастер-Досьє"}, {"num": 84, "cat": "Філософія майбутнього", "text": "«Ми маємо виховувати покоління творців, які не бояться глобальних викликів».", "source": "Мастер-Досьє"}, {"num": 85, "cat": "Філософія майбутнього", "text": "«Коли ти бачиш гарячі очі слухачів у залі, ти розумієш силу натхненного слова».", "source": "Мастер-Досьє"}, {"num": 86, "cat": "Етика та безпека ШІ", "text": "«Ми прагнемо побудувати інфраструктуру, яка прискорить перехід людства до сталого розвитку».", "source": "Мастер-Досьє"}, {"num": 87, "cat": "Філософія майбутнього", "text": "«Коли закони інформації зустрічаються з підприємництвом, народжуються нові глобальні ринки».", "source": "Мастер-Досьє"}, {"num": 88, "cat": "Філософія майбутнього", "text": "«Ми маємо поважати час користувачів і створювати швидкі, надійні та корисні рішення».", "source": "Мастер-Досьє"}, {"num": 89, "cat": "Філософія майбутнього", "text": "«Коли ми аналізуємо тенденції, ми бачимо, що майбутнє належить тим, хто швидко адаптується».", "source": "Мастер-Досьє"}, {"num": 90, "cat": "Кризи та стійкість", "text": "«Кожен рядок якісного коду — це внесок у стабільність нашого спільного цифрового простору».", "source": "Мастер-Досьє"}, {"num": 91, "cat": "Філософія майбутнього", "text": "«Ми маємо захищати авторські права та чесну винагороду для творців контенту в епоху ШІ».", "source": "Мастер-Досьє"}, {"num": 92, "cat": "Лідерство та екосистема", "text": "«Коли ми створюємо венчурні компанії, ми шукаємо команду з бездоганною чесністю та енергією».", "source": "Мастер-Досьє"}, {"num": 93, "cat": "Філософія майбутнього", "text": "«Технологічний підйом вимагає від нас мудрості у розподілі багатств і благ».", "source": "Мастер-Досьє"}, {"num": 94, "cat": "Походження та гарт", "text": "«Коли студент долає страх перед штучним інтелектом, він стає архіпелагом нових можливостей».", "source": "Мастер-Досьє"}, {"num": 95, "cat": "Філософія майбутнього", "text": "«Ми маємо прагнути до досконалості в продуктах, не забуваючи про турботу одне про одного».", "source": "Мастер-Досьє"}, {"num": 96, "cat": "Лідерство та екосистема", "text": "«Коли ми дивимося на нові горизонти, ми знаємо, що найкращі відкриття ще попереду».", "source": "Мастер-Досьє"}, {"num": 97, "cat": "Походження та гарт", "text": "«Ми створюємо фундамент для епохи, де кожна людина матиме персонального штучного помічника».", "source": "Мастер-Досьє"}, {"num": 98, "cat": "Філософія майбутнього", "text": "«Кожен день роботи з даними нагадує мені про неймовірну складність та красу реального світу».", "source": "Мастер-Досьє"}, {"num": 99, "cat": "Кризи та стійкість", "text": "«Ми маємо ділитися знаннями відкрито, бо ізоляція вбиває будь-яку інновацію».", "source": "Мастер-Досьє"}, {"num": 100, "cat": "Лідерство та екосистема", "text": "«Усе починається з маленького курсу, однієї мрії і людини, яка повірила, що може змінити своє життя».", "source": "Мастер-Досьє"}]}];
